--
-- Name: hat_sicht(uuid, text, text); Type: FUNCTION; Schema: coach; Owner: postgres
--

CREATE FUNCTION coach.hat_sicht(p_client uuid, p_modul text, p_stufe text DEFAULT 'full'::text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM coach.client_permissions p
    WHERE p.coach_id = (SELECT auth.uid())
      AND p.client_id = p_client
      AND (p.expires_at IS NULL OR p.expires_at > now())
      AND (
        CASE p_modul
          WHEN 'nutrition'   THEN p.nutrition_visibility
          WHEN 'training'    THEN p.training_visibility
          WHEN 'recovery'    THEN p.recovery_visibility
          WHEN 'goals'       THEN p.goals_visibility
          WHEN 'supplements' THEN p.supplements_visibility
          WHEN 'medical'     THEN p.medical_visibility
          WHEN 'buddy'       THEN p.buddy_visibility
        END
      ) = ANY (
        CASE WHEN p_stufe = 'full'
          THEN ARRAY['full']
          ELSE ARRAY['summary', 'full']
        END
      )
  );
$$;


ALTER FUNCTION coach.hat_sicht(p_client uuid, p_modul text, p_stufe text) OWNER TO postgres;

--
-- Name: FUNCTION hat_sicht(p_client uuid, p_modul text, p_stufe text); Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON FUNCTION coach.hat_sicht(p_client uuid, p_modul text, p_stufe text) IS 'Die eine Stelle der Sichtpruefung: hat der angemeldete Coach fuer diesen Klienten in diesem Modul mindestens diese Stufe? Beachtet expires_at.';


--
-- Name: klienten(); Type: FUNCTION; Schema: coach; Owner: postgres
--

CREATE FUNCTION coach.klienten() RETURNS TABLE(relationship_id uuid, client_id uuid, status text, started_at timestamp with time zone, invited_at timestamp with time zone, invite_note text, email text, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    r.id,
    r.client_id,
    r.status,
    r.started_at,
    r.created_at,
    r.invite_note,
    u.email::text,
    COALESCE(u.raw_app_meta_data->>'full_name', split_part(u.email::text, '@', 1))
  FROM coach.relationships r
  JOIN auth.users u ON u.id = r.client_id
  WHERE r.coach_id = (SELECT auth.uid());
$$;


ALTER FUNCTION coach.klienten() OWNER TO postgres;

--
-- Name: FUNCTION klienten(); Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON FUNCTION coach.klienten() IS 'Beziehungen des angemeldeten Coaches mit E-Mail und Anzeigenamen. DEFINER nur fuer den auth.users-Join; die WHERE-Klausel bindet an auth.uid().';


