-- Name: log_autonomy_change(); Type: FUNCTION; Schema: coach; Owner: postgres
--

CREATE FUNCTION coach.log_autonomy_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO coach.autonomy_change_log (
    autonomy_id, coach_id, client_id, changed_by, change_kind, old_value, new_value
  )
  VALUES (
    COALESCE(NEW.id, OLD.id),
    COALESCE(NEW.coach_id, OLD.coach_id),
    COALESCE(NEW.client_id, OLD.client_id),
    COALESCE(auth.uid(), NEW.changed_by, OLD.changed_by),
    lower(TG_OP),
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION coach.log_autonomy_change() OWNER TO postgres;

