--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_cron_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


ALTER FUNCTION extensions.grant_pg_graphql_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

    REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
    REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

    GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_net_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_ddl_watch() OWNER TO supabase_admin;

--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_drop_watch() OWNER TO supabase_admin;

--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


ALTER FUNCTION extensions.set_graphql_placeholder() OWNER TO supabase_admin;

--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: adaptive_tdee(uuid, date, integer); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.adaptive_tdee(p_user_id uuid, p_stichtag date DEFAULT CURRENT_DATE, p_window_days integer DEFAULT 14) RETURNS TABLE(user_id uuid, period_start date, period_end date, window_days integer, complete_intake_days integer, weight_measurement_count integer, weight_start_kg numeric, weight_end_kg numeric, weight_delta_kg numeric, measurement_span_days integer, avg_intake_kcal numeric, formula_tdee_kcal numeric, raw_tdee_kcal numeric, adaptive_tdee_kcal numeric, delta_to_formula_kcal numeric, confidence text, reliable boolean, status text, source text, method text, alpha numeric, kcal_per_kg numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH params AS (
  SELECT
    p_user_id AS user_id,
    p_stichtag AS period_end,
    GREATEST(p_window_days, 1)::integer AS window_days,
    (p_stichtag - (GREATEST(p_window_days, 1)::integer - 1))::date AS period_start,
    1.0::numeric AS alpha,
    7700::numeric AS kcal_per_kg
),
intake AS (
  SELECT
    count(*) FILTER (WHERE ds.enercc IS NOT NULL AND ds.enercc_missing = 0)::integer AS complete_intake_days,
    avg(ds.enercc) FILTER (WHERE ds.enercc IS NOT NULL AND ds.enercc_missing = 0)::numeric AS avg_intake_kcal
  FROM params p
  LEFT JOIN nutrition.daily_summary ds
    ON ds.user_id = p.user_id
   AND ds.entry_date BETWEEN p.period_start AND p.period_end
),
weights AS (
  SELECT
    count(bm.*)::integer AS weight_measurement_count,
    (array_agg(bm.weight_kg ORDER BY bm.measurement_date, bm.measurement_time, bm.created_at, bm.id))[1]::numeric AS weight_start_kg,
    (array_agg(bm.weight_kg ORDER BY bm.measurement_date DESC, bm.measurement_time DESC, bm.created_at DESC, bm.id DESC))[1]::numeric AS weight_end_kg,
    min(bm.measurement_date)::date AS first_weight_date,
    max(bm.measurement_date)::date AS last_weight_date
  FROM params p
  LEFT JOIN goals.body_measurements bm
    ON bm.user_id = p.user_id
   AND bm.measurement_date BETWEEN p.period_start AND p.period_end
   AND bm.weight_kg IS NOT NULL
),
formula AS (
  SELECT bz.tdee AS formula_tdee_kcal
  FROM params p
  LEFT JOIN LATERAL goals.berechne_zielwerte(p.user_id, p.period_end) bz ON true
),
calc AS (
  SELECT
    p.user_id,
    p.period_start,
    p.period_end,
    p.window_days,
    COALESCE(i.complete_intake_days, 0) AS complete_intake_days,
    COALESCE(w.weight_measurement_count, 0) AS weight_measurement_count,
    w.weight_start_kg,
    w.weight_end_kg,
    CASE WHEN w.weight_start_kg IS NULL OR w.weight_end_kg IS NULL
      THEN NULL
      ELSE round((w.weight_end_kg - w.weight_start_kg)::numeric, 3)
    END AS weight_delta_kg,
    CASE WHEN w.first_weight_date IS NULL OR w.last_weight_date IS NULL
      THEN NULL
      ELSE GREATEST((w.last_weight_date - w.first_weight_date), 1)
    END AS measurement_span_days,
    round(i.avg_intake_kcal, 1) AS avg_intake_kcal,
    f.formula_tdee_kcal,
    p.alpha,
    p.kcal_per_kg
  FROM params p
  CROSS JOIN intake i
  CROSS JOIN weights w
  CROSS JOIN formula f
)
SELECT
  c.user_id,
  c.period_start,
  c.period_end,
  c.window_days,
  c.complete_intake_days,
  c.weight_measurement_count,
  c.weight_start_kg,
  c.weight_end_kg,
  c.weight_delta_kg,
  c.measurement_span_days,
  c.avg_intake_kcal,
  c.formula_tdee_kcal,
  CASE WHEN c.complete_intake_days >= c.window_days
      AND c.weight_measurement_count >= 2
      AND c.measurement_span_days >= c.window_days - 1
    THEN round((c.avg_intake_kcal - (c.weight_delta_kg * c.kcal_per_kg / c.measurement_span_days))::numeric, 1)
    ELSE NULL
  END AS raw_tdee_kcal,
  CASE WHEN c.complete_intake_days >= c.window_days
      AND c.weight_measurement_count >= 2
      AND c.measurement_span_days >= c.window_days - 1
      AND c.formula_tdee_kcal IS NOT NULL
    THEN round((
      c.alpha * (c.avg_intake_kcal - (c.weight_delta_kg * c.kcal_per_kg / c.measurement_span_days))
      + (1 - c.alpha) * c.formula_tdee_kcal
    )::numeric, 1)
    ELSE NULL
  END AS adaptive_tdee_kcal,
  CASE WHEN c.complete_intake_days >= c.window_days
      AND c.weight_measurement_count >= 2
      AND c.measurement_span_days >= c.window_days - 1
      AND c.formula_tdee_kcal IS NOT NULL
    THEN round((
      c.alpha * (c.avg_intake_kcal - (c.weight_delta_kg * c.kcal_per_kg / c.measurement_span_days))
      + (1 - c.alpha) * c.formula_tdee_kcal
      - c.formula_tdee_kcal
    )::numeric, 1)
    ELSE NULL
  END AS delta_to_formula_kcal,
  CASE
    WHEN c.complete_intake_days >= c.window_days AND c.weight_measurement_count >= 7 THEN 'high'
    WHEN c.complete_intake_days >= c.window_days AND c.weight_measurement_count >= 2 THEN 'medium'
    ELSE 'low'
  END AS confidence,
  (c.complete_intake_days >= c.window_days
    AND c.weight_measurement_count >= 2
    AND c.measurement_span_days >= c.window_days - 1
    AND c.formula_tdee_kcal IS NOT NULL) AS reliable,
  CASE
    WHEN c.formula_tdee_kcal IS NULL THEN 'missing_profile'
    WHEN c.complete_intake_days < c.window_days THEN 'insufficient_intake_days'
    WHEN c.weight_measurement_count < 2 THEN 'insufficient_weight_measurements'
    WHEN c.measurement_span_days < c.window_days - 1 THEN 'insufficient_weight_span'
    ELSE 'complete'
  END AS status,
  'derived_adaptive_tdee'::text AS source,
  'rolling_14d_intake_weight_delta_alpha_1_formula_baseline'::text AS method,
  c.alpha,
  c.kcal_per_kg
FROM calc c;
$$;


ALTER FUNCTION goals.adaptive_tdee(p_user_id uuid, p_stichtag date, p_window_days integer) OWNER TO postgres;

--
-- Name: FUNCTION adaptive_tdee(p_user_id uuid, p_stichtag date, p_window_days integer); Type: COMMENT; Schema: goals; Owner: postgres
--

COMMENT ON FUNCTION goals.adaptive_tdee(p_user_id uuid, p_stichtag date, p_window_days integer) IS 'Adaptiver TDEE aus tatsaechlicher Kalorienzufuhr und Gewichtsentwicklung. Alpha ist 1.0; der Formelwert bleibt als Baseline erhalten.';


--
-- Name: berechne_zielwerte(uuid, date); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.berechne_zielwerte(p_user_id uuid, p_stichtag date DEFAULT CURRENT_DATE) RETURNS TABLE(bmr numeric, tdee numeric, kcal numeric, protein_g numeric, carbs_g numeric, fat_g numeric, linoleic_acid_g numeric, alpha_linolenic_acid_g numeric, nutrition_goal text, kalorienfaktor numeric, hindernis text, fehlende_felder text[])
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH profil AS (
  SELECT
    p.birth_date,
    p.biological_sex,
    p.height_cm,
    p.body_weight_kg,
    p.activity_level,
    p.nutrition_goal,
    -- age() beruecksichtigt Monat und Tag, anders als der Vorgaenger.
    CASE WHEN p.birth_date IS NULL THEN NULL
         ELSE EXTRACT(YEAR FROM age(p_stichtag, p.birth_date))::INTEGER
    END AS alter_jahre
  FROM public.profiles p
  WHERE p.id = p_user_id
),
-- Genau eine Zeile, auch wenn es kein Profil gibt.
profil_eins AS (
  SELECT
    pr.birth_date, pr.biological_sex, pr.height_cm, pr.body_weight_kg,
    pr.activity_level, pr.nutrition_goal, pr.alter_jahre,
    ARRAY_REMOVE(ARRAY[
      CASE WHEN pr.birth_date     IS NULL THEN 'birth_date'     END,
      CASE WHEN pr.biological_sex IS NULL THEN 'biological_sex' END,
      CASE WHEN pr.height_cm      IS NULL THEN 'height_cm'      END,
      CASE WHEN pr.body_weight_kg IS NULL THEN 'body_weight_kg' END,
      CASE WHEN pr.activity_level IS NULL THEN 'activity_level' END,
      CASE WHEN pr.nutrition_goal IS NULL THEN 'nutrition_goal' END
    ], NULL) AS fehlend
  FROM (SELECT 1) seed
  LEFT JOIN profil pr ON true
),
faktoren AS (
  -- Die fuenf Stufen aus SCORING.md, wertgleich mit useTDEE.ts.
  SELECT * FROM (VALUES
    ('sedentary',   1.200::NUMERIC),
    ('light',       1.375),
    ('moderate',    1.550),
    ('active',      1.725),
    ('very_active', 1.900)
  ) AS f(stufe, faktor)
),
zuschlaege AS (
  -- Aus daten/zielrichtung-kalorienzuschlag.json. 'health' fehlt
  -- absichtlich: der Vorgaenger kennt die Zielrichtung nicht, und
  -- 0 waere eine stille Entscheidung.
  SELECT * FROM (VALUES
    ('lose_weight',   -0.20::NUMERIC),
    ('maintain',       0.00),
    ('gain_muscle',    0.10),
    ('recomposition',  0.00),
    ('performance',    0.10)
  ) AS z(ziel, faktor)
),
gerechnet AS (
  SELECT
    p.*,
    f.faktor AS akt_faktor,
    z.faktor AS ziel_faktor,
    -- Mifflin-St Jeor.
    CASE
      WHEN p.body_weight_kg IS NULL OR p.height_cm IS NULL
        OR p.alter_jahre IS NULL OR p.biological_sex IS NULL THEN NULL
      ELSE ROUND(
        10 * p.body_weight_kg + 6.25 * p.height_cm - 5 * p.alter_jahre
        + CASE WHEN p.biological_sex = 'male' THEN 5 ELSE -161 END, 1)
    END AS bmr_wert
  FROM profil_eins p
  LEFT JOIN faktoren   f ON f.stufe = p.activity_level
  LEFT JOIN zuschlaege z ON z.ziel  = p.nutrition_goal
),
abgeleitet AS (
  SELECT
    g.*,
    ROUND(g.bmr_wert * g.akt_faktor, 1) AS tdee_wert,
    ROUND(g.bmr_wert * g.akt_faktor * (1 + g.ziel_faktor), 1) AS kcal_wert
  FROM gerechnet g
),
makros AS (
  SELECT
    a.*,
    -- Protein: 2 g je kg. Beide Vorgaengerdateien sind sich einig.
    ROUND(a.body_weight_kg * 2, 1) AS protein_wert,
    -- Fett: 25 % der Zielkalorien, geteilt durch 9 kcal/g.
    ROUND(a.kcal_wert * 0.25 / 9, 1) AS fett_wert,
    -- C-52: EFSA AI fuer die zwei essenziellen Fettsaeuren als
    -- Energieprozent. 1 g Fett/Fettsaeure = 9 kcal.
    ROUND(a.kcal_wert * 0.04 / 9, 1) AS linolsaeure_wert,
    ROUND(a.kcal_wert * 0.005 / 9, 1) AS alpha_linolensaeure_wert
  FROM abgeleitet a
)
SELECT
  m.bmr_wert,
  m.tdee_wert,
  m.kcal_wert,
  m.protein_wert,
  -- Kohlenhydrate sind die Restgroesse: was nach Protein und Fett
  -- uebrig bleibt, geteilt durch 4 kcal/g. [cmd] Diese Regel steht in
  -- keiner Goals-Spec, nur im Vorgaengercode.
  -- GREATEST(...,0): bei sehr niedrigen Zielkalorien und hohem
  -- Koerpergewicht kann der Rest negativ werden. Der Vorgaenger laesst
  -- das zu und liefert negative Kohlenhydrate.
  CASE WHEN m.kcal_wert IS NULL THEN NULL
       ELSE ROUND(GREATEST(m.kcal_wert - (m.protein_wert * 4 + m.fett_wert * 9), 0) / 4, 1)
  END,
  m.fett_wert,
  m.linolsaeure_wert,
  m.alpha_linolensaeure_wert,
  m.nutrition_goal,
  m.ziel_faktor,
  CASE
    WHEN cardinality(m.fehlend) > 0 THEN 'profil_unvollstaendig'
    WHEN m.ziel_faktor IS NULL      THEN 'zielrichtung_ohne_faktor'
    ELSE NULL
  END,
  m.fehlend
FROM makros m;
$$;


