--
-- Name: goal_milestone_status(uuid, date); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.goal_milestone_status(p_milestone_id uuid, p_stichtag date DEFAULT CURRENT_DATE) RETURNS TABLE(milestone_id uuid, goal_id uuid, user_id uuid, title text, milestone_type text, target_value numeric, target_unit text, target_date date, stored_status text, computed_status text, current_value numeric, current_source text, progress_pct numeric, progress_status text, source text, source_detail text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH m AS (
  SELECT * FROM goals.goal_milestones WHERE id = p_milestone_id
),
g AS (
  SELECT ug.*
  FROM m
  JOIN goals.user_goals ug ON ug.id = m.goal_id
),
p AS (
  SELECT gp.*
  FROM m
  LEFT JOIN LATERAL goals.goal_progress_at(m.goal_id, p_stichtag) gp ON true
)
SELECT
  m.id AS milestone_id,
  m.goal_id,
  m.user_id,
  m.title,
  m.milestone_type,
  m.target_value,
  m.target_unit,
  m.target_date,
  m.status AS stored_status,
  CASE
    WHEN m.status IN ('achieved', 'missed', 'abandoned') THEN m.status
    WHEN p.progress_status IS DISTINCT FROM 'measured' THEN p.progress_status
    WHEN m.milestone_type = 'absolute_value'
      AND g.start_value IS NOT NULL
      AND g.target_value IS NOT NULL
      AND g.target_value >= g.start_value
      AND p.current_value >= m.target_value THEN 'achieved'
    WHEN m.milestone_type = 'absolute_value'
      AND g.start_value IS NOT NULL
      AND g.target_value IS NOT NULL
      AND g.target_value < g.start_value
      AND p.current_value <= m.target_value THEN 'achieved'
    WHEN m.milestone_type = 'percentage'
      AND p.progress_pct >= m.threshold_pct THEN 'achieved'
    WHEN m.target_date IS NOT NULL AND m.target_date < p_stichtag THEN 'missed'
    ELSE 'open'
  END AS computed_status,
  p.current_value,
  p.current_source,
  p.progress_pct,
  p.progress_status,
  m.source,
  m.source_detail
FROM m
JOIN g ON true
LEFT JOIN p ON true;
$$;


