-- Name: FUNCTION goal_milestone_status(p_milestone_id uuid, p_stichtag date); Type: COMMENT; Schema: goals; Owner: postgres
--

COMMENT ON FUNCTION goals.goal_milestone_status(p_milestone_id uuid, p_stichtag date) IS 'Berechneter Status eines gesetzten Meilensteins am Stichtag.';


--
-- Name: goal_progress_at(uuid, date); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.goal_progress_at(p_goal_id uuid, p_stichtag date DEFAULT CURRENT_DATE) RETURNS TABLE(goal_id uuid, user_id uuid, goal_type text, subtype text, title text, target_value numeric, target_unit text, start_value numeric, current_value numeric, current_source text, progress_pct numeric, progress_status text, measured_at date)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH goal_row AS (
  SELECT g.*
  FROM goals.user_goals g
  WHERE g.id = p_goal_id
),
body_value AS (
  SELECT bm.weight_kg AS value, bm.measurement_date AS measured_at
  FROM goal_row g
  JOIN LATERAL (
    SELECT bm.weight_kg, bm.measurement_date
    FROM goals.body_measurements bm
    WHERE bm.user_id = g.user_id
      AND bm.measurement_date <= p_stichtag
      AND bm.weight_kg IS NOT NULL
    ORDER BY bm.measurement_date DESC, bm.measurement_time DESC, bm.created_at DESC, bm.id DESC
    LIMIT 1
  ) bm ON true
  WHERE g.goal_type = 'body_composition'
    AND g.target_unit = 'kg'
),
performance_map AS (
  SELECT
    g.*,
    CASE
      WHEN g.goal_type = 'performance'
       AND g.target_unit = 'kg'
       AND lower(g.title) LIKE '%bankdruecken%' THEN 'Barbell Bench Press'
      ELSE NULL
    END AS exercise_name
  FROM goal_row g
),
performance_value AS (
  SELECT
    max(ws.estimated_1rm)::numeric AS value,
    max(s.session_date)::date AS measured_at
  FROM performance_map g
  JOIN training.workout_sessions s
    ON s.user_id = g.user_id
   AND s.session_date <= p_stichtag
   AND s.status = 'completed'
  JOIN training.workout_exercises we
    ON we.workout_session_id = s.id
   AND we.exercise_name = g.exercise_name
  JOIN training.workout_sets ws
    ON ws.workout_exercise_id = we.id
   AND ws.estimated_1rm IS NOT NULL
  WHERE g.exercise_name IS NOT NULL
),
selected_value AS (
  SELECT
    CASE
      WHEN g.goal_type = 'body_composition' AND g.target_unit = 'kg' THEN bv.value
      WHEN g.goal_type = 'performance' AND g.target_unit = 'kg' THEN pv.value
      ELSE NULL
    END AS current_value,
    CASE
      WHEN g.goal_type = 'body_composition' AND g.target_unit = 'kg' AND bv.value IS NOT NULL THEN 'goals.body_measurements'
      WHEN g.goal_type = 'performance' AND g.target_unit = 'kg' AND pv.value IS NOT NULL THEN 'training.workout_sets.estimated_1rm'
      ELSE NULL
    END AS current_source,
    CASE
      WHEN g.goal_type = 'body_composition' AND g.target_unit = 'kg' THEN bv.measured_at
      WHEN g.goal_type = 'performance' AND g.target_unit = 'kg' THEN pv.measured_at
      ELSE NULL
    END AS measured_at
  FROM goal_row g
  LEFT JOIN body_value bv ON true
  LEFT JOIN performance_value pv ON true
)
SELECT
  g.id AS goal_id,
  g.user_id,
  g.goal_type,
  g.subtype,
  g.title,
  g.target_value,
  g.target_unit,
  g.start_value,
  v.current_value,
  v.current_source,
  CASE
    WHEN v.current_value IS NULL OR g.start_value IS NULL OR g.target_value IS NULL OR g.target_value = g.start_value THEN NULL
    ELSE round(LEAST(100, GREATEST(0, ((v.current_value - g.start_value) / (g.target_value - g.start_value)) * 100))::numeric, 1)
  END AS progress_pct,
  CASE
    WHEN g.goal_type = 'body_composition' AND g.target_unit = 'kg' AND v.current_value IS NULL THEN 'no_measurement'
    WHEN g.goal_type = 'body_composition' AND g.target_unit = 'kg' THEN 'measured'
    WHEN g.goal_type = 'performance' AND g.target_unit = 'kg' AND v.current_value IS NULL THEN 'no_workout_sets'
    WHEN g.goal_type = 'performance' AND g.target_unit = 'kg' THEN 'measured'
    WHEN g.goal_type = 'performance' THEN 'not_measurable'
    ELSE 'not_measurable'
  END AS progress_status,
  v.measured_at
FROM goal_row g
CROSS JOIN selected_value v;
$$;


