CREATE FUNCTION goals.phase_am(p_user_id uuid, p_stichtag date DEFAULT CURRENT_DATE) RETURNS TABLE(phase_id uuid, user_id uuid, goal_id uuid, phase_type text, variant text, parameters jsonb, gueltig_ab date, projected_end_date date, actual_end_date date, transitioned_from text, recommended_next text, transition_reason text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT gp.id, gp.user_id, gp.goal_id, gp.phase_type, gp.variant, gp.parameters,
         gp.gueltig_ab, gp.projected_end_date, gp.actual_end_date,
         gp.transitioned_from, gp.recommended_next, gp.transition_reason,
         gp.created_at, gp.updated_at
  FROM goals.goal_phases gp
  WHERE gp.user_id = p_user_id
    AND gp.gueltig_ab <= p_stichtag
    AND (gp.actual_end_date IS NULL OR gp.actual_end_date >= p_stichtag)
  ORDER BY gp.gueltig_ab DESC
  LIMIT 1;
$$;


