--
-- Name: refresh_goal_progress_from_body_measurement(); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.refresh_goal_progress_from_body_measurement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    PERFORM goals.refresh_user_goals_progress_for_user(NEW.user_id, CURRENT_DATE);
  END IF;

  IF TG_OP IN ('UPDATE', 'DELETE') AND (TG_OP = 'DELETE' OR OLD.user_id IS DISTINCT FROM NEW.user_id) THEN
    PERFORM goals.refresh_user_goals_progress_for_user(OLD.user_id, CURRENT_DATE);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION goals.refresh_goal_progress_from_body_measurement() OWNER TO postgres;

--
-- Name: refresh_goal_progress_from_workout_set(); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.refresh_goal_progress_from_workout_set() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_new_user_id uuid;
  v_old_user_id uuid;
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT s.user_id
    INTO v_new_user_id
    FROM training.workout_exercises we
    JOIN training.workout_sessions s ON s.id = we.workout_session_id
    WHERE we.id = NEW.workout_exercise_id;

    IF v_new_user_id IS NOT NULL THEN
      PERFORM goals.refresh_user_goals_progress_for_user(v_new_user_id, CURRENT_DATE);
    END IF;
  END IF;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT s.user_id
    INTO v_old_user_id
    FROM training.workout_exercises we
    JOIN training.workout_sessions s ON s.id = we.workout_session_id
    WHERE we.id = OLD.workout_exercise_id;

    IF v_old_user_id IS NOT NULL AND v_old_user_id IS DISTINCT FROM v_new_user_id THEN
      PERFORM goals.refresh_user_goals_progress_for_user(v_old_user_id, CURRENT_DATE);
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION goals.refresh_goal_progress_from_workout_set() OWNER TO postgres;

--
-- Name: refresh_profile_body_weight(uuid); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.refresh_profile_body_weight(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_weight numeric;
BEGIN
  SELECT bm.weight_kg
    INTO v_weight
  FROM goals.body_measurements bm
  WHERE bm.user_id = p_user_id
  ORDER BY bm.measurement_date DESC, bm.measurement_time DESC, bm.created_at DESC, bm.id DESC
  LIMIT 1;

  IF v_weight IS NOT NULL THEN
    UPDATE public.profiles p
       SET body_weight_kg = v_weight,
           updated_at = now()
     WHERE p.id = p_user_id;
  END IF;
END;
$$;


ALTER FUNCTION goals.refresh_profile_body_weight(p_user_id uuid) OWNER TO postgres;

--
-- Name: refresh_user_goal_progress(uuid, date); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.refresh_user_goal_progress(p_goal_id uuid, p_stichtag date DEFAULT CURRENT_DATE) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_progress record;
BEGIN
  SELECT *
  INTO v_progress
  FROM goals.goal_progress_at(p_goal_id, p_stichtag)
  LIMIT 1;

  IF NOT FOUND OR v_progress.progress_status IS DISTINCT FROM 'measured' THEN
    RETURN false;
  END IF;

  UPDATE goals.user_goals
  SET
    current_value = v_progress.current_value,
    progress_pct = COALESCE(v_progress.progress_pct, 0),
    updated_at = now()
  WHERE id = p_goal_id
    AND auto_update;

  RETURN FOUND;
END;
$$;


ALTER FUNCTION goals.refresh_user_goal_progress(p_goal_id uuid, p_stichtag date) OWNER TO postgres;

--
-- Name: FUNCTION refresh_user_goal_progress(p_goal_id uuid, p_stichtag date); Type: COMMENT; Schema: goals; Owner: postgres
--

COMMENT ON FUNCTION goals.refresh_user_goal_progress(p_goal_id uuid, p_stichtag date) IS 'Pflegt den Snapshot user_goals.progress_pct aus goal_progress_at() fuer ein messbares Ziel.';


--
-- Name: refresh_user_goals_progress_for_user(uuid, date); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.refresh_user_goals_progress_for_user(p_user_id uuid, p_stichtag date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_goal record;
  v_count integer := 0;
BEGIN
  FOR v_goal IN
    SELECT id
    FROM goals.user_goals
    WHERE user_id = p_user_id
      AND auto_update
      AND status IN ('active', 'paused')
  LOOP
    IF goals.refresh_user_goal_progress(v_goal.id, p_stichtag) THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION goals.refresh_user_goals_progress_for_user(p_user_id uuid, p_stichtag date) OWNER TO postgres;

--
-- Name: FUNCTION refresh_user_goals_progress_for_user(p_user_id uuid, p_stichtag date); Type: COMMENT; Schema: goals; Owner: postgres
--

COMMENT ON FUNCTION goals.refresh_user_goals_progress_for_user(p_user_id uuid, p_stichtag date) IS 'Pflegt messbare Ziel-Snapshots eines Nutzers nach Aenderungen an Koerper- oder Trainingsmessungen.';


--
-- Name: sync_profile_weight_from_measurement(); Type: FUNCTION; Schema: goals; Owner: postgres
--

CREATE FUNCTION goals.sync_profile_weight_from_measurement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.user_id <> NEW.user_id THEN
    PERFORM goals.refresh_profile_body_weight(OLD.user_id);
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM goals.refresh_profile_body_weight(OLD.user_id);
    RETURN OLD;
  END IF;

  PERFORM goals.refresh_profile_body_weight(NEW.user_id);
  RETURN NEW;
END;
$$;


