--
-- Name: biomarker_marker_candidates(text, text); Type: FUNCTION; Schema: medical; Owner: postgres
--

CREATE FUNCTION medical.biomarker_marker_candidates(p_marker_name text, p_unit text DEFAULT NULL::text) RETURNS TABLE(loinc_code text, match_source text, match_policy text, confidence numeric, canonical_name text, display_name text, system text, example_ucum_units text, common_test_rank integer)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH q AS (
    SELECT nutrition.search_fold(p_marker_name) AS folded,
           NULLIF(btrim(lower(coalesce(p_unit, ''))), '') AS unit_folded
  ),
  alias_candidates AS (
    SELECT
      a.loinc_code,
      a.source AS match_source,
      a.match_policy,
      a.confidence
        + CASE
            WHEN q.unit_folded IS NOT NULL
             AND lower(coalesce(c.example_ucum_units, '')) = q.unit_folded
            THEN 0.03 ELSE 0
          END AS confidence,
      a.canonical_name,
      c.display_name,
      c.system,
      c.example_ucum_units,
      c.common_test_rank
    FROM q
    JOIN medical.biomarker_aliases a
      ON a.alias_folded = q.folded
    JOIN medical.biomarker_catalog c
      ON c.loinc_code = a.loinc_code
  ),
  catalog_terms AS (
    SELECT c.loinc_code,
           'loinc_catalog'::text AS match_source,
           'exact'::text AS match_policy,
           CASE
             WHEN q.unit_folded IS NOT NULL
              AND lower(coalesce(c.example_ucum_units, '')) = q.unit_folded
             THEN 0.83::numeric
             ELSE 0.80::numeric
           END AS confidence,
           c.long_common_name AS canonical_name,
           c.display_name,
           c.system,
           c.example_ucum_units,
           c.common_test_rank
    FROM q
    JOIN medical.biomarker_catalog c ON true
    JOIN LATERAL (
      SELECT term
      FROM (
        VALUES
          (c.component),
          (c.long_common_name),
          (c.short_name),
          (c.display_name),
          (c.consumer_name),
          (c.german_component),
          (c.german_long_name),
          (c.german_display_name)
      ) AS direct_terms(term)
      WHERE nutrition.search_fold(term) = q.folded
      UNION ALL
      SELECT s.value
      FROM jsonb_array_elements_text(coalesce(c.synonyms->'loinc_related_names', '[]'::jsonb)) AS s(value)
      WHERE nutrition.search_fold(s.value) = q.folded
    ) matched ON true
  ),
  combined AS (
    SELECT * FROM alias_candidates
    UNION ALL
    SELECT * FROM catalog_terms
  )
  SELECT
    c.loinc_code,
    (array_agg(c.match_source ORDER BY c.confidence DESC, c.common_test_rank))[1] AS match_source,
    CASE
      WHEN bool_or(c.match_policy = 'ambiguous') THEN 'ambiguous'
      ELSE 'exact'
    END AS match_policy,
    max(c.confidence)::numeric(3,2) AS confidence,
    (array_agg(c.canonical_name ORDER BY c.confidence DESC, c.common_test_rank))[1] AS canonical_name,
    (array_agg(c.display_name ORDER BY c.confidence DESC, c.common_test_rank))[1] AS display_name,
    (array_agg(c.system ORDER BY c.confidence DESC, c.common_test_rank))[1] AS system,
    (array_agg(c.example_ucum_units ORDER BY c.confidence DESC, c.common_test_rank))[1] AS example_ucum_units,
    min(c.common_test_rank) AS common_test_rank
  FROM combined c
  GROUP BY c.loinc_code
  ORDER BY confidence DESC, common_test_rank NULLS LAST, loinc_code
  LIMIT 10;
$$;


ALTER FUNCTION medical.biomarker_marker_candidates(p_marker_name text, p_unit text) OWNER TO postgres;

--
-- Name: import_lab_report_rows(uuid, date, time without time zone, text, text, text, jsonb); Type: FUNCTION; Schema: medical; Owner: postgres
--

CREATE FUNCTION medical.import_lab_report_rows(p_user_id uuid, p_report_date date, p_report_time time without time zone, p_lab_name text, p_title text, p_source text, p_rows jsonb) RETURNS TABLE(report_id uuid, inserted_count integer, exact_count integer, ambiguous_count integer, unknown_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_report_id UUID;
  v_row JSONB;
  v_raw_name TEXT;
  v_unit TEXT;
  v_candidates JSONB;
  v_candidate_count INTEGER;
  v_top JSONB;
  v_second JSONB;
  v_status TEXT;
  v_loinc TEXT;
  v_confidence NUMERIC(3,2);
  v_exact INTEGER := 0;
  v_ambiguous INTEGER := 0;
  v_unknown INTEGER := 0;
  v_auth_user UUID;
BEGIN
  v_auth_user := nullif(current_setting('request.jwt.claim.sub', true), '')::uuid;

  IF p_user_id <> v_auth_user THEN
    RAISE EXCEPTION 'medical import: user mismatch';
  END IF;
  IF jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'medical import: rows must be an array';
  END IF;

  INSERT INTO medical.lab_reports (
    user_id, report_date, report_time, lab_name, title, source, source_detail
  )
  VALUES (
    p_user_id, p_report_date, p_report_time, p_lab_name, p_title, p_source,
    'medical.import_lab_report_rows'
  )
  RETURNING id INTO v_report_id;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_raw_name := NULLIF(btrim(v_row->>'marker_name'), '');
    v_unit := NULLIF(btrim(v_row->>'unit'), '');
    IF v_raw_name IS NULL THEN
      RAISE EXCEPTION 'medical import: marker_name missing';
    END IF;
    IF v_unit IS NULL THEN
      RAISE EXCEPTION 'medical import: unit missing';
    END IF;

    SELECT coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb), count(*)
    INTO v_candidates, v_candidate_count
    FROM medical.biomarker_marker_candidates(v_raw_name, v_unit) c;

    v_top := CASE WHEN v_candidate_count > 0 THEN v_candidates->0 ELSE NULL END;
    v_second := CASE WHEN v_candidate_count > 1 THEN v_candidates->1 ELSE NULL END;

    IF v_candidate_count = 0 THEN
      v_status := 'unknown';
      v_loinc := NULL;
      v_confidence := 0.00;
      v_unknown := v_unknown + 1;
    ELSIF coalesce(v_top->>'match_policy', 'exact') = 'exact'
      AND (
        v_candidate_count = 1
        OR (
          (v_top->>'confidence')::numeric >= 0.95
          AND (v_second->>'confidence')::numeric < (v_top->>'confidence')::numeric
        )
      ) THEN
      v_status := 'exact';
      v_loinc := v_top->>'loinc_code';
      v_confidence := (v_top->>'confidence')::numeric(3,2);
      v_exact := v_exact + 1;
    ELSE
      v_status := 'ambiguous';
      v_loinc := NULL;
      v_confidence := 0.50;
      v_ambiguous := v_ambiguous + 1;
    END IF;

    INSERT INTO medical.lab_result_values (
      report_id,
      user_id,
      loinc_code,
      raw_marker_name,
      match_status,
      match_candidates,
      match_source,
      marker_name_snapshot,
      unit_snapshot,
      value_numeric,
      value_text,
      value_operator,
      lab_reference_low,
      lab_reference_high,
      lab_reference_text,
      lab_reference_unit,
      lab_reference_source,
      source,
      entry_confidence,
      needs_verification,
      notes
    )
    VALUES (
      v_report_id,
      p_user_id,
      v_loinc,
      v_raw_name,
      v_status,
      v_candidates,
      CASE WHEN v_top IS NULL THEN NULL ELSE v_top->>'match_source' END,
      coalesce(v_top->>'canonical_name', v_raw_name),
      v_unit,
      NULLIF(v_row->>'value_numeric', '')::numeric,
      NULLIF(v_row->>'value_text', ''),
      coalesce(NULLIF(v_row->>'value_operator', ''), '='),
      NULLIF(v_row->>'lab_reference_low', '')::numeric,
      NULLIF(v_row->>'lab_reference_high', '')::numeric,
      NULLIF(v_row->>'lab_reference_text', ''),
      NULLIF(v_row->>'lab_reference_unit', ''),
      NULLIF(v_row->>'lab_reference_source', ''),
      p_source,
      v_confidence,
      v_status <> 'exact',
      NULLIF(v_row->>'notes', '')
    );
  END LOOP;

  report_id := v_report_id;
  inserted_count := jsonb_array_length(p_rows);
  exact_count := v_exact;
  ambiguous_count := v_ambiguous;
  unknown_count := v_unknown;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION medical.import_lab_report_rows(p_user_id uuid, p_report_date date, p_report_time time without time zone, p_lab_name text, p_title text, p_source text, p_rows jsonb) OWNER TO postgres;

--
-- Name: lab_result_values_read(uuid, uuid); Type: FUNCTION; Schema: medical; Owner: postgres
--

CREATE FUNCTION medical.lab_result_values_read(p_user_id uuid, p_report_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, report_id uuid, report_date date, report_time time without time zone, lab_name text, loinc_code text, marker_name text, unit text, value_numeric numeric, value_text text, value_operator text, reference_low numeric, reference_high numeric, reference_text text, reference_unit text, reference_source text, reference_range_id uuid, source text, frozen_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    v.id,
    v.report_id,
    r.report_date,
    r.report_time,
    r.lab_name,
    v.loinc_code,
    v.marker_name_snapshot AS marker_name,
    v.unit_snapshot AS unit,
    v.value_numeric,
    v.value_text,
    v.value_operator,
    COALESCE(v.lab_reference_low, rr.min_value) AS reference_low,
    COALESCE(v.lab_reference_high, rr.max_value) AS reference_high,
    COALESCE(v.lab_reference_text, rr.value_text) AS reference_text,
    COALESCE(v.lab_reference_unit, rr.unit) AS reference_unit,
    CASE
      WHEN v.lab_reference_low IS NOT NULL
        OR v.lab_reference_high IS NOT NULL
        OR v.lab_reference_text IS NOT NULL
      THEN 'lab_report'
      WHEN rr.id IS NOT NULL THEN 'catalog_fallback'
      ELSE 'none'
    END AS reference_source,
    rr.id AS reference_range_id,
    v.source,
    v.frozen_at
  FROM medical.lab_result_values v
  JOIN medical.lab_reports r
    ON r.id = v.report_id
   AND r.user_id = v.user_id
  LEFT JOIN LATERAL (
    SELECT br.*
    FROM medical.biomarker_reference_ranges br
    WHERE br.loinc_code = v.loinc_code
      AND br.is_active
      AND br.decision_status <> 'do_not_import_without_source'
      AND br.range_type = 'lab'
      AND br.sex IN ('all', (
        SELECT p.biological_sex
        FROM public.profiles p
        WHERE p.id = v.user_id
      ))
    ORDER BY
      CASE br.sex WHEN 'all' THEN 1 ELSE 0 END,
      br.age_min_years NULLS FIRST,
      br.id
    LIMIT 1
  ) rr ON true
  WHERE v.user_id = p_user_id
    AND (p_report_id IS NULL OR v.report_id = p_report_id)
  ORDER BY r.report_date DESC, r.report_time DESC NULLS LAST, v.created_at, v.id;
$$;


ALTER FUNCTION medical.lab_result_values_read(p_user_id uuid, p_report_id uuid) OWNER TO postgres;

--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: medical; Owner: postgres
--

CREATE FUNCTION medical.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION medical.touch_updated_at() OWNER TO postgres;

--
-- Name: copy_meal_plan_week(uuid, date); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.copy_meal_plan_week(p_week_id uuid, p_target_week_start date) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_old nutrition.meal_plan_weeks%ROWTYPE;
  v_new_week_id uuid := gen_random_uuid();
  v_auth uuid := auth.uid();
BEGIN
  SELECT * INTO v_old
  FROM nutrition.meal_plan_weeks
  WHERE id = p_week_id;

  IF v_old.id IS NULL THEN
    RAISE EXCEPTION 'copy_meal_plan_week: Woche % nicht gefunden', p_week_id
      USING ERRCODE = '02000';
  END IF;
  IF v_auth IS NOT NULL AND v_old.user_id <> v_auth THEN
    RAISE EXCEPTION 'copy_meal_plan_week: fremde Woche'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO nutrition.meal_plan_weeks (
    id, plan_id, user_id, week_start, name, copied_from_week_id
  )
  VALUES (
    v_new_week_id,
    v_old.plan_id,
    v_old.user_id,
    p_target_week_start,
    COALESCE(v_old.name, 'Kopierte Woche'),
    v_old.id
  );

  INSERT INTO nutrition.meal_plan_days (
    week_id, user_id, plan_date, day_index, notes
  )
  SELECT
    v_new_week_id,
    d.user_id,
    p_target_week_start + (d.day_index - 1),
    d.day_index,
    d.notes
  FROM nutrition.meal_plan_days d
  WHERE d.week_id = v_old.id
  ORDER BY d.day_index;

  INSERT INTO nutrition.meal_plan_entries (
    day_id, user_id, meal_type, planned_time, slot_order, entry_type,
    recipe_id, food_id, custom_food_id, amount_g, planned_servings,
    portion_name, portion_quantity, portion_amount_g, note
  )
  SELECT
    nd.id,
    e.user_id,
    e.meal_type,
    e.planned_time,
    e.slot_order,
    e.entry_type,
    e.recipe_id,
    e.food_id,
    e.custom_food_id,
    e.amount_g,
    e.planned_servings,
    e.portion_name,
    e.portion_quantity,
    e.portion_amount_g,
    e.note
  FROM nutrition.meal_plan_entries e
  JOIN nutrition.meal_plan_days od ON od.id = e.day_id
  JOIN nutrition.meal_plan_days nd
    ON nd.week_id = v_new_week_id
   AND nd.day_index = od.day_index
  WHERE od.week_id = v_old.id
  ORDER BY od.day_index, e.meal_type, e.slot_order;

  RETURN v_new_week_id;
END;
$$;


ALTER FUNCTION nutrition.copy_meal_plan_week(p_week_id uuid, p_target_week_start date) OWNER TO postgres;

--
-- Name: curation_overview(boolean, text, text, text, text); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.curation_overview(p_unassigned_only boolean, p_category text, p_tag text, p_alias_state text, p_sort text) RETURNS json
    LANGUAGE sql STABLE
    AS $$
WITH category_levels AS (
  SELECT level, COUNT(*)::int AS count
  FROM nutrition.food_categories
  GROUP BY level
  ORDER BY level
),
tag_coverage AS (
  SELECT td.code, td.name_de, COUNT(ft.food_id)::int AS food_count
  FROM nutrition.tag_definitions td
  LEFT JOIN nutrition.food_tags ft ON ft.tag_code = td.code
  GROUP BY td.code, td.name_de
  ORDER BY food_count DESC, td.code
),
alias_counts AS (
  SELECT f.id, COUNT(fa.alias)::int AS alias_count
  FROM nutrition.foods f
  LEFT JOIN nutrition.food_aliases fa ON fa.food_id = f.id
  GROUP BY f.id
),
unassigned AS (
  SELECT
    f.id,
    f.bls_code,
    COALESCE(NULLIF(f.name_display_de, ''), f.name_de, f.name_en, f.bls_code) AS source_label,
    fc.slug AS current_category_slug,
    fc.name_de AS current_category_name_de,
    f.sort_weight,
    COALESCE(alias.alias_count, 0)::int AS alias_count,
    COALESCE(tags.tags, ARRAY[]::text[]) AS tags,
    m.enercc::text,
    m.prot625::text,
    m.fat::text,
    m.cho::text
  FROM nutrition.foods f
  LEFT JOIN nutrition.food_categories fc ON fc.id = f.category_id
  LEFT JOIN LATERAL (
    SELECT COUNT(*) AS alias_count FROM nutrition.food_aliases fa WHERE fa.food_id = f.id
  ) alias ON TRUE
  LEFT JOIN LATERAL (
    SELECT array_agg(ft.tag_code ORDER BY ft.tag_code) AS tags FROM nutrition.food_tags ft WHERE ft.food_id = f.id
  ) tags ON TRUE
  LEFT JOIN LATERAL (
    SELECT
      MAX(value) FILTER (WHERE nutrient_code='ENERCC') AS enercc,
      MAX(value) FILTER (WHERE nutrient_code='PROT625') AS prot625,
      MAX(value) FILTER (WHERE nutrient_code='FAT') AS fat,
      MAX(value) FILTER (WHERE nutrient_code='CHO') AS cho
    FROM nutrition.food_nutrients fn WHERE fn.food_id = f.id
  ) m ON TRUE
  WHERE
    (NOT COALESCE(p_unassigned_only, TRUE) OR f.category_id IS NULL)
    AND (COALESCE(p_category, '') = '' OR fc.slug = p_category)
    AND (COALESCE(p_tag, '') = '' OR EXISTS (
      SELECT 1 FROM nutrition.food_tags ft_filter
      WHERE ft_filter.food_id = f.id AND ft_filter.tag_code = p_tag
    ))
    AND (
      COALESCE(p_alias_state, '') NOT IN ('has', 'missing')
      OR (p_alias_state = 'has' AND COALESCE(alias.alias_count, 0) > 0)
      OR (p_alias_state = 'missing' AND COALESCE(alias.alias_count, 0) = 0)
    )
  ORDER BY
    CASE WHEN COALESCE(p_sort, 'category_missing_first') NOT IN ('sort_weight_desc','name_asc','macro_relevance')
         THEN CASE WHEN f.category_id IS NULL THEN 0 ELSE 1 END END ASC,
    CASE WHEN p_sort = 'macro_relevance' THEN COALESCE(m.prot625, 0) END DESC,
    CASE WHEN p_sort = 'macro_relevance' THEN COALESCE(m.enercc, 0) END DESC,
    CASE WHEN p_sort = 'sort_weight_desc'
           OR COALESCE(p_sort, 'category_missing_first') NOT IN ('sort_weight_desc','name_asc','macro_relevance')
         THEN f.sort_weight END DESC NULLS LAST,
    COALESCE(NULLIF(f.name_display_de, ''), f.name_de, f.name_en, f.bls_code) ASC
  LIMIT 50
)
SELECT json_build_object(
  'counts', json_build_object(
    'foods', (SELECT COUNT(*)::int FROM nutrition.foods),
    'food_nutrients', (SELECT COUNT(*)::int FROM nutrition.food_nutrients),
    'assigned_foods', (SELECT COUNT(*)::int FROM nutrition.foods WHERE category_id IS NOT NULL),
    'unassigned_foods', (SELECT COUNT(*)::int FROM nutrition.foods WHERE category_id IS NULL),
    'tag_definitions', (SELECT COUNT(*)::int FROM nutrition.tag_definitions),
    'food_tags', (SELECT COUNT(*)::int FROM nutrition.food_tags),
    'food_aliases', (SELECT COUNT(*)::int FROM nutrition.food_aliases)
  ),
  'category_levels', COALESCE((SELECT json_agg(json_build_object('level', level, 'count', count)) FROM category_levels), '[]'::json),
  'tag_coverage', COALESCE((SELECT json_agg(json_build_object('code', code, 'name_de', name_de, 'food_count', food_count)) FROM tag_coverage), '[]'::json),
  'low_coverage_tags', COALESCE((SELECT json_agg(json_build_object('code', code, 'name_de', name_de, 'food_count', food_count)) FROM tag_coverage WHERE food_count <= 5), '[]'::json),
  'alias_coverage', json_build_object(
    'zero_alias_foods', (SELECT COUNT(*)::int FROM alias_counts WHERE alias_count = 0),
    'one_alias_foods', (SELECT COUNT(*)::int FROM alias_counts WHERE alias_count = 1),
    'multi_alias_foods', (SELECT COUNT(*)::int FROM alias_counts WHERE alias_count > 1),
    'german_umlaut_foods', (SELECT COUNT(*)::int FROM nutrition.foods WHERE name_de ~ '[äöüÄÖÜß]'),
    'foods_with_en_source_label', (SELECT COUNT(*)::int FROM nutrition.foods WHERE COALESCE(NULLIF(name_en, ''), '') <> '')
  ),
  'candidate_tables', json_build_object(
    'candidates_table_exists', to_regclass('nutrition.food_curation_candidates') IS NOT NULL,
    'decisions_table_exists', to_regclass('nutrition.food_curation_decisions') IS NOT NULL,
    'candidates', CASE WHEN to_regclass('nutrition.food_curation_candidates') IS NULL THEN 0 ELSE (SELECT COUNT(*)::int FROM nutrition.food_curation_candidates) END,
    'pending_candidates', CASE WHEN to_regclass('nutrition.food_curation_candidates') IS NULL THEN 0 ELSE (SELECT COUNT(*)::int FROM nutrition.food_curation_candidates WHERE status = 'pending') END,
    'decisions', CASE WHEN to_regclass('nutrition.food_curation_decisions') IS NULL THEN 0 ELSE (SELECT COUNT(*)::int FROM nutrition.food_curation_decisions) END
  ),
  'unassigned_examples', COALESCE((SELECT json_agg(json_build_object(
    'id', id,
    'bls_code', bls_code,
    'source_label', source_label,
    'current_category_slug', COALESCE(current_category_slug, ''),
    'current_category_name_de', COALESCE(current_category_name_de, ''),
    'sort_weight', COALESCE(sort_weight, 0),
    'alias_count', alias_count,
    'tags', tags,
    'enercc', enercc,
    'prot625', prot625,
    'fat', fat,
    'cho', cho,
    'curation_status', CASE WHEN current_category_slug IS NULL THEN 'needs_curation' ELSE 'categorized' END,
    'unresolved_reason', CASE WHEN current_category_slug IS NULL THEN 'No deterministic category_id is assigned yet.' ELSE '' END
  )) FROM unassigned), '[]'::json)
)
$$;


ALTER FUNCTION nutrition.curation_overview(p_unassigned_only boolean, p_category text, p_tag text, p_alias_state text, p_sort text) OWNER TO postgres;

--
-- Name: custom_food_energy_plausibility(numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.custom_food_energy_plausibility(p_enercc numeric, p_prot625 numeric, p_fat numeric, p_cho numeric, p_alc numeric DEFAULT NULL::numeric, p_tolerance numeric DEFAULT 0.10) RETURNS TABLE(calculated_enercc numeric, deviation_ratio numeric, plausible boolean, message text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_calculated numeric;
  v_base numeric;
  v_ratio numeric;
BEGIN
  v_calculated :=
    4 * COALESCE(p_prot625, 0) +
    9 * COALESCE(p_fat, 0) +
    4 * COALESCE(p_cho, 0) +
    7 * COALESCE(p_alc, 0);

  v_base := GREATEST(ABS(COALESCE(p_enercc, 0)), ABS(v_calculated), 1);
  v_ratio := ABS(COALESCE(p_enercc, 0) - v_calculated) / v_base;

  RETURN QUERY SELECT
    ROUND(v_calculated, 2),
    ROUND(v_ratio, 4),
    v_ratio <= COALESCE(p_tolerance, 0.10),
    CASE
      WHEN v_ratio <= COALESCE(p_tolerance, 0.10)
        THEN 'Makroenergie passt innerhalb der Toleranz'
      ELSE 'Makroenergie weicht um mehr als die Toleranz ab'
    END;
END;
$$;


ALTER FUNCTION nutrition.custom_food_energy_plausibility(p_enercc numeric, p_prot625 numeric, p_fat numeric, p_cho numeric, p_alc numeric, p_tolerance numeric) OWNER TO postgres;

--
-- Name: daily_reference_assessment(uuid, date); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.daily_reference_assessment(p_user_id uuid, p_entry_date date) RETURNS TABLE(user_id uuid, entry_date date, nutrient_code text, nutrient_name_de text, nutrient_unit text, nutrient_display_tier integer, actual_value numeric, missing_count integer, value_complete boolean, reference_kind text, reference_direction text, reference_value_min numeric, reference_value_max numeric, reference_unit text, reference_basis text, reference_pct numeric, reference_pct_min numeric, reference_pct_max numeric, reference_status text, profile_age_years integer, profile_biological_sex text, profile_is_pregnant boolean, profile_is_lactating boolean, source text, source_locator text, notes text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH profile AS (
  SELECT
    p_user_id AS user_id,
    p_entry_date AS entry_date,
    p.birth_date,
    p.biological_sex,
    -- GO-00 Teil 2: fuer Referenzwerte je Kilogramm Koerpergewicht.
    -- Live gelesen, nicht in den Seed gerechnet ??? beim Gewichtswechsel
    -- aendert sich der Wert damit mit, statt zu veralten.
    p.body_weight_kg,
    CASE
      WHEN p.birth_date IS NULL THEN NULL
      ELSE EXTRACT(YEAR FROM age(p_entry_date, p.birth_date))::INTEGER
    END AS age_years,
    (
      p.pregnancy_started_on IS NOT NULL
      AND p_entry_date >= p.pregnancy_started_on
      AND (p.pregnancy_ended_on IS NULL OR p_entry_date <= p.pregnancy_ended_on)
    ) AS is_pregnant,
    (
      p.lactation_started_on IS NOT NULL
      AND p_entry_date >= p.lactation_started_on
      AND (p.lactation_ended_on IS NULL OR p_entry_date <= p.lactation_ended_on)
    ) AS is_lactating
  FROM public.profiles p
  WHERE p.id = p_user_id
),
profile_one AS (
  SELECT
    p_user_id AS user_id,
    p_entry_date AS entry_date,
    pr.birth_date,
    pr.biological_sex,
    pr.body_weight_kg,
    pr.age_years,
    COALESCE(pr.is_pregnant, false) AS is_pregnant,
    COALESCE(pr.is_lactating, false) AS is_lactating,
    (pr.birth_date IS NOT NULL AND pr.biological_sex IS NOT NULL) AS profile_complete
  FROM (SELECT 1) seed
  LEFT JOIN profile pr ON true
),
day_values AS (
  SELECT
    l.nutrient_code,
    l.total_value AS actual_value,
    l.missing_count
  FROM nutrition.daily_nutrient_summary_long l
  WHERE l.user_id = p_user_id
    AND l.entry_date = p_entry_date
),
reference_candidates AS (
  SELECT
    dv.nutrient_code,
    r.reference_kind,
    r.value_min,
    r.value_max,
    r.unit,
    r.basis,
    r.source,
    r.source_locator,
    r.notes,
    CASE
      WHEN r.reference_kind IN ('UL', 'ALAP') THEN 'upper_limit'
      WHEN r.reference_kind = 'RI' THEN 'range'
      WHEN r.reference_kind IN ('NO_REFERENCE', 'NO_STANDALONE_REFERENCE') THEN 'not_applicable'
      ELSE 'target'
    END AS reference_direction,
    ROW_NUMBER() OVER (
      PARTITION BY dv.nutrient_code, r.reference_kind
      ORDER BY
        CASE
          WHEN r.is_pregnant = p.is_pregnant AND r.is_lactating = p.is_lactating THEN 2
          WHEN NOT r.is_pregnant AND NOT r.is_lactating THEN 1
          ELSE 0
        END DESC,
        CASE WHEN r.sex = p.biological_sex THEN 1 ELSE 0 END DESC,
        COALESCE(r.age_max - r.age_min, 999) ASC
    ) AS rn
  FROM day_values dv
  CROSS JOIN profile_one p
  JOIN nutrition.nutrient_reference_values r
    ON r.nutrient_code = dv.nutrient_code
   AND p.profile_complete
   AND (r.age_min IS NULL OR p.age_years >= r.age_min)
   AND (r.age_max IS NULL OR p.age_years <= r.age_max)
   AND (r.sex = 'both' OR r.sex = p.biological_sex)
   AND (
     (r.is_pregnant = p.is_pregnant AND r.is_lactating = p.is_lactating)
     OR (NOT r.is_pregnant AND NOT r.is_lactating)
   )
),
-- =============================================================
-- GO-00 Teil 2: die Bezugsgroesse aufloesen
-- =============================================================
-- `[cmd]` 16 der 109 Referenzzeilen stehen nicht je Tag, sondern je
-- Kilogramm Koerpergewicht (10), als Energieanteil (4) oder je
-- Megajoule (2). Vorher hat die Funktion sie behandelt, als staenden
-- sie je Tag ??? Protein zeigte 1.593 % statt rund 20 %, weil 13,22 g
-- durch 0,83 geteilt wurde statt durch 0,83 x 78,4 kg.
--
-- WARUM HIER UND NICHT IM SEED:
-- `[read]` 0,83 g/kg bleibt 0,83 g/kg ??? so schreibt es die EFSA, und
-- der Seed bildet die Quelle ab. Ein Wert je Kilogramm laesst sich
-- ausserdem gar nicht vorab ausrechnen: er haengt am Gewicht der
-- Nutzerin, und das aendert sich. Umgerechnet wird beim Lesen.
--
-- WARUM ABSOLUT ANGEZEIGT WIRD:
-- `[read]` Entscheidung Tom, 2026-08-15, nach einer Erhebung, wie
-- etablierte Ernaehrungs-Apps es halten: keine zeigt eine Einheit je
-- Kilogramm. MyFitnessPal nennt 1,2 g/kg als Zielsetzung in den
-- Einstellungen; im Tagebuch stehen 120 g.
--
-- OHNE GEWICHT KEIN PROZENTWERT. Kein Standardgewicht, kein
-- Ruecktritt ??? dieselbe Regel wie bei fehlendem Alter oder Geschlecht.
-- `[read]` Ein erfundener Nenner waere schlimmer als keine Zahl: er
-- sieht aus wie eine Messung.
goals_targets AS (
  SELECT
    z.kcal,
    COALESCE(
      z.linoleic_acid_g,
      CASE WHEN z.kcal IS NULL THEN NULL ELSE ROUND(z.kcal * 0.04 / 9, 1) END
    ) AS linoleic_acid_g,
    COALESCE(
      z.alpha_linolenic_acid_g,
      CASE WHEN z.kcal IS NULL THEN NULL ELSE ROUND(z.kcal * 0.005 / 9, 1) END
    ) AS alpha_linolenic_acid_g
  FROM (SELECT 1) seed
  LEFT JOIN LATERAL goals.zielwerte_am(p_user_id, p_entry_date) z ON true
),
aufgeloeste_referenzen AS (
  SELECT
    rc.*,
    p.body_weight_kg,
    gt.linoleic_acid_g,
    gt.alpha_linolenic_acid_g,
    CASE
      WHEN rc.nutrient_code = 'F18:2CN6' AND rc.reference_kind = 'AI'
        THEN gt.linoleic_acid_g
      WHEN rc.nutrient_code = 'F18:3CN3' AND rc.reference_kind = 'AI'
        THEN gt.alpha_linolenic_acid_g
      -- Je Kilogramm Koerpergewicht: mit dem Gewicht multiplizieren.
      -- `[cmd]` Neun der zehn Zeilen stehen in mg/kg, waehrend der
      -- Naehrstoff selbst in g gefuehrt wird (die Aminosaeuren) ???
      -- deshalb zusaetzlich durch 1000. Protein steht in g/kg und
      -- braucht nur die Multiplikation.
      WHEN rc.basis = 'per_kg_bw_per_day' AND p.body_weight_kg IS NOT NULL THEN
        rc.value_min * p.body_weight_kg
        / CASE WHEN rc.unit LIKE 'mg/kg%' THEN 1000 ELSE 1 END
      WHEN rc.basis = 'per_day' THEN rc.value_min
      ELSE NULL
    END AS abs_value_min,
    CASE
      WHEN rc.nutrient_code IN ('F18:2CN6', 'F18:3CN3') AND rc.reference_kind = 'AI'
        THEN NULL
      WHEN rc.basis = 'per_kg_bw_per_day' AND p.body_weight_kg IS NOT NULL THEN
        rc.value_max * p.body_weight_kg
        / CASE WHEN rc.unit LIKE 'mg/kg%' THEN 1000 ELSE 1 END
      WHEN rc.basis = 'per_day' THEN rc.value_max
      ELSE NULL
    END AS abs_value_max,
    -- Warum ein Wert NICHT als Prozent erscheint. NULL heisst: er darf.
    CASE
      WHEN rc.nutrient_code = 'F18:2CN6' AND rc.reference_kind = 'AI'
        AND gt.linoleic_acid_g IS NULL THEN 'missing_goal'
      WHEN rc.nutrient_code = 'F18:3CN3' AND rc.reference_kind = 'AI'
        AND gt.alpha_linolenic_acid_g IS NULL THEN 'missing_goal'
      WHEN rc.nutrient_code IN ('F18:2CN6', 'F18:3CN3') AND rc.reference_kind = 'AI'
        THEN NULL
      WHEN rc.basis = 'per_kg_bw_per_day' AND p.body_weight_kg IS NULL
        THEN 'missing_weight'
      -- `[read]` E% ist keine Naehrstoffempfehlung, sondern eine
      -- Aussage ueber die Energieverteilung ("Fett soll 20-35 % der
      -- Tagesenergie ausmachen"). Genau das rechnet GO-02 beim
      -- Zielwert; hier ein zweites Mal zu rechnen hiesse zwei
      -- Wahrheiten zu fuehren.
      WHEN rc.basis IN ('energy_percent', 'as_low_as_possible')
        THEN 'energy_share'
      -- `[read]` Je Megajoule ist ein Fachmass fuer Naehrstoffdichte.
      -- Es sagt nichts darueber, ob heute genug gegessen wurde.
      WHEN rc.basis = 'per_mj' THEN 'nutrient_density'
      ELSE NULL
    END AS basis_hindernis
  FROM reference_candidates rc
  CROSS JOIN profile_one p
  CROSS JOIN goals_targets gt
),
selected_references AS (
  SELECT *
  FROM aufgeloeste_referenzen
  WHERE rn = 1
)
SELECT
  p.user_id,
  p.entry_date,
  dv.nutrient_code,
  nd.name_de AS nutrient_name_de,
  nd.unit AS nutrient_unit,
  nd.display_tier AS nutrient_display_tier,
  dv.actual_value,
  dv.missing_count::INTEGER,
  (dv.missing_count = 0 AND dv.actual_value IS NOT NULL) AS value_complete,
  sr.reference_kind,
  sr.reference_direction,
  -- GO-00 Teil 2: der AUFGELOESTE Wert, in der Einheit des
  -- Naehrstoffs. Sonst staende bei Protein "0,83" als Referenz, und
  -- niemand koennte die 20 % nachrechnen.
  -- Ist die Bezugsgroesse nicht aufloesbar (E%, je MJ, Gewicht fehlt),
  -- steht hier NULL ??? der Rohwert waere irrefuehrend.
  ROUND(sr.abs_value_min, 3) AS reference_value_min,
  ROUND(sr.abs_value_max, 3) AS reference_value_max,
  -- Ebenso die Einheit: nach der Aufloesung gilt die des Naehrstoffs.
  CASE
    WHEN sr.abs_value_min IS NULL AND sr.abs_value_max IS NULL THEN sr.unit
    ELSE nd.unit
  END AS reference_unit,
  CASE
    WHEN sr.nutrient_code IN ('F18:2CN6', 'F18:3CN3')
      AND sr.reference_kind = 'AI'
      AND sr.basis_hindernis IS NULL
      THEN 'goals_target_from_energy_percent'
    ELSE sr.basis
  END AS reference_basis,
  -- GO-00 Teil 2: gerechnet wird gegen den AUFGELOESTEN Wert
  -- (abs_value_*), nicht gegen die rohe Zahl aus der Tabelle.
  -- Steht ein basis_hindernis, gibt es keinen Prozentwert.
  CASE
    WHEN dv.missing_count > 0 OR dv.actual_value IS NULL THEN NULL
    WHEN sr.reference_kind IN ('NO_REFERENCE', 'NO_STANDALONE_REFERENCE') THEN NULL
    WHEN sr.basis_hindernis IS NOT NULL THEN NULL
    WHEN COALESCE(sr.abs_value_min, sr.abs_value_max) IS NULL
      OR COALESCE(sr.abs_value_min, sr.abs_value_max) = 0 THEN NULL
    ELSE ROUND(dv.actual_value / COALESCE(sr.abs_value_min, sr.abs_value_max) * 100, 1)
  END AS reference_pct,
  CASE
    WHEN dv.missing_count > 0 OR dv.actual_value IS NULL THEN NULL
    WHEN sr.basis_hindernis IS NOT NULL THEN NULL
    WHEN sr.abs_value_min IS NULL OR sr.abs_value_min = 0 THEN NULL
    ELSE ROUND(dv.actual_value / sr.abs_value_min * 100, 1)
  END AS reference_pct_min,
  CASE
    WHEN dv.missing_count > 0 OR dv.actual_value IS NULL THEN NULL
    WHEN sr.basis_hindernis IS NOT NULL THEN NULL
    WHEN sr.abs_value_max IS NULL OR sr.abs_value_max = 0 THEN NULL
    ELSE ROUND(dv.actual_value / sr.abs_value_max * 100, 1)
  END AS reference_pct_max,
  CASE
    WHEN NOT p.profile_complete THEN 'missing_profile'
    WHEN sr.reference_kind IS NULL THEN 'no_applicable_reference'
    WHEN dv.missing_count > 0 THEN 'incomplete'
    WHEN dv.actual_value IS NULL THEN 'no_value'
    WHEN sr.reference_kind IN ('NO_REFERENCE', 'NO_STANDALONE_REFERENCE') THEN 'not_applicable'
    -- Drei neue Zustaende, je mit eigenem Grund. `[read]` Sie treten an
    -- die Stelle eines falschen Prozentwerts, nicht an die Stelle von
    -- 'complete' ??? die Zeile bleibt sichtbar, nur ohne Balken.
    WHEN sr.basis_hindernis = 'missing_weight' THEN 'missing_weight'
    WHEN sr.basis_hindernis = 'missing_goal' THEN 'missing_goal'
    WHEN sr.basis_hindernis = 'energy_share' THEN 'energy_share'
    WHEN sr.basis_hindernis = 'nutrient_density' THEN 'nutrient_density'
    ELSE 'complete'
  END AS reference_status,
  p.age_years AS profile_age_years,
  p.biological_sex AS profile_biological_sex,
  p.is_pregnant AS profile_is_pregnant,
  p.is_lactating AS profile_is_lactating,
  sr.source,
  sr.source_locator,
  sr.notes
FROM day_values dv
CROSS JOIN profile_one p
JOIN nutrition.nutrient_defs nd ON nd.code = dv.nutrient_code
LEFT JOIN selected_references sr ON sr.nutrient_code = dv.nutrient_code
ORDER BY nd.display_tier, nd.sort_index, sr.reference_kind NULLS LAST;
$$;


ALTER FUNCTION nutrition.daily_reference_assessment(p_user_id uuid, p_entry_date date) OWNER TO postgres;

--
-- Name: FUNCTION daily_reference_assessment(p_user_id uuid, p_entry_date date); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.daily_reference_assessment(p_user_id uuid, p_entry_date date) IS 'C-47/C-161: Numerischer Vergleich von daily_nutrient_summary_long mit nutrient_reference_values anhand public.profiles. Fuehrt reference_kind und reference_direction mit; keine Ampel, kein Score, keine Wortbewertung. C-54: Fuehrt nutrient_display_tier aus nutrient_defs mit, damit die Anzeige Haupt- und Nebenwerte ordnen kann. C-52: Bewertet Linolsaeure und Alpha-Linolensaeure gegen die Goals-Grammziele aus EFSA-Energieprozent. Bei *_missing > 0 bleibt reference_pct NULL, damit eine unvollstaendige Summe nicht als Deckung erscheint.';


--
-- Name: food_categories_tree(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.food_categories_tree() RETURNS json
    LANGUAGE sql STABLE
    AS $$
WITH category_counts AS (
  SELECT category_id, COUNT(*)::int AS food_count
  FROM nutrition.foods
  WHERE category_id IS NOT NULL
  GROUP BY category_id
),
nodes AS (
  SELECT
    fc.id,
    fc.slug,
    fc.name_de,
    fc.name_en,
    COALESCE(fc.name_th, '') AS name_th,
    fc.parent_id,
    fc.level,
    fc.sort_order,
    COALESCE(cc.food_count, 0) AS direct_count
  FROM nutrition.food_categories fc
  LEFT JOIN category_counts cc ON cc.category_id = fc.id
),
level4 AS (
  SELECT n.*, '[]'::json AS children, n.direct_count AS subtree_count
  FROM nodes n
  WHERE n.level = 4
),
level3 AS (
  SELECT
    n.*,
    COALESCE(json_agg(json_build_object(
      'id', c.id,
      'slug', c.slug,
      'name_de', c.name_de,
      'name_en', c.name_en,
      'name_th', c.name_th,
      'level', c.level,
      'sort_order', c.sort_order,
      'count', c.subtree_count,
      'children', c.children
    ) ORDER BY c.sort_order, c.name_de) FILTER (WHERE c.id IS NOT NULL), '[]'::json) AS children,
    n.direct_count + COALESCE(SUM(c.subtree_count), 0)::int AS subtree_count
  FROM nodes n
  LEFT JOIN level4 c ON c.parent_id = n.id
  WHERE n.level = 3
  GROUP BY n.id, n.slug, n.name_de, n.name_en, n.name_th, n.parent_id, n.level, n.sort_order, n.direct_count
),
level2 AS (
  SELECT
    n.*,
    COALESCE(json_agg(json_build_object(
      'id', c.id,
      'slug', c.slug,
      'name_de', c.name_de,
      'name_en', c.name_en,
      'name_th', c.name_th,
      'level', c.level,
      'sort_order', c.sort_order,
      'count', c.subtree_count,
      'children', c.children
    ) ORDER BY c.sort_order, c.name_de) FILTER (WHERE c.id IS NOT NULL), '[]'::json) AS children,
    n.direct_count + COALESCE(SUM(c.subtree_count), 0)::int AS subtree_count
  FROM nodes n
  LEFT JOIN level3 c ON c.parent_id = n.id
  WHERE n.level = 2
  GROUP BY n.id, n.slug, n.name_de, n.name_en, n.name_th, n.parent_id, n.level, n.sort_order, n.direct_count
),
level1 AS (
  SELECT
    n.*,
    COALESCE(json_agg(json_build_object(
      'id', c.id,
      'slug', c.slug,
      'name_de', c.name_de,
      'name_en', c.name_en,
      'name_th', c.name_th,
      'level', c.level,
      'sort_order', c.sort_order,
      'count', c.subtree_count,
      'children', c.children
    ) ORDER BY c.sort_order, c.name_de) FILTER (WHERE c.id IS NOT NULL), '[]'::json) AS children,
    n.direct_count + COALESCE(SUM(c.subtree_count), 0)::int AS subtree_count
  FROM nodes n
  LEFT JOIN level2 c ON c.parent_id = n.id
  WHERE n.level = 1
  GROUP BY n.id, n.slug, n.name_de, n.name_en, n.name_th, n.parent_id, n.level, n.sort_order, n.direct_count
)
SELECT COALESCE(json_agg(json_build_object(
  'id', id,
  'slug', slug,
  'name_de', name_de,
  'name_en', name_en,
  'name_th', name_th,
  'level', level,
  'sort_order', sort_order,
  'count', subtree_count,
  'children', children
) ORDER BY sort_order, name_de), '[]'::json)
FROM level1
$$;


ALTER FUNCTION nutrition.food_categories_tree() OWNER TO postgres;

--
-- Name: food_nutrient_snapshot(text, uuid, uuid, numeric); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.food_nutrient_snapshot(p_food_source text, p_food_id uuid, p_custom_food_id uuid, p_amount_g numeric) RETURNS TABLE(food_name text, enercc numeric, prot625 numeric, fat numeric, cho numeric, fibt numeric, sugar numeric, fasat numeric, nacl numeric, water_g numeric, nutrients jsonb)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
  IF p_amount_g IS NULL OR p_amount_g <= 0 THEN
    RAISE EXCEPTION 'food_nutrient_snapshot: amount_g muss > 0 sein'
      USING ERRCODE = '23514';
  END IF;

  IF p_food_source = 'bls' THEN
    RETURN QUERY
    SELECT
      COALESCE(NULLIF(f.name_display_de, ''), f.name_de) AS food_name,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'ENERCC') AS enercc,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'PROT625') AS prot625,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'FAT') AS fat,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'CHO') AS cho,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'FIBT') AS fibt,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'SUGAR') AS sugar,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'FASAT') AS fasat,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'NACL') AS nacl,
      max(round(fn.value * p_amount_g / 100, 5)) FILTER (WHERE fn.nutrient_code = 'WATER') AS water_g,
      COALESCE(jsonb_object_agg(fn.nutrient_code, round(fn.value * p_amount_g / 100, 5))
        FILTER (WHERE fn.nutrient_code IS NOT NULL), '{}'::jsonb) AS nutrients
    FROM nutrition.foods f
    LEFT JOIN nutrition.food_nutrients fn ON fn.food_id = f.id
    WHERE f.id = p_food_id
    GROUP BY f.id, f.name_display_de, f.name_de;

    RETURN;
  END IF;

  IF p_food_source = 'custom' THEN
    RETURN QUERY
    SELECT
      fc.name_de AS food_name,
      round(fc.enercc * p_amount_g / 100, 5) AS enercc,
      round(fc.prot625 * p_amount_g / 100, 5) AS prot625,
      round(fc.fat * p_amount_g / 100, 5) AS fat,
      round(fc.cho * p_amount_g / 100, 5) AS cho,
      round(fc.fibt * p_amount_g / 100, 5) AS fibt,
      round(fc.sugar * p_amount_g / 100, 5) AS sugar,
      round(fc.fasat * p_amount_g / 100, 5) AS fasat,
      round(fc.nacl * p_amount_g / 100, 5) AS nacl,
      round(fc.water_g * p_amount_g / 100, 5) AS water_g,
      jsonb_strip_nulls(jsonb_build_object(
        'ENERCC', round(fc.enercc * p_amount_g / 100, 5),
        'PROT625', round(fc.prot625 * p_amount_g / 100, 5),
        'FAT', round(fc.fat * p_amount_g / 100, 5),
        'CHO', round(fc.cho * p_amount_g / 100, 5),
        'FIBT', round(fc.fibt * p_amount_g / 100, 5),
        'SUGAR', round(fc.sugar * p_amount_g / 100, 5),
        'FASAT', round(fc.fasat * p_amount_g / 100, 5),
        'NACL', round(fc.nacl * p_amount_g / 100, 5),
        'WATER', round(fc.water_g * p_amount_g / 100, 5),
        'ALC', round(fc.alc * p_amount_g / 100, 5),
        'VITA', round(fc.vita_ug * p_amount_g / 100, 5),
        'VITD', round(fc.vitd_ug * p_amount_g / 100, 5),
        'VITE', round(fc.vite_mg * p_amount_g / 100, 5),
        'VITK', round(fc.vitk_ug * p_amount_g / 100, 5),
        'VITC', round(fc.vitc_mg * p_amount_g / 100, 5),
        'THIA', round(fc.thia_mg * p_amount_g / 100, 5),
        'RIBF', round(fc.ribf_mg * p_amount_g / 100, 5),
        'NIA', round(fc.nia_mg * p_amount_g / 100, 5),
        'VITB6', round(fc.vitb6_ug * p_amount_g / 100, 5),
        'FOL', round(fc.fol_ug * p_amount_g / 100, 5),
        'VITB12', round(fc.vitb12_ug * p_amount_g / 100, 5),
        'NA', round(fc.na_mg * p_amount_g / 100, 5),
        'K', round(fc.k_mg * p_amount_g / 100, 5),
        'CA', round(fc.ca_mg * p_amount_g / 100, 5),
        'MG', round(fc.mg_mg * p_amount_g / 100, 5),
        'P', round(fc.p_mg * p_amount_g / 100, 5),
        'FE', round(fc.fe_mg * p_amount_g / 100, 5),
        'ZN', round(fc.zn_mg * p_amount_g / 100, 5),
        'ID', round(fc.id_ug * p_amount_g / 100, 5),
        'CU', round(fc.cu_ug * p_amount_g / 100, 5),
        'MN', round(fc.mn_ug * p_amount_g / 100, 5)
      )) AS nutrients
    FROM nutrition.foods_custom fc
    WHERE fc.id = p_custom_food_id;

    RETURN;
  END IF;

  RAISE EXCEPTION 'food_nutrient_snapshot: unbekannte Quelle %', p_food_source
    USING ERRCODE = '23514';
END;
$$;


ALTER FUNCTION nutrition.food_nutrient_snapshot(p_food_source text, p_food_id uuid, p_custom_food_id uuid, p_amount_g numeric) OWNER TO postgres;

--
-- Name: food_preferences_read(uuid); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.food_preferences_read(p_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
WITH prefs AS (
  SELECT
    fp.user_id,
    fp.diet_type,
    COALESCE(fp.allergies, '{}'::text[]) AS allergies,
    COALESCE(fp.intolerances, '{}'::text[]) AS intolerances,
    COALESCE(fp.general_exclusions, '{}'::text[]) AS general_exclusions,
    COALESCE(fp.preferred_cuisines, '{}'::text[]) AS preferred_cuisines,
    fp.meals_per_day,
    fp.snacks_per_day,
    fp.cooking_skill,
    fp.prep_time_max_min,
    fp.budget_level,
    fp.meal_prep_ok,
    fp.planner_notes,
    fp.updated_at
  FROM nutrition.food_preferences fp
  WHERE fp.user_id = p_user_id
),
items AS (
  SELECT
    fpi.id,
    fpi.user_id,
    fpi.preference,
    fpi.strength,
    fpi.target_type,
    fpi.food_id,
    f.bls_code,
    COALESCE(NULLIF(f.name_display_de, ''), f.name_de, f.bls_code) AS food_name,
    fpi.category_id,
    fc.slug AS category_slug,
    fc.name_de AS category_name_de,
    fpi.tag_code,
    td.name_de AS tag_name_de,
    fpi.cuisine_code,
    fpi.exclusion_preset_code,
    fpi.catalog_item_code,
    fpi.source,
    fpi.created_at,
    CASE
      WHEN fpi.preference = 'hard_exclude'
        OR fpi.strength = 'hard_exclude' THEN 'hard'
      WHEN fpi.strength = 'strong_avoid' THEN 'strong'
      WHEN fpi.preference = 'disliked'
        OR fpi.strength = 'soft_dislike' THEN 'soft'
      WHEN fpi.preference = 'liked'
        OR fpi.strength IN ('like', 'boost') THEN 'boost'
      ELSE 'neutral'
    END AS constraint_level
  FROM nutrition.food_preference_items fpi
  LEFT JOIN nutrition.foods f ON f.id = fpi.food_id
  LEFT JOIN nutrition.food_categories fc ON fc.id = fpi.category_id
  LEFT JOIN nutrition.tag_definitions td ON td.code = fpi.tag_code
  WHERE fpi.user_id = p_user_id
),
item_json AS (
  SELECT COALESCE(jsonb_agg(
    jsonb_strip_nulls(jsonb_build_object(
      'id', id,
      'preference', preference,
      'strength', strength,
      'constraint_level', constraint_level,
      'target_type', target_type,
      'food_id', food_id,
      'bls_code', bls_code,
      'food_name', food_name,
      'category_id', category_id,
      'category_slug', category_slug,
      'category_name_de', category_name_de,
      'tag_code', tag_code,
      'tag_name_de', tag_name_de,
      'cuisine_code', cuisine_code,
      'exclusion_preset_code', exclusion_preset_code,
      'catalog_item_code', catalog_item_code,
      'source', source,
      'created_at', created_at
    ))
    ORDER BY constraint_level, target_type, food_name, category_name_de, tag_code, cuisine_code
  ), '[]'::jsonb) AS value
  FROM items
),
search_levels AS (
  SELECT
    COALESCE(jsonb_agg(to_jsonb(i) - 'constraint_level') FILTER (WHERE constraint_level = 'hard'), '[]'::jsonb) AS hard,
    COALESCE(jsonb_agg(to_jsonb(i) - 'constraint_level') FILTER (WHERE constraint_level = 'strong'), '[]'::jsonb) AS strong,
    COALESCE(jsonb_agg(to_jsonb(i) - 'constraint_level') FILTER (WHERE constraint_level = 'soft'), '[]'::jsonb) AS soft,
    COALESCE(jsonb_agg(to_jsonb(i) - 'constraint_level') FILTER (WHERE constraint_level = 'boost'), '[]'::jsonb) AS boost
  FROM (
    SELECT
      constraint_level,
      target_type,
      food_id,
      category_id,
      tag_code,
      cuisine_code,
      exclusion_preset_code,
      catalog_item_code,
      preference,
      strength
    FROM items
    WHERE constraint_level <> 'neutral'
    ORDER BY constraint_level, target_type
  ) i
)
SELECT jsonb_build_object(
  'user_id', p_user_id,
  'preferences', COALESCE((
    SELECT jsonb_build_object(
      'diet_type', diet_type,
      'allergies', allergies,
      'intolerances', intolerances,
      'general_exclusions', general_exclusions,
      'preferred_cuisines', preferred_cuisines,
      'meals_per_day', meals_per_day,
      'snacks_per_day', snacks_per_day,
      'cooking_skill', cooking_skill,
      'prep_time_max_min', prep_time_max_min,
      'budget_level', budget_level,
      'meal_prep_ok', meal_prep_ok,
      'planner_notes', planner_notes,
      'updated_at', updated_at
    )
    FROM prefs
  ), jsonb_build_object(
    'diet_type', 'omnivore',
    'allergies', '[]'::jsonb,
    'intolerances', '[]'::jsonb,
    'general_exclusions', '[]'::jsonb,
    'preferred_cuisines', '[]'::jsonb,
    'meals_per_day', 3,
    'snacks_per_day', 1,
    'cooking_skill', 'intermediate',
    'prep_time_max_min', 30,
    'budget_level', 'medium',
    'meal_prep_ok', false,
    'planner_notes', '',
    'updated_at', NULL
  )),
  'items', (SELECT value FROM item_json),
  'search_application', jsonb_build_object(
    'hard', (SELECT hard FROM search_levels),
    'strong', (SELECT strong FROM search_levels),
    'soft', (SELECT soft FROM search_levels),
    'boost', (SELECT boost FROM search_levels)
  )
)
$$;


ALTER FUNCTION nutrition.food_preferences_read(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION food_preferences_read(p_user_id uuid); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.food_preferences_read(p_user_id uuid) IS 'G-11a: liest die Nutrition-Praeferenzen eines Nutzers und bereitet die vier Suchstufen hard/strong/soft/boost vor. SECURITY INVOKER: RLS der Tabellen bleibt wirksam.';


--
-- Name: food_preferences_write(uuid, jsonb, jsonb); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.food_preferences_write(p_user_id uuid, p_preferences jsonb, p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_items jsonb := COALESCE(p_items, '[]'::jsonb);
  v_preference_rows integer;
  v_item_count integer;
  v_touched_items integer;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'food_preferences_write: p_user_id is required';
  END IF;
  IF COALESCE(jsonb_typeof(p_preferences), 'object') <> 'object' THEN
    RAISE EXCEPTION 'food_preferences_write: p_preferences must be an object';
  END IF;
  IF jsonb_typeof(v_items) <> 'array' THEN
    RAISE EXCEPTION 'food_preferences_write: p_items must be an array';
  END IF;

  INSERT INTO nutrition.food_preferences (
    user_id,
    diet_type,
    allergies,
    intolerances,
    general_exclusions,
    preferred_cuisines,
    meals_per_day,
    snacks_per_day,
    cooking_skill,
    prep_time_max_min,
    budget_level,
    meal_prep_ok,
    planner_notes,
    updated_at
  )
  VALUES (
    p_user_id,
    COALESCE(NULLIF(p_preferences->>'diet_type', ''), 'omnivore'),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_preferences->'allergies', '[]'::jsonb))), '{}'::text[]),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_preferences->'intolerances', '[]'::jsonb))), '{}'::text[]),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_preferences->'general_exclusions', '[]'::jsonb))), '{}'::text[]),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_preferences->'preferred_cuisines', '[]'::jsonb))), '{}'::text[]),
    COALESCE((p_preferences->>'meals_per_day')::integer, 3),
    COALESCE((p_preferences->>'snacks_per_day')::integer, 1),
    COALESCE(NULLIF(p_preferences->>'cooking_skill', ''), 'intermediate'),
    COALESCE((p_preferences->>'prep_time_max_min')::integer, 30),
    COALESCE(NULLIF(p_preferences->>'budget_level', ''), 'medium'),
    COALESCE((p_preferences->>'meal_prep_ok')::boolean, false),
    COALESCE(p_preferences->>'planner_notes', ''),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    diet_type = EXCLUDED.diet_type,
    allergies = EXCLUDED.allergies,
    intolerances = EXCLUDED.intolerances,
    general_exclusions = EXCLUDED.general_exclusions,
    preferred_cuisines = EXCLUDED.preferred_cuisines,
    meals_per_day = EXCLUDED.meals_per_day,
    snacks_per_day = EXCLUDED.snacks_per_day,
    cooking_skill = EXCLUDED.cooking_skill,
    prep_time_max_min = EXCLUDED.prep_time_max_min,
    budget_level = EXCLUDED.budget_level,
    meal_prep_ok = EXCLUDED.meal_prep_ok,
    planner_notes = EXCLUDED.planner_notes,
    updated_at = now();

  GET DIAGNOSTICS v_preference_rows = ROW_COUNT;
  IF v_preference_rows <> 1 THEN
    RAISE EXCEPTION 'food_preferences_write: no preference row written for %', p_user_id;
  END IF;

  IF to_regclass('pg_temp.food_preferences_write_items') IS NOT NULL THEN
    DROP TABLE pg_temp.food_preferences_write_items;
  END IF;
  CREATE TEMP TABLE food_preferences_write_items ON COMMIT DROP AS
  SELECT
    row_number() OVER () AS item_no,
    x.preference,
    COALESCE(x.strength, 'neutral') AS strength,
    x.target_type,
    x.food_id,
    x.category_id,
    NULLIF(x.tag_code, '') AS tag_code,
    NULLIF(x.cuisine_code, '') AS cuisine_code,
    NULLIF(x.exclusion_preset_code, '') AS exclusion_preset_code,
    NULLIF(x.catalog_item_code, '') AS catalog_item_code,
    COALESCE(NULLIF(x.source, ''), 'user') AS source,
    concat_ws(':',
      x.target_type,
      COALESCE(x.food_id::text, x.category_id::text, NULLIF(x.tag_code, ''),
        NULLIF(x.cuisine_code, ''), NULLIF(x.exclusion_preset_code, ''),
        NULLIF(x.catalog_item_code, ''))
    ) AS item_key
  FROM jsonb_to_recordset(v_items) AS x(
    preference text,
    strength text,
    target_type text,
    food_id uuid,
    category_id uuid,
    tag_code text,
    cuisine_code text,
    exclusion_preset_code text,
    catalog_item_code text,
    source text
  );

  SELECT COUNT(*) INTO v_item_count FROM pg_temp.food_preferences_write_items;
  IF EXISTS (
    SELECT 1
    FROM pg_temp.food_preferences_write_items
    GROUP BY item_key
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'food_preferences_write: duplicate preference item in payload';
  END IF;

  -- C-156: Einstellungen ersetzen nur Einstellungen. Ein Daumen- oder
  -- Suchtreffer-Eintrag, den die Oberflaeche nicht mitsendet, darf nicht
  -- durch einen Kachel-Speicherlauf verschwinden.
  DELETE FROM nutrition.food_preference_items existing
  WHERE existing.user_id = p_user_id
    AND existing.source = 'settings'
    AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.food_preferences_write_items incoming
      WHERE incoming.target_type = existing.target_type
        AND COALESCE(incoming.food_id, '00000000-0000-0000-0000-000000000000'::uuid)
          = COALESCE(existing.food_id, '00000000-0000-0000-0000-000000000000'::uuid)
        AND COALESCE(incoming.category_id, '00000000-0000-0000-0000-000000000000'::uuid)
          = COALESCE(existing.category_id, '00000000-0000-0000-0000-000000000000'::uuid)
        AND COALESCE(incoming.tag_code, '') = COALESCE(existing.tag_code, '')
        AND COALESCE(incoming.cuisine_code, '') = COALESCE(existing.cuisine_code, '')
        AND COALESCE(incoming.exclusion_preset_code, '') = COALESCE(existing.exclusion_preset_code, '')
        AND COALESCE(incoming.catalog_item_code, '') = COALESCE(existing.catalog_item_code, '')
    );

  WITH updated AS (
    UPDATE nutrition.food_preference_items existing
       SET preference = incoming.preference,
           strength = incoming.strength,
           source = COALESCE(NULLIF(existing.source, ''), incoming.source)
      FROM pg_temp.food_preferences_write_items incoming
     WHERE existing.user_id = p_user_id
       AND incoming.target_type = existing.target_type
       AND COALESCE(incoming.food_id, '00000000-0000-0000-0000-000000000000'::uuid)
         = COALESCE(existing.food_id, '00000000-0000-0000-0000-000000000000'::uuid)
       AND COALESCE(incoming.category_id, '00000000-0000-0000-0000-000000000000'::uuid)
         = COALESCE(existing.category_id, '00000000-0000-0000-0000-000000000000'::uuid)
       AND COALESCE(incoming.tag_code, '') = COALESCE(existing.tag_code, '')
       AND COALESCE(incoming.cuisine_code, '') = COALESCE(existing.cuisine_code, '')
       AND COALESCE(incoming.exclusion_preset_code, '') = COALESCE(existing.exclusion_preset_code, '')
       AND COALESCE(incoming.catalog_item_code, '') = COALESCE(existing.catalog_item_code, '')
    RETURNING incoming.item_no
  ), inserted AS (
    INSERT INTO nutrition.food_preference_items (
      user_id,
      preference,
      strength,
      target_type,
      food_id,
      category_id,
      tag_code,
      cuisine_code,
      exclusion_preset_code,
      catalog_item_code,
      source
    )
    SELECT
      p_user_id,
      incoming.preference,
      incoming.strength,
      incoming.target_type,
      incoming.food_id,
      incoming.category_id,
      incoming.tag_code,
      incoming.cuisine_code,
      incoming.exclusion_preset_code,
      incoming.catalog_item_code,
      incoming.source
    FROM pg_temp.food_preferences_write_items incoming
    WHERE NOT EXISTS (
      SELECT 1
      FROM updated u
      WHERE u.item_no = incoming.item_no
    )
    RETURNING 1
  )
  SELECT (SELECT COUNT(*) FROM updated) + (SELECT COUNT(*) FROM inserted)
    INTO v_touched_items;

  IF v_touched_items <> v_item_count THEN
    RAISE EXCEPTION 'food_preferences_write: wrote % of % preference items',
      v_touched_items, v_item_count;
  END IF;

  RETURN nutrition.food_preferences_read(p_user_id);
END;
$$;


ALTER FUNCTION nutrition.food_preferences_write(p_user_id uuid, p_preferences jsonb, p_items jsonb) OWNER TO postgres;

--
-- Name: FUNCTION food_preferences_write(p_user_id uuid, p_preferences jsonb, p_items jsonb); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.food_preferences_write(p_user_id uuid, p_preferences jsonb, p_items jsonb) IS 'C-156: schreibt Basis-Praeferenzen und fuehrt Preference-Items key-basiert zusammen. Nur source=settings wird durch die Einstellungsseite ersetzt; search_thumb und andere Herkuenfte bleiben erhalten. SECURITY INVOKER: Tabellenrechte, Checks, FKs und RLS bleiben die Zugriffskontrolle.';


--
-- Name: food_search(text, text, text[], uuid, text, uuid, text, text, integer, integer, text[], text[], boolean, jsonb, uuid, jsonb); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.food_search(p_query text, p_normalized_query text, p_tokens text[], p_selected_food_id uuid, p_category_slug text, p_category_id uuid, p_tag_code text, p_sort text, p_limit integer, p_offset integer, p_preparations text[] DEFAULT NULL::text[], p_groups text[] DEFAULT NULL::text[], p_basics_only boolean DEFAULT false, p_token_groups jsonb DEFAULT NULL::jsonb, p_user_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT NULL::jsonb) RETURNS json
    LANGUAGE sql STABLE
    AS $$
WITH RECURSIVE params AS (
  SELECT
    LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100) AS lim,
    GREATEST(COALESCE(p_offset, 0), 0) AS off,
    CASE WHEN p_sort IN ('relevance','protein_desc','kcal_asc','name_asc') THEN p_sort ELSE 'relevance' END AS sort
),
filter_tag_groups AS MATERIALIZED (
  SELECT g.gruppe, g.nr
  FROM jsonb_array_elements(
    CASE
      WHEN p_filters IS NOT NULL
       AND jsonb_typeof(COALESCE(p_filters->'tag_groups', p_filters->'include_tag_groups')) = 'array'
      THEN COALESCE(p_filters->'tag_groups', p_filters->'include_tag_groups')
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS g(gruppe, nr)
  WHERE jsonb_typeof(g.gruppe) = 'array'
    AND jsonb_array_length(g.gruppe) > 0
),
filter_exclude_tags AS MATERIALIZED (
  SELECT DISTINCT code
  FROM jsonb_array_elements_text(
    CASE
      WHEN p_filters IS NOT NULL
       AND jsonb_typeof(COALESCE(p_filters->'exclude_tag_codes', p_filters->'exclude_tags')) = 'array'
      THEN COALESCE(p_filters->'exclude_tag_codes', p_filters->'exclude_tags')
      ELSE '[]'::jsonb
    END
  ) AS t(code)
  WHERE code <> ''
),
filter_processing_levels AS MATERIALIZED (
  SELECT DISTINCT level
  FROM jsonb_array_elements_text(
    CASE
      WHEN p_filters IS NOT NULL
       AND jsonb_typeof(p_filters->'processing_levels') = 'array'
      THEN p_filters->'processing_levels'
      ELSE '[]'::jsonb
    END
  ) AS t(level)
  WHERE level <> ''
),
filter_exclude_processing_levels AS MATERIALIZED (
  SELECT DISTINCT level
  FROM jsonb_array_elements_text(
    CASE
      WHEN p_filters IS NOT NULL
       AND jsonb_typeof(p_filters->'exclude_processing_levels') = 'array'
      THEN p_filters->'exclude_processing_levels'
      ELSE '[]'::jsonb
    END
  ) AS t(level)
  WHERE level <> ''
),
filter_state AS MATERIALIZED (
  SELECT
    EXISTS (SELECT 1 FROM filter_tag_groups) AS has_tag_groups,
    EXISTS (SELECT 1 FROM filter_exclude_tags) AS has_exclude_tags,
    EXISTS (SELECT 1 FROM filter_processing_levels) AS has_processing_levels,
    EXISTS (SELECT 1 FROM filter_exclude_processing_levels) AS has_exclude_processing_levels
),
user_preference AS (
  SELECT
    fp.user_id,
    COALESCE(fp.diet_type, 'omnivore') AS diet_type,
    COALESCE(fp.allergies, '{}'::text[]) AS allergies,
    COALESCE(fp.intolerances, '{}'::text[]) AS intolerances,
    COALESCE(fp.general_exclusions, '{}'::text[]) AS general_exclusions
  FROM nutrition.food_preferences fp
  WHERE p_user_id IS NOT NULL
    AND fp.user_id = p_user_id
),
preference_items AS MATERIALIZED (
  SELECT
    fpi.id,
    fpi.user_id,
    fpi.preference,
    fpi.strength,
    fpi.target_type,
    fpi.food_id,
    fpi.category_id,
    fpi.tag_code,
    fpi.cuisine_code,
    fpi.exclusion_preset_code,
    CASE
      WHEN fpi.preference = 'hard_exclude'
        OR fpi.strength = 'hard_exclude' THEN 'hard'
      WHEN fpi.strength = 'strong_avoid' THEN 'strong'
      WHEN fpi.preference = 'disliked'
        OR fpi.strength = 'soft_dislike' THEN 'soft'
      WHEN fpi.preference = 'liked'
        OR fpi.strength IN ('like', 'boost') THEN 'boost'
      ELSE 'neutral'
    END AS constraint_level
  FROM nutrition.food_preference_items fpi
  WHERE p_user_id IS NOT NULL
    AND fpi.user_id = p_user_id
),
preference_category_tree AS (
  SELECT pi.id AS item_id, pi.category_id
  FROM preference_items pi
  WHERE pi.target_type = 'category'
    AND pi.category_id IS NOT NULL
  UNION ALL
  SELECT pct.item_id, fc.id
  FROM preference_category_tree pct
  JOIN nutrition.food_categories fc ON fc.parent_id = pct.category_id
),
preference_category_ancestors AS (
  SELECT pi.id AS item_id, pi.category_id
  FROM preference_items pi
  WHERE pi.target_type = 'category'
    AND pi.category_id IS NOT NULL
  UNION ALL
  SELECT pca.item_id, fc.parent_id
  FROM preference_category_ancestors pca
  JOIN nutrition.food_categories fc ON fc.id = pca.category_id
  WHERE fc.parent_id IS NOT NULL
),
allergy_tag_map AS (
  SELECT * FROM (VALUES
    ('gluten_wheat', 'contains_gluten'),
    ('gluten', 'contains_gluten'),
    ('tree_nuts', 'contains_nuts'),
    ('peanuts', 'contains_nuts'),
    ('nuts', 'contains_nuts'),
    ('lactose', 'contains_lactose'),
    ('milk_protein', 'contains_lactose')
  ) AS m(source_code, tag_code)
),
preference_targets AS MATERIALIZED (
  SELECT
    pi.food_id,
    pi.constraint_level,
    'food'::text AS match_type,
    CASE
      WHEN pi.constraint_level = 'boost' THEN 100
      WHEN pi.constraint_level = 'soft' THEN -100
      WHEN pi.constraint_level = 'strong' THEN -75
      ELSE 0
    END AS score,
    30 AS specificity
  FROM preference_items pi
  WHERE pi.target_type = 'food'
    AND pi.food_id IS NOT NULL
    AND pi.constraint_level <> 'neutral'

  UNION ALL

  SELECT
    f.id,
    pi.constraint_level,
    'category'::text,
    CASE
      WHEN pi.constraint_level = 'boost' THEN 50
      WHEN pi.constraint_level = 'soft' THEN -50
      WHEN pi.constraint_level = 'strong' THEN -40
      ELSE 0
    END,
    20
  FROM preference_items pi
  JOIN (
    SELECT item_id, category_id FROM preference_category_tree
    UNION
    SELECT item_id, category_id FROM preference_category_ancestors
  ) pct ON pct.item_id = pi.id
  JOIN nutrition.foods f ON f.category_id = pct.category_id
  WHERE pi.constraint_level <> 'neutral'

  UNION ALL

  SELECT
    ft.food_id,
    pi.constraint_level,
    'tag'::text,
    CASE
      WHEN pi.constraint_level = 'boost' THEN 30
      WHEN pi.constraint_level = 'soft' THEN -30
      WHEN pi.constraint_level = 'strong' THEN -25
      ELSE 0
    END,
    10
  FROM preference_items pi
  JOIN nutrition.food_tags ft ON ft.tag_code = pi.tag_code
  WHERE pi.target_type = 'tag'
    AND pi.tag_code IS NOT NULL
    AND pi.constraint_level <> 'neutral'

  UNION ALL

  SELECT
    epm.food_id,
    pi.constraint_level,
    'exclusion_preset'::text,
    CASE
      WHEN pi.constraint_level = 'boost' THEN 30
      WHEN pi.constraint_level = 'soft' THEN -30
      WHEN pi.constraint_level = 'strong' THEN -25
      ELSE 0
    END,
    10
  FROM preference_items pi
  JOIN nutrition.exclusion_preset_matches epm
    ON epm.preset_code = pi.exclusion_preset_code
  WHERE pi.target_type = 'exclusion_preset'
    AND pi.exclusion_preset_code IS NOT NULL
    AND pi.constraint_level <> 'neutral'

  UNION ALL

  SELECT
    ft.food_id,
    'hard'::text,
    'allergy'::text,
    0,
    100
  FROM user_preference up
  JOIN allergy_tag_map m ON m.source_code = ANY(up.allergies)
  JOIN nutrition.food_tags ft ON ft.tag_code = m.tag_code

  UNION ALL

  SELECT
    ft.food_id,
    'strong'::text,
    'intolerance'::text,
    -25,
    90
  FROM user_preference up
  JOIN allergy_tag_map m ON m.source_code = ANY(up.intolerances)
  JOIN nutrition.food_tags ft ON ft.tag_code = m.tag_code

  UNION ALL

  SELECT
    ft.food_id,
    'hard'::text,
    'general_tag'::text,
    0,
    80
  FROM user_preference up
  JOIN nutrition.tag_definitions td ON td.code = ANY(up.general_exclusions)
  JOIN nutrition.food_tags ft ON ft.tag_code = td.code

  UNION ALL

  SELECT
    epm.food_id,
    'hard'::text,
    'general_preset'::text,
    0,
    80
  FROM user_preference up
  JOIN nutrition.exclusion_presets ep ON ep.code = ANY(up.general_exclusions)
  JOIN nutrition.exclusion_preset_matches epm ON epm.preset_code = ep.code

  UNION ALL

  SELECT
    f.id,
    'hard'::text,
    'diet_type'::text,
    0,
    70
  FROM user_preference up
  JOIN nutrition.foods f ON TRUE
  WHERE up.diet_type = 'vegan'
    AND NOT EXISTS (
      SELECT 1 FROM nutrition.food_tags ft
      WHERE ft.food_id = f.id AND ft.tag_code = 'vegan'
    )

  UNION ALL

  SELECT
    f.id,
    'hard'::text,
    'diet_type'::text,
    0,
    70
  FROM user_preference up
  JOIN nutrition.foods f ON TRUE
  WHERE up.diet_type = 'vegetarian'
    AND NOT EXISTS (
      SELECT 1 FROM nutrition.food_tags ft
      WHERE ft.food_id = f.id AND ft.tag_code = 'vegetarian'
    )

  UNION ALL

  SELECT
    f.id,
    'hard'::text,
    'diet_type'::text,
    0,
    70
  FROM user_preference up
  JOIN nutrition.foods f ON TRUE
  LEFT JOIN nutrition.food_categories fc ON fc.id = f.category_id
  WHERE up.diet_type = 'pescatarian'
    AND COALESCE(fc.food_group_code, substring(f.bls_code, 1, 1)) IN ('U', 'V', 'W')
),
preference_scores AS NOT MATERIALIZED (
  SELECT
    food_id,
    bool_or(constraint_level = 'hard')
      OR (bool_or(constraint_level = 'strong')
          AND COALESCE(p_normalized_query, '') = '') AS preference_excluded,
    COALESCE((array_agg(score ORDER BY specificity DESC, abs(score) DESC))[1], 0) AS preference_score,
    (array_agg(constraint_level ORDER BY specificity DESC, abs(score) DESC))[1] AS preference_level,
    (array_agg(match_type ORDER BY specificity DESC, abs(score) DESC))[1] AS preference_match_type,
    COALESCE(jsonb_agg(DISTINCT jsonb_build_object(
      'level', constraint_level,
      'type', match_type,
      'score', score
    )), '[]'::jsonb) AS preference_matches
  FROM nutrition.food_preference_search_targets
  WHERE p_user_id IS NOT NULL
    AND user_id = p_user_id
  GROUP BY food_id
),
matching_foods AS (
  SELECT
    f.id,
    f.bls_code,
    f.name_de,
    f.name_en,
    f.name_th,
    f.name_display_de,
    f.name_display_en,
    f.name_display_th,
    f.category_id,
    f.sort_weight,
    COALESCE(NULLIF(f.name_display_de, ''), f.name_de, f.name_en, f.bls_code) AS source_label,
    CASE
      WHEN p_tokens IS NULL OR cardinality(p_tokens) = 0 THEN 0.5
      -- 1.00  Bestandsname exakt
      WHEN lower(COALESCE(f.name_de, '')) = lower(p_query) THEN 1.0
      -- 0.95  Alias exakt: der Nutzer hat den Begriff genau getroffen,
      --       nur nicht in der Schreibweise des Bestands. Knapp unter
      --       dem Namenstreffer, weil der Bestandsname die genauere
      --       Angabe ist.
      WHEN EXISTS (SELECT 1 FROM nutrition.food_aliases fa
                    WHERE fa.food_id = f.id
                      AND nutrition.search_fold(fa.alias) = p_normalized_query)
        THEN 0.95
      -- 0.85  Bestandsname beginnt mit der Anfrage
      WHEN lower(COALESCE(f.name_de, '')) LIKE lower(p_query) || '%' THEN 0.85
      -- 0.80  Alias beginnt mit der Anfrage
      WHEN EXISTS (SELECT 1 FROM nutrition.food_aliases fa
                    WHERE fa.food_id = f.id
                      AND nutrition.search_fold(fa.alias) LIKE p_normalized_query || '%')
        THEN 0.80
      -- 0.75  Treffer am WORTANFANG im Bestandsnamen. Das ist der
      --       huhn/Suppenhuhn-Fall: "huhn" steckt mitten in
      --       "Suppenhuhn" und traf bisher gleichwertig. Ein Treffer,
      --       der ein Wort beginnt, ist fast immer der gemeinte.
      WHEN nutrition.search_fold(COALESCE(f.name_de,'')) LIKE p_normalized_query || '%'
        OR nutrition.search_fold(COALESCE(f.name_de,'')) LIKE '% ' || p_normalized_query || '%'
        THEN 0.75
      ELSE 0.65
    END AS text_rank,
    fc.slug AS category_slug,
    fc.name_de AS category_name_de,
    m.enercc,
    m.prot625,
    m.fat,
    m.cho,
    COALESCE(tags.tags, ARRAY[]::text[]) AS tags,
    COALESCE(ps.preference_score, 0) AS preference_score,
    COALESCE(ps.preference_level, 'neutral') AS preference_level,
    COALESCE(ps.preference_match_type, '') AS preference_match_type,
    COALESCE(ps.preference_matches, '[]'::jsonb) AS preference_matches
  FROM nutrition.foods f
  LEFT JOIN nutrition.food_categories fc ON fc.id = f.category_id
  LEFT JOIN preference_scores ps ON ps.food_id = f.id
  LEFT JOIN LATERAL (
    SELECT
      MAX(value) FILTER (WHERE nutrient_code='ENERCC') AS enercc,
      MAX(value) FILTER (WHERE nutrient_code='PROT625') AS prot625,
      MAX(value) FILTER (WHERE nutrient_code='FAT') AS fat,
      MAX(value) FILTER (WHERE nutrient_code='CHO') AS cho
    FROM nutrition.food_nutrients fn
    WHERE fn.food_id = f.id
  ) m ON TRUE
  LEFT JOIN LATERAL (
    SELECT array_agg(ft.tag_code ORDER BY td.sort_order, ft.tag_code) AS tags
    FROM nutrition.food_tags ft
    JOIN nutrition.tag_definitions td ON td.code = ft.tag_code
    WHERE ft.food_id = f.id
  ) tags ON TRUE
  WHERE
    NOT COALESCE(ps.preference_excluded, false)
    AND
    -- ACHTUNG: Diese Bedingung steht ZWEIMAL in dieser Funktion
    -- (matching_foods und all_matching_food_ids). Wer eine aendert,
    -- muss die andere mitaendern — sonst weicht `total` von der Liste
    -- ab, wie am 2026-08-14 geschehen.
    --
    -- Zwei Faelle:
    --   p_token_groups gesetzt -> ODER innerhalb einer Gruppe,
    --     UND zwischen den Gruppen. Eine Gruppe traegt ein Wort samt
    --     Zerlegungsteil und Synonymen.
    --   sonst -> die alte Tokenlogik, unveraendert. Sie bleibt die
    --     Rueckfallebene fuer Aufrufer ohne Gruppen.
    (CASE
      WHEN p_token_groups IS NOT NULL AND jsonb_array_length(p_token_groups) > 0 THEN
        -- WARUM jsonb UND NICHT SECHS FESTE text[]-SLOTS:
        -- `[cmd]` Beides gemessen. Die Slot-Fassung sollte den
        -- Trigramm-Index nutzbar machen und war LANGSAMER: 704 ms
        -- gegen 562 ms, weil jeder der sechs Slots einen eigenen
        -- Durchlauf ueber nutrition.foods ausloest — auch die fuenf
        -- leeren einer einwortigen Anfrage.
        --
        -- Der Index greift hier ohnehin nicht, und zwar unabhaengig
        -- von den Gruppen: die Bedingung faltet
        -- concat_ws(bls_code, name_de, name_en, name_th), waehrend
        -- idx_foods_fold_trgm auf search_fold(name_de) liegt. Zwei
        -- verschiedene Ausdruecke, also Seq Scan. Das war schon vor
        -- Block 31 so und ist als Aufgabe notiert, nicht hier geloest.
        --
        -- `[cmd]` Grundkosten der Funktion ohne jede Gruppe: 178 ms
        -- bei leerer Anfrage, 288 ms bei einem Wort. Die Gruppen
        -- kosten zusaetzlich rund 275 ms.
        -- C-17 (2026-08-15): Die Alias-Pruefung lief je Zeile UND je
        -- Alternative. `[cmd]` Der Plan zeigte fuer "huehnerbrust"
        -- einen Index Only Scan auf food_aliases mit loops=14212 und
        -- 43.347 von 44.165 Buffern (98 %) — der Seq Scan auf foods
        -- kostete nur 818. Der Engpass war NICHT der fehlende Index
        -- auf foods, sondern die korrelierte Unterabfrage.
        --
        -- Jetzt liefert nutrition.such_alias_treffer() die Food-IDs je
        -- Gruppe EINMAL. Sie baut ihre Bedingung dynamisch, damit die
        -- Alternativen als Literale im Plan stehen — nur dann nutzt
        -- Postgres idx_food_aliases_fold_trgm.
        -- `[cmd]` 43.316 -> 1.025 Buffer, 260 -> 93 ms, Trefferzahl
        -- unveraendert 31.
        NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(p_token_groups) WITH ORDINALITY AS g(gruppe, nr)
          WHERE NOT (
            EXISTS (
              SELECT 1
              FROM jsonb_array_elements_text(g.gruppe) AS a(alt)
              WHERE nutrition.search_fold(concat_ws(' ', f.bls_code, f.name_de, f.name_en, f.name_th)) LIKE '%' || a.alt || '%'
            )
            OR (g.nr::integer, f.id) IN (
              SELECT t.nr, t.food_id
              FROM nutrition.such_alias_treffer(p_token_groups) t
            )
          )
        )
      ELSE
        (p_tokens IS NULL OR cardinality(p_tokens) = 0 OR NOT EXISTS (
          SELECT 1 FROM unnest(p_tokens) AS t(tok)
          WHERE NOT (
            nutrition.search_fold(concat_ws(' ', f.bls_code, f.name_de, f.name_en, f.name_th)) LIKE '%' || tok || '%'
            OR EXISTS (
              SELECT 1 FROM nutrition.food_aliases fa
              WHERE fa.food_id = f.id
                AND nutrition.search_fold(fa.alias) LIKE '%' || tok || '%'
            )
          )
        ))
    END)
    AND (
      (COALESCE(p_category_slug, '') = '' AND p_category_id IS NULL)
      OR EXISTS (
        SELECT 1
        FROM nutrition.food_categories selected_category
        JOIN nutrition.food_categories assigned_category ON assigned_category.id = f.category_id
        WHERE (CASE
                 WHEN p_category_id IS NOT NULL THEN selected_category.id = p_category_id
                 ELSE selected_category.slug = p_category_slug
               END)
          AND (
            assigned_category.slug = selected_category.slug
            OR assigned_category.parent_id = selected_category.id
            OR assigned_category.parent_id IN (
              SELECT child.id FROM nutrition.food_categories child WHERE child.parent_id = selected_category.id
            )
            OR assigned_category.parent_id IN (
              SELECT grandchild.id
              FROM nutrition.food_categories child
              JOIN nutrition.food_categories grandchild ON grandchild.parent_id = child.id
              WHERE child.parent_id = selected_category.id
            )
          )
      )
    )
    AND (
      COALESCE(p_tag_code, '') = ''
      OR EXISTS (
        SELECT 1 FROM nutrition.food_tags selected_tag
        WHERE selected_tag.food_id = f.id
          AND selected_tag.tag_code = p_tag_code
      )
    )
    -- C-164: Mehrfach-Facetten. `tag_groups` ist ODER innerhalb
    -- einer sichtbaren Gruppe, UND zwischen Gruppen. Ausschluesse
    -- wirken auf die Gesamtmenge, nicht nur auf die aktuelle Seite.
    AND (
      NOT (SELECT has_tag_groups FROM filter_state)
      OR NOT EXISTS (
        SELECT 1
        FROM filter_tag_groups fg
        WHERE NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(fg.gruppe) AS wanted(tag_code)
          JOIN nutrition.food_tags ft ON ft.tag_code = wanted.tag_code
          WHERE ft.food_id = f.id
        )
      )
    )
    AND (
      NOT (SELECT has_exclude_tags FROM filter_state)
      OR NOT EXISTS (
        SELECT 1
        FROM filter_exclude_tags et
        JOIN nutrition.food_tags ft ON ft.tag_code = et.code
        WHERE ft.food_id = f.id
      )
    )
    AND (
      NOT (SELECT has_processing_levels FROM filter_state)
      OR f.processing_level IN (SELECT level FROM filter_processing_levels)
    )
    AND (
      NOT (SELECT has_exclude_processing_levels FROM filter_state)
      OR NOT EXISTS (
        SELECT 1
        FROM filter_exclude_processing_levels ep
        WHERE ep.level = f.processing_level
      )
    )
    -- Zubereitung: Code ODER Wort im Namen. [cmd] Fuer "roh" tragen
    -- 509 Lebensmittel beides, 338 nur den Code, 153 nur das Wort —
    -- eines allein liesse je nach Richtung Hunderte fallen.
    AND (
      p_preparations IS NULL OR cardinality(p_preparations) = 0
      OR EXISTS (
        SELECT 1 FROM nutrition.preparation_kinds pk
        WHERE pk.code = ANY(p_preparations)
          AND (
            nutrition.search_fold(f.name_de) ~ pk.name_pattern
            OR (pk.bls_codes IS NOT NULL
                AND substr(f.bls_code, 5, 3) = ANY(pk.bls_codes))
          )
      )
    )
    -- Warengruppe: C-99 nutzt die Bruecke food_categories -> food_groups.
    -- Der Praefix bleibt Rueckfall fuer Kategorien ohne eindeutige
    -- Gruppe, z.B. X/Y unter der gemischten Fertiggerichte-Wurzel.
    AND (
      p_groups IS NULL OR cardinality(p_groups) = 0
      OR EXISTS (
        SELECT 1
        FROM nutrition.food_categories fcg
        WHERE fcg.id = f.category_id
          AND fcg.food_group_code = ANY(p_groups)
      )
      OR (
        NOT EXISTS (
          SELECT 1
          FROM nutrition.food_categories fcg
          WHERE fcg.id = f.category_id
            AND fcg.food_group_code IS NOT NULL
        )
        AND substr(f.bls_code, 1, 1) = ANY(p_groups)
      )
    )
    -- Nur Grundnahrungsmittel: [cmd] X und Y sind zusammengesetzte
    -- Gerichte (2.050 Eintraege, sort_weight durchgaengig 0).
    AND (
      NOT COALESCE(p_basics_only, false)
      OR NOT EXISTS (
        SELECT 1 FROM nutrition.food_groups fg
        WHERE fg.code = COALESCE(
            (SELECT fcg.food_group_code
             FROM nutrition.food_categories fcg
             WHERE fcg.id = f.category_id),
            substr(f.bls_code, 1, 1)
          )
          AND fg.ist_gericht
      )
    )
  ORDER BY
    CASE WHEN (SELECT sort FROM params) = 'protein_desc' THEN COALESCE(m.prot625, 0) END DESC,
    CASE WHEN (SELECT sort FROM params) = 'kcal_asc' THEN COALESCE(m.enercc, 999999) END ASC,
    CASE WHEN (SELECT sort FROM params) = 'relevance' THEN
      CASE
        WHEN p_tokens IS NULL OR cardinality(p_tokens) = 0 THEN 0.5
        WHEN lower(COALESCE(f.name_de, '')) = lower(p_query) THEN 1.0
        WHEN EXISTS (SELECT 1 FROM nutrition.food_aliases fa
                      WHERE fa.food_id = f.id
                        AND nutrition.search_fold(fa.alias) = p_normalized_query)
          THEN 0.95
        WHEN lower(COALESCE(f.name_de, '')) LIKE lower(p_query) || '%' THEN 0.85
        WHEN EXISTS (SELECT 1 FROM nutrition.food_aliases fa
                      WHERE fa.food_id = f.id
                        AND nutrition.search_fold(fa.alias) LIKE p_normalized_query || '%')
          THEN 0.80
        WHEN nutrition.search_fold(COALESCE(f.name_de,'')) LIKE p_normalized_query || '%'
          OR nutrition.search_fold(COALESCE(f.name_de,'')) LIKE '% ' || p_normalized_query || '%'
          THEN 0.75
        ELSE 0.65
      END
    END DESC,
    CASE WHEN (SELECT sort FROM params) = 'relevance'
         THEN COALESCE(ps.preference_score, 0) END DESC,
    -- BLOCK 32, die Reihenfolge der drei neuen Stufen ist GEMESSEN,
    -- nicht gewaehlt. `[cmd]` Gegen die 37 MealCam-Zutaten:
    --   ohne Regel                      12 von 37 auf Platz 1
    --   nur Wortgrenze (C-20)           12   — allein bringt sie nichts,
    --                                        weil danach das Alphabet
    --                                        entscheidet: alle sieben
    --                                        "Tomate …" stehen gleich
    --   nur Zubereitung (C-25)          23
    --   beide, Wortgrenze zuerst        23
    --   beide, Zubereitung zuerst       24
    --   + Namenskuerze                  29
    -- C-20 traegt also nur ZUSAMMEN mit C-25: sie holt die Tomate-Gruppe
    -- vor die Heringsfilets, und C-25 entscheidet dann innerhalb.
    CASE WHEN (SELECT sort FROM params) = 'relevance'
         THEN nutrition.such_rang_zubereitung(f.bls_code) END DESC,
    CASE WHEN (SELECT sort FROM params) = 'relevance'
         THEN nutrition.such_rang_wortgrenze(f.name_de, p_token_groups) END DESC,
    CASE WHEN (SELECT sort FROM params) IN ('relevance', 'protein_desc') THEN f.sort_weight END DESC NULLS LAST,
    -- Namenskuerze als STICHENTSCHEID, nach sort_weight.
    -- `[cmd]` Die Stufe vor sort_weight zu ziehen wurde gemessen und
    -- verworfen: sie holt zwar lachs, kartoffeln und spinat nach vorn,
    -- zerstoert dafuer aber reis (auf Platz 6, hinter "Reis Mehl"),
    -- mozzarella und mandeln (hinter "Mandeloel") — kurze Namen
    -- gewinnen dann unabhaengig davon, ob sie die Zutat sind.
    -- Unterm Strich beides 31 von 37, aber die spaetere Stellung haelt
    -- 35 statt 34 in den ersten drei. sort_weight leistet dort echte
    -- Arbeit; die Kuerze entscheidet nur, was es gleich gewichtet.
    CASE WHEN (SELECT sort FROM params) = 'relevance'
         THEN length(COALESCE(f.name_de, '')) END ASC,
    COALESCE(NULLIF(f.name_display_de, ''), f.name_de, f.name_en, f.bls_code) ASC,
    f.bls_code ASC
  LIMIT (SELECT lim FROM params)
  OFFSET (SELECT off FROM params)
),
all_matching_food_ids AS (
  SELECT f.id
  FROM nutrition.foods f
  LEFT JOIN preference_scores ps ON ps.food_id = f.id
  WHERE
    NOT COALESCE(ps.preference_excluded, false)
    AND
    -- ACHTUNG: Diese Bedingung steht ZWEIMAL in dieser Funktion
    -- (matching_foods und all_matching_food_ids). Wer eine aendert,
    -- muss die andere mitaendern — sonst weicht `total` von der Liste
    -- ab, wie am 2026-08-14 geschehen.
    --
    -- Zwei Faelle:
    --   p_token_groups gesetzt -> ODER innerhalb einer Gruppe,
    --     UND zwischen den Gruppen. Eine Gruppe traegt ein Wort samt
    --     Zerlegungsteil und Synonymen.
    --   sonst -> die alte Tokenlogik, unveraendert. Sie bleibt die
    --     Rueckfallebene fuer Aufrufer ohne Gruppen.
    (CASE
      WHEN p_token_groups IS NOT NULL AND jsonb_array_length(p_token_groups) > 0 THEN
        -- WARUM jsonb UND NICHT SECHS FESTE text[]-SLOTS:
        -- `[cmd]` Beides gemessen. Die Slot-Fassung sollte den
        -- Trigramm-Index nutzbar machen und war LANGSAMER: 704 ms
        -- gegen 562 ms, weil jeder der sechs Slots einen eigenen
        -- Durchlauf ueber nutrition.foods ausloest — auch die fuenf
        -- leeren einer einwortigen Anfrage.
        --
        -- Der Index greift hier ohnehin nicht, und zwar unabhaengig
        -- von den Gruppen: die Bedingung faltet
        -- concat_ws(bls_code, name_de, name_en, name_th), waehrend
        -- idx_foods_fold_trgm auf search_fold(name_de) liegt. Zwei
        -- verschiedene Ausdruecke, also Seq Scan. Das war schon vor
        -- Block 31 so und ist als Aufgabe notiert, nicht hier geloest.
        --
        -- `[cmd]` Grundkosten der Funktion ohne jede Gruppe: 178 ms
        -- bei leerer Anfrage, 288 ms bei einem Wort. Die Gruppen
        -- kosten zusaetzlich rund 275 ms.
        -- C-17 (2026-08-15): Die Alias-Pruefung lief je Zeile UND je
        -- Alternative. `[cmd]` Der Plan zeigte fuer "huehnerbrust"
        -- einen Index Only Scan auf food_aliases mit loops=14212 und
        -- 43.347 von 44.165 Buffern (98 %) — der Seq Scan auf foods
        -- kostete nur 818. Der Engpass war NICHT der fehlende Index
        -- auf foods, sondern die korrelierte Unterabfrage.
        --
        -- Jetzt liefert nutrition.such_alias_treffer() die Food-IDs je
        -- Gruppe EINMAL. Sie baut ihre Bedingung dynamisch, damit die
        -- Alternativen als Literale im Plan stehen — nur dann nutzt
        -- Postgres idx_food_aliases_fold_trgm.
        -- `[cmd]` 43.316 -> 1.025 Buffer, 260 -> 93 ms, Trefferzahl
        -- unveraendert 31.
        NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(p_token_groups) WITH ORDINALITY AS g(gruppe, nr)
          WHERE NOT (
            EXISTS (
              SELECT 1
              FROM jsonb_array_elements_text(g.gruppe) AS a(alt)
              WHERE nutrition.search_fold(concat_ws(' ', f.bls_code, f.name_de, f.name_en, f.name_th)) LIKE '%' || a.alt || '%'
            )
            OR (g.nr::integer, f.id) IN (
              SELECT t.nr, t.food_id
              FROM nutrition.such_alias_treffer(p_token_groups) t
            )
          )
        )
      ELSE
        (p_tokens IS NULL OR cardinality(p_tokens) = 0 OR NOT EXISTS (
          SELECT 1 FROM unnest(p_tokens) AS t(tok)
          WHERE NOT (
            nutrition.search_fold(concat_ws(' ', f.bls_code, f.name_de, f.name_en, f.name_th)) LIKE '%' || tok || '%'
            OR EXISTS (
              SELECT 1 FROM nutrition.food_aliases fa
              WHERE fa.food_id = f.id
                AND nutrition.search_fold(fa.alias) LIKE '%' || tok || '%'
            )
          )
        ))
    END)
    AND (
      (COALESCE(p_category_slug, '') = '' AND p_category_id IS NULL)
      OR EXISTS (
        SELECT 1
        FROM nutrition.food_categories selected_category
        JOIN nutrition.food_categories assigned_category ON assigned_category.id = f.category_id
        WHERE (CASE
                 WHEN p_category_id IS NOT NULL THEN selected_category.id = p_category_id
                 ELSE selected_category.slug = p_category_slug
               END)
          AND (
            assigned_category.slug = selected_category.slug
            OR assigned_category.parent_id = selected_category.id
            OR assigned_category.parent_id IN (
              SELECT child.id FROM nutrition.food_categories child WHERE child.parent_id = selected_category.id
            )
            OR assigned_category.parent_id IN (
              SELECT grandchild.id
              FROM nutrition.food_categories child
              JOIN nutrition.food_categories grandchild ON grandchild.parent_id = child.id
              WHERE child.parent_id = selected_category.id
            )
          )
      )
    )
    AND (
      COALESCE(p_tag_code, '') = ''
      OR EXISTS (
        SELECT 1 FROM nutrition.food_tags selected_tag
        WHERE selected_tag.food_id = f.id
          AND selected_tag.tag_code = p_tag_code
      )
    )
    -- ACHTUNG: Diese Bedingungen stehen ABSICHTLICH zweimal — einmal in
    -- `matching_foods` (die angezeigte Seite) und hier in
    -- C-164: Mehrfach-Facetten. `tag_groups` ist ODER innerhalb
    -- einer sichtbaren Gruppe, UND zwischen Gruppen. Ausschluesse
    -- wirken auf die Gesamtmenge, nicht nur auf die aktuelle Seite.
    AND (
      NOT (SELECT has_tag_groups FROM filter_state)
      OR NOT EXISTS (
        SELECT 1
        FROM filter_tag_groups fg
        WHERE NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(fg.gruppe) AS wanted(tag_code)
          JOIN nutrition.food_tags ft ON ft.tag_code = wanted.tag_code
          WHERE ft.food_id = f.id
        )
      )
    )
    AND (
      NOT (SELECT has_exclude_tags FROM filter_state)
      OR NOT EXISTS (
        SELECT 1
        FROM filter_exclude_tags et
        JOIN nutrition.food_tags ft ON ft.tag_code = et.code
        WHERE ft.food_id = f.id
      )
    )
    AND (
      NOT (SELECT has_processing_levels FROM filter_state)
      OR f.processing_level IN (SELECT level FROM filter_processing_levels)
    )
    AND (
      NOT (SELECT has_exclude_processing_levels FROM filter_state)
      OR NOT EXISTS (
        SELECT 1
        FROM filter_exclude_processing_levels ep
        WHERE ep.level = f.processing_level
      )
    )
    -- `all_matching_food_ids` (die Gesamtzahl). `[cmd]` 2026-08-14: beim
    -- ersten Anlauf war nur die erste Stelle gepatcht, worauf jeder
    -- Filter 7.140 zurueckgab — die Trefferliste war gefiltert, die Zahl
    -- darueber nicht. Wer eine Bedingung aendert, aendert BEIDE.
    AND (
      p_preparations IS NULL OR cardinality(p_preparations) = 0
      OR EXISTS (
        SELECT 1 FROM nutrition.preparation_kinds pk
        WHERE pk.code = ANY(p_preparations)
          AND (
            nutrition.search_fold(f.name_de) ~ pk.name_pattern
            OR (pk.bls_codes IS NOT NULL
                AND substr(f.bls_code, 5, 3) = ANY(pk.bls_codes))
          )
      )
    )
    AND (
      p_groups IS NULL OR cardinality(p_groups) = 0
      OR EXISTS (
        SELECT 1
        FROM nutrition.food_categories fcg
        WHERE fcg.id = f.category_id
          AND fcg.food_group_code = ANY(p_groups)
      )
      OR (
        NOT EXISTS (
          SELECT 1
          FROM nutrition.food_categories fcg
          WHERE fcg.id = f.category_id
            AND fcg.food_group_code IS NOT NULL
        )
        AND substr(f.bls_code, 1, 1) = ANY(p_groups)
      )
    )
    AND (
      NOT COALESCE(p_basics_only, false)
      OR NOT EXISTS (
        SELECT 1 FROM nutrition.food_groups fg
        WHERE fg.code = COALESCE(
            (SELECT fcg.food_group_code
             FROM nutrition.food_categories fcg
             WHERE fcg.id = f.category_id),
            substr(f.bls_code, 1, 1)
          )
          AND fg.ist_gericht
      )
    )
),
selected_food AS (
  SELECT
    f.id,
    f.bls_code,
    f.name_de,
    f.name_en,
    f.name_th,
    f.name_display_de,
    f.name_display_en,
    f.name_display_th,
    f.category_id,
    f.sort_weight,
    COALESCE(NULLIF(f.name_display_de, ''), f.name_de, f.name_en, f.bls_code) AS source_label,
    fc.slug AS category_slug,
    fc.name_de AS category_name_de,
    m.enercc,
    m.prot625,
    m.fat,
    m.cho,
    COALESCE(tags.tags, ARRAY[]::text[]) AS tags,
    COALESCE(ps.preference_score, 0) AS preference_score,
    COALESCE(ps.preference_level, 'neutral') AS preference_level,
    COALESCE(ps.preference_match_type, '') AS preference_match_type,
    COALESCE(ps.preference_matches, '[]'::jsonb) AS preference_matches
  FROM nutrition.foods f
  LEFT JOIN nutrition.food_categories fc ON fc.id = f.category_id
  LEFT JOIN preference_scores ps ON ps.food_id = f.id
  LEFT JOIN LATERAL (
    SELECT
      MAX(value) FILTER (WHERE nutrient_code='ENERCC') AS enercc,
      MAX(value) FILTER (WHERE nutrient_code='PROT625') AS prot625,
      MAX(value) FILTER (WHERE nutrient_code='FAT') AS fat,
      MAX(value) FILTER (WHERE nutrient_code='CHO') AS cho
    FROM nutrition.food_nutrients fn
    WHERE fn.food_id = f.id
  ) m ON TRUE
  LEFT JOIN LATERAL (
    SELECT array_agg(ft.tag_code ORDER BY td.sort_order, ft.tag_code) AS tags
    FROM nutrition.food_tags ft
    JOIN nutrition.tag_definitions td ON td.code = ft.tag_code
    WHERE ft.food_id = f.id
  ) tags ON TRUE
  WHERE f.id = COALESCE(p_selected_food_id, (SELECT id FROM matching_foods LIMIT 1))
    AND NOT COALESCE(ps.preference_excluded, false)
  LIMIT 1
),
selected_food_json AS (
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM selected_food) THEN (
      SELECT json_build_object(
        'id', id,
        'bls_code', bls_code,
        'source_label', source_label,
        'source_label_marker', 'bls_source_label_not_final_display_name',
        'name_display_de', name_display_de,
        'name_display_en', name_display_en,
        'name_display_th', name_display_th,
        'name_de', name_de,
        'name_en', name_en,
        'name_th', name_th,
        'category_id', category_id,
        'category_slug', category_slug,
        'category_name_de', category_name_de,
        'sort_weight', sort_weight,
        'enercc', enercc::text,
        'prot625', prot625::text,
        'fat', fat::text,
        'cho', cho::text,
        'tags', tags,
        'preference_score', preference_score,
        'preference_level', preference_level,
        'preference_match_type', preference_match_type,
        'preference_matches', preference_matches
      )
      FROM selected_food
    )
    ELSE NULL::json
  END AS value
),
nutrients_json AS (
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'nutrient_code', fn.nutrient_code,
        'name_de', nd.name_de,
        'name_en', nd.name_en,
        'unit', nd.unit,
        'value', fn.value::text,
        'data_source', COALESCE(fn.data_source, 'BLS')
      )
      ORDER BY
        CASE fn.nutrient_code
          WHEN 'ENERCJ' THEN 1
          WHEN 'ENERCC' THEN 2
          WHEN 'PROT625' THEN 3
          WHEN 'FAT' THEN 4
          WHEN 'CHO' THEN 5
          WHEN 'FIBT' THEN 6
          WHEN 'SUGAR' THEN 7
          WHEN 'NA' THEN 8
          ELSE 50
        END,
        nd.sort_index,
        fn.nutrient_code
    ),
    '[]'::json
  ) AS value
  FROM selected_food sf
  JOIN nutrition.food_nutrients fn ON fn.food_id = sf.id
  JOIN nutrition.nutrient_defs nd ON nd.code = fn.nutrient_code
),
categories_json AS (
  SELECT COALESCE(json_agg(json_build_object(
    'slug', slug,
    'name_de', name_de,
    'level', level,
    'count', food_count
  ) ORDER BY level, sort_order, name_de), '[]'::json) AS value
  FROM (
    SELECT fc.slug, fc.name_de, fc.level, fc.sort_order, COUNT(f.id)::int AS food_count
    FROM nutrition.food_categories fc
    JOIN nutrition.foods f ON f.category_id = fc.id
    WHERE fc.level IN (1,2)
    GROUP BY fc.slug, fc.name_de, fc.level, fc.sort_order
    ORDER BY fc.level, fc.sort_order
    LIMIT 40
  ) category_counts
),
tags_json AS (
  SELECT COALESCE(json_agg(json_build_object(
    'code', code,
    'name_de', name_de,
    'count', food_count
  ) ORDER BY sort_order, name_de), '[]'::json) AS value
  FROM (
    SELECT td.code, td.name_de, td.sort_order, COUNT(ft.food_id)::int AS food_count
    FROM nutrition.tag_definitions td
    JOIN nutrition.food_tags ft ON ft.tag_code = td.code
    GROUP BY td.code, td.name_de, td.sort_order
    ORDER BY td.sort_order
  ) tag_counts
)
SELECT json_build_object(
  'query', COALESCE(p_query, ''),
  'normalized_query', COALESCE(p_normalized_query, ''),
  'category', COALESCE(p_category_slug, ''),
  'category_id', COALESCE(p_category_id::text, ''),
  'tag', COALESCE(p_tag_code, ''),
  -- Die gesetzten Filter zurueckspiegeln, wie category und tag es tun —
  -- die Oberflaeche baut daraus ihre Ankreuzliste und die Adresse.
  'preparations', COALESCE(to_json(p_preparations), 'null'::json),
  'groups', COALESCE(to_json(p_groups), 'null'::json),
  'basics_only', COALESCE(p_basics_only, false),
  'filters', COALESCE(p_filters, '{}'::jsonb),
  'sort', (SELECT sort FROM params),
  'limit', (SELECT lim FROM params),
  'offset', (SELECT off FROM params),
  'total', (SELECT COUNT(*)::int FROM all_matching_food_ids),
  'result_count', (SELECT COUNT(*)::int FROM matching_foods),
  'foods', COALESCE((
    SELECT json_agg(
      json_build_object(
        'id', id,
        'bls_code', bls_code,
        'source_label', source_label,
        'source_label_marker', 'bls_source_label_not_final_display_name',
        'name_display_de', name_display_de,
        'name_display_en', name_display_en,
        'name_display_th', name_display_th,
        'name_de', name_de,
        'name_en', name_en,
        'name_th', name_th,
        'category_id', category_id,
        'category_slug', category_slug,
        'category_name_de', category_name_de,
        'sort_weight', sort_weight,
        'enercc', enercc::text,
        'prot625', prot625::text,
        'fat', fat::text,
        'cho', cho::text,
        'tags', tags,
        'preference_score', preference_score,
        'preference_level', preference_level,
        'preference_match_type', preference_match_type,
        'preference_matches', preference_matches
      )
    )
    FROM matching_foods
  ), '[]'::json),
  'selected_food', (SELECT value FROM selected_food_json),
  'nutrients', (SELECT value FROM nutrients_json),
  'categories', (SELECT value FROM categories_json),
  'tags', (SELECT value FROM tags_json)
)
$$;


ALTER FUNCTION nutrition.food_search(p_query text, p_normalized_query text, p_tokens text[], p_selected_food_id uuid, p_category_slug text, p_category_id uuid, p_tag_code text, p_sort text, p_limit integer, p_offset integer, p_preparations text[], p_groups text[], p_basics_only boolean, p_token_groups jsonb, p_user_id uuid, p_filters jsonb) OWNER TO postgres;

