-- Name: FUNCTION food_search(p_query text, p_normalized_query text, p_tokens text[], p_selected_food_id uuid, p_category_slug text, p_category_id uuid, p_tag_code text, p_sort text, p_limit integer, p_offset integer, p_preparations text[], p_groups text[], p_basics_only boolean, p_token_groups jsonb, p_user_id uuid, p_filters jsonb); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.food_search(p_query text, p_normalized_query text, p_tokens text[], p_selected_food_id uuid, p_category_slug text, p_category_id uuid, p_tag_code text, p_sort text, p_limit integer, p_offset integer, p_preparations text[], p_groups text[], p_basics_only boolean, p_token_groups jsonb, p_user_id uuid, p_filters jsonb) IS 'C-94: Lebensmittelsuche mit optionaler Preference-Anwendung. p_user_id NULL behaelt die ungefilterte Suche; mit Nutzer greifen hard/strong/soft/boost aus food_preferences_read(). C-164: p_filters ergaenzt Mehrfach-Tags, Ausschluesse und processing_level.';


--
-- Name: hydration_day(uuid, date); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.hydration_day(p_user_id uuid, p_entry_date date) RETURNS TABLE(user_id uuid, entry_date date, logged_ml numeric, log_count integer, food_ml numeric, food_ml_missing integer, total_ml numeric, total_complete boolean, target_ml numeric, target_source text, target_available boolean, progress_pct numeric, glass_size_ml integer, glasses_total integer, glasses_target integer, avg_14d_total_ml numeric, avg_14d_days integer, delta_vs_14d_ml numeric, behind_14d_avg_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH profile AS (
  SELECT
    p.id AS user_id,
    p.body_weight_kg,
    p.activity_level,
    CASE p.activity_level
      WHEN 'sedentary' THEN 1.0000::numeric
      WHEN 'light' THEN 1.0833::numeric
      WHEN 'moderate' THEN 1.1667::numeric
      WHEN 'active' THEN 1.2500::numeric
      WHEN 'very_active' THEN 1.3333::numeric
      ELSE NULL::numeric
    END AS activity_factor,
    1.0000::numeric AS climate_factor,
    0::numeric AS training_bonus_ml,
    CASE
      WHEN p.pregnancy_started_on IS NOT NULL
       AND p.pregnancy_started_on <= p_entry_date
       AND (p.pregnancy_ended_on IS NULL OR p.pregnancy_ended_on >= p_entry_date)
        THEN 300::numeric
      ELSE 0::numeric
    END AS pregnancy_bonus_ml,
    CASE
      WHEN p.lactation_started_on IS NOT NULL
       AND p.lactation_started_on <= p_entry_date
       AND (p.lactation_ended_on IS NULL OR p.lactation_ended_on >= p_entry_date)
        THEN 1100::numeric
      ELSE 0::numeric
    END AS lactation_bonus_ml
  FROM public.profiles p
  WHERE p.id = p_user_id
),
today AS (
  SELECT
    p.user_id,
    p_entry_date AS entry_date,
    h.logged_ml,
    h.log_count,
    h.food_ml,
    h.food_ml_missing,
    h.total_ml,
    h.total_complete,
    CASE
      WHEN p.body_weight_kg IS NULL THEN NULL
      WHEN p.activity_factor IS NULL THEN NULL
      ELSE ROUND(
        (p.body_weight_kg * 30 * p.activity_factor * p.climate_factor)
        + p.training_bonus_ml
        + p.pregnancy_bonus_ml
        + p.lactation_bonus_ml
      )
    END AS target_ml,
    CASE
      WHEN p.body_weight_kg IS NULL THEN 'missing_body_weight'
      WHEN p.activity_factor IS NULL THEN 'missing_activity_level'
      ELSE concat(
        'profile_body_weight_activity_formula(',
        'base_30_ml_per_kg',
        '*activity_factor_', trim(to_char(p.activity_factor, 'FM999999990.0000')),
        '*climate_factor_', trim(to_char(p.climate_factor, 'FM999999990.0000')),
        '+training_bonus_', trim(to_char(p.training_bonus_ml, 'FM999999990')), '_ml',
        '+pregnancy_bonus_', trim(to_char(p.pregnancy_bonus_ml, 'FM999999990')), '_ml',
        '+lactation_bonus_', trim(to_char(p.lactation_bonus_ml, 'FM999999990')), '_ml',
        ')'
      )
    END AS target_source
  FROM profile p
  LEFT JOIN nutrition.hydration_summary h
    ON h.user_id = p.user_id
   AND h.entry_date = p_entry_date
),
history_days AS (
  SELECT generate_series(p_entry_date - INTERVAL '14 days', p_entry_date - INTERVAL '1 day', INTERVAL '1 day')::date AS entry_date
),
history AS (
  SELECT
    ROUND(AVG(COALESCE(h.total_ml, 0)), 1) AS avg_14d_total_ml,
    COUNT(*)::INTEGER AS avg_14d_days
  FROM history_days d
  LEFT JOIN nutrition.hydration_summary h
    ON h.user_id = p_user_id
   AND h.entry_date = d.entry_date
)
SELECT
  t.user_id,
  t.entry_date,
  COALESCE(t.logged_ml, 0) AS logged_ml,
  COALESCE(t.log_count, 0)::INTEGER AS log_count,
  t.food_ml,
  COALESCE(t.food_ml_missing, 0)::INTEGER AS food_ml_missing,
  COALESCE(t.total_ml, 0) AS total_ml,
  COALESCE(t.total_complete, true) AS total_complete,
  t.target_ml,
  t.target_source,
  (t.target_ml IS NOT NULL) AS target_available,
  CASE
    WHEN t.target_ml IS NULL OR t.target_ml = 0 THEN NULL
    ELSE ROUND(COALESCE(t.total_ml, 0) / t.target_ml * 100, 1)
  END AS progress_pct,
  250 AS glass_size_ml,
  FLOOR(COALESCE(t.total_ml, 0) / 250)::INTEGER AS glasses_total,
  CASE
    WHEN t.target_ml IS NULL THEN NULL
    ELSE CEIL(t.target_ml / 250)::INTEGER
  END AS glasses_target,
  h.avg_14d_total_ml,
  h.avg_14d_days,
  ROUND(COALESCE(t.total_ml, 0) - h.avg_14d_total_ml, 1) AS delta_vs_14d_ml,
  CASE
    WHEN h.avg_14d_total_ml IS NULL OR h.avg_14d_total_ml = 0 THEN NULL
    WHEN COALESCE(t.total_ml, 0) >= h.avg_14d_total_ml THEN 0
    ELSE ROUND((h.avg_14d_total_ml - COALESCE(t.total_ml, 0)) / h.avg_14d_total_ml * 100, 1)
  END AS behind_14d_avg_pct
FROM today t
CROSS JOIN history h;
$$;


ALTER FUNCTION nutrition.hydration_day(p_user_id uuid, p_entry_date date) OWNER TO postgres;

--
-- Name: FUNCTION hydration_day(p_user_id uuid, p_entry_date date); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.hydration_day(p_user_id uuid, p_entry_date date) IS 'C-55: Lesefunktion fuer Hydration-Seitenleiste. Nutzt hydration_summary als Rohquelle, berechnet Ziel als body_weight_kg * 30 ml * Aktivitaetsfaktor * Klimafaktor plus Trainings-/Schwangerschafts-/Stillzeitbonus, liefert Glaszaehler zu 250 ml und Vergleich gegen die vorherigen 14 Kalendertage. Klima steht bis zur Orts-/Gym-Anbindung auf 1.0, Trainingsbonus bis zu Trainingseinheiten auf 0 ml. Kein Maximum; progress_pct darf ueber 100 liegen.';


--
-- Name: meal_items_owner_guard(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.meal_items_owner_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  owner UUID;
BEGIN
  SELECT m.user_id INTO owner FROM nutrition.meals m WHERE m.id = NEW.meal_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION 'meal_items.meal_id % existiert nicht', NEW.meal_id
      USING ERRCODE = '23503';
  END IF;
  IF NEW.user_id <> owner THEN
    RAISE EXCEPTION
      'meal_items.user_id (%) weicht von meals.user_id (%) ab', NEW.user_id, owner
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION nutrition.meal_items_owner_guard() OWNER TO postgres;

--
-- Name: meal_plan_day_to_diary(uuid, date); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.meal_plan_day_to_diary(p_day_id uuid, p_entry_date date DEFAULT NULL::date) RETURNS TABLE(meal_id uuid, meal_type text, item_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_day nutrition.meal_plan_days%ROWTYPE;
  v_auth uuid := auth.uid();
  v_entry_date date;
  v_slot record;
  v_meal_id uuid;
  v_inserted integer;
  v_scale numeric;
  v_food record;
BEGIN
  SELECT * INTO v_day
  FROM nutrition.meal_plan_days
  WHERE id = p_day_id;

  IF v_day.id IS NULL THEN
    RAISE EXCEPTION 'meal_plan_day_to_diary: Plantag % nicht gefunden', p_day_id
      USING ERRCODE = '02000';
  END IF;
  IF v_auth IS NOT NULL AND v_day.user_id <> v_auth THEN
    RAISE EXCEPTION 'meal_plan_day_to_diary: fremder Plantag'
      USING ERRCODE = '42501';
  END IF;

  v_entry_date := COALESCE(p_entry_date, v_day.plan_date);

  FOR v_slot IN
    SELECT
      e.meal_type,
      COALESCE(min(e.planned_time), CASE e.meal_type
        WHEN 'breakfast' THEN TIME '07:30'
        WHEN 'lunch' THEN TIME '12:30'
        WHEN 'snack' THEN TIME '16:00'
        WHEN 'dinner' THEN TIME '19:30'
        WHEN 'pre_workout' THEN TIME '17:00'
        WHEN 'post_workout' THEN TIME '19:00'
        ELSE TIME '12:00'
      END) AS meal_time
    FROM nutrition.meal_plan_entries e
    WHERE e.day_id = v_day.id
    GROUP BY e.meal_type
    ORDER BY min(COALESCE(e.planned_time, TIME '12:00')), e.meal_type
  LOOP
    v_meal_id := gen_random_uuid();

    INSERT INTO nutrition.meals (
      id, user_id, entry_date, meal_type, meal_time, notes,
      entry_source, source_detail
    )
    VALUES (
      v_meal_id,
      v_day.user_id,
      v_entry_date,
      v_slot.meal_type,
      v_slot.meal_time,
      'Aus Wochenplan uebernommen',
      'seed',
      'meal_plan_day_to_diary'
    );

    v_inserted := 0;

    FOR v_food IN
      SELECT
        e.entry_type AS food_source,
        e.food_id,
        e.custom_food_id,
        e.amount_g,
        e.portion_name,
        e.portion_quantity,
        e.portion_amount_g
      FROM nutrition.meal_plan_entries e
      WHERE e.day_id = v_day.id
        AND e.meal_type = v_slot.meal_type
        AND e.entry_type IN ('bls','custom')
      UNION ALL
      SELECT
        ri.food_source,
        ri.food_id,
        ri.custom_food_id,
        round(ri.amount_g * e.planned_servings / r.servings, 2) AS amount_g,
        ri.portion_name,
        CASE
          WHEN ri.portion_quantity IS NULL THEN NULL
          ELSE round(ri.portion_quantity * e.planned_servings / r.servings, 3)
        END AS portion_quantity,
        ri.portion_amount_g
      FROM nutrition.meal_plan_entries e
      JOIN nutrition.recipes r ON r.id = e.recipe_id
      JOIN nutrition.recipe_ingredients ri ON ri.recipe_id = r.id
      WHERE e.day_id = v_day.id
        AND e.meal_type = v_slot.meal_type
        AND e.entry_type = 'recipe'
      ORDER BY food_source, amount_g DESC
    LOOP
      INSERT INTO nutrition.meal_items (
        meal_id, user_id, food_id, food_source, custom_food_id,
        food_name, amount_g,
        portion_name, portion_quantity, portion_amount_g,
        enercc, prot625, fat, cho, fibt, sugar, fasat, nacl, water_g,
        nutrients, measurement_source, source_detail
      )
      SELECT
        v_meal_id,
        v_day.user_id,
        CASE WHEN v_food.food_source = 'bls' THEN v_food.food_id ELSE NULL END,
        v_food.food_source,
        CASE WHEN v_food.food_source = 'custom' THEN v_food.custom_food_id ELSE NULL END,
        snap.food_name,
        v_food.amount_g,
        v_food.portion_name,
        v_food.portion_quantity,
        v_food.portion_amount_g,
        snap.enercc,
        snap.prot625,
        snap.fat,
        snap.cho,
        snap.fibt,
        snap.sugar,
        snap.fasat,
        snap.nacl,
        snap.water_g,
        snap.nutrients,
        'seed',
        'Aus Wochenplan uebernommen'
      FROM nutrition.food_nutrient_snapshot(
        v_food.food_source,
        v_food.food_id,
        v_food.custom_food_id,
        v_food.amount_g
      ) snap;

      v_inserted := v_inserted + 1;
    END LOOP;

    meal_id := v_meal_id;
    meal_type := v_slot.meal_type;
    item_count := v_inserted;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION nutrition.meal_plan_day_to_diary(p_day_id uuid, p_entry_date date) OWNER TO postgres;

--
-- Name: FUNCTION meal_plan_day_to_diary(p_day_id uuid, p_entry_date date); Type: COMMENT; Schema: nutrition; Owner: postgres
