COMMENT ON FUNCTION nutrition.meal_plan_day_to_diary(p_day_id uuid, p_entry_date date) IS 'C-150: uebernimmt einen geplanten Tag als normale meals/meal_items und friert Naehrwerte erst dort ein.';


--
-- Name: meal_plan_days_owner_guard(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.meal_plan_days_owner_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_owner UUID;
BEGIN
  SELECT w.user_id INTO v_owner
  FROM nutrition.meal_plan_weeks w
  WHERE w.id = NEW.week_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'meal_plan_days.week_id % existiert nicht', NEW.week_id
      USING ERRCODE = '23503';
  END IF;
  IF NEW.user_id <> v_owner THEN
    RAISE EXCEPTION 'meal_plan_days.user_id (%) weicht von meal_plan_weeks.user_id (%) ab',
      NEW.user_id, v_owner USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION nutrition.meal_plan_days_owner_guard() OWNER TO postgres;

--
-- Name: meal_plan_entries_owner_guard(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.meal_plan_entries_owner_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_owner UUID;
  v_recipe_owner UUID;
  v_custom_owner UUID;
BEGIN
  SELECT d.user_id INTO v_owner
  FROM nutrition.meal_plan_days d
  WHERE d.id = NEW.day_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'meal_plan_entries.day_id % existiert nicht', NEW.day_id
      USING ERRCODE = '23503';
  END IF;
  IF NEW.user_id <> v_owner THEN
    RAISE EXCEPTION 'meal_plan_entries.user_id (%) weicht von meal_plan_days.user_id (%) ab',
      NEW.user_id, v_owner USING ERRCODE = '23514';
  END IF;

  IF NEW.recipe_id IS NOT NULL THEN
    SELECT r.user_id INTO v_recipe_owner
    FROM nutrition.recipes r
    WHERE r.id = NEW.recipe_id;
    IF v_recipe_owner <> NEW.user_id THEN
      RAISE EXCEPTION 'meal_plan_entries.recipe_id gehoert nicht der Nutzerin'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.custom_food_id IS NOT NULL THEN
    SELECT fc.user_id INTO v_custom_owner
    FROM nutrition.foods_custom fc
    WHERE fc.id = NEW.custom_food_id;
    IF v_custom_owner <> NEW.user_id THEN
      RAISE EXCEPTION 'meal_plan_entries.custom_food_id gehoert nicht der Nutzerin'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION nutrition.meal_plan_entries_owner_guard() OWNER TO postgres;

--
-- Name: meal_plan_weeks_owner_guard(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.meal_plan_weeks_owner_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_owner UUID;
BEGIN
  SELECT p.user_id INTO v_owner
  FROM nutrition.meal_plans p
  WHERE p.id = NEW.plan_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'meal_plan_weeks.plan_id % existiert nicht', NEW.plan_id
      USING ERRCODE = '23503';
  END IF;
  IF NEW.user_id <> v_owner THEN
    RAISE EXCEPTION 'meal_plan_weeks.user_id (%) weicht von meal_plans.user_id (%) ab',
      NEW.user_id, v_owner USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION nutrition.meal_plan_weeks_owner_guard() OWNER TO postgres;

--
-- Name: micronutrient_below_threshold(uuid, date, numeric); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.micronutrient_below_threshold(p_user_id uuid, p_entry_date date, p_threshold_pct numeric DEFAULT 75) RETURNS TABLE(threshold_pct numeric, total_assessed integer, below_count integer, items jsonb)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH assessed AS (
  SELECT
    a.nutrient_code,
    a.nutrient_name_de,
    a.nutrient_unit,
    a.actual_value,
    a.reference_value_min,
    a.reference_pct,
    a.reference_kind,
    ROW_NUMBER() OVER (
      PARTITION BY a.nutrient_code
      ORDER BY CASE a.reference_kind
        WHEN 'PRI' THEN 1
        WHEN 'AI' THEN 2
        WHEN 'FORMULA' THEN 3
        WHEN 'RI' THEN 4
        ELSE 9
      END
    ) AS rn
  FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date) a
  WHERE a.reference_direction = 'target'
    AND a.reference_status = 'complete'
    AND a.reference_pct IS NOT NULL
),
selected AS (
  SELECT *
  FROM assessed
  WHERE rn = 1
),
below AS (
  SELECT *
  FROM selected
  WHERE reference_pct < p_threshold_pct
)
SELECT
  p_threshold_pct AS threshold_pct,
  (SELECT COUNT(*)::INTEGER FROM selected) AS total_assessed,
  (SELECT COUNT(*)::INTEGER FROM below) AS below_count,
  COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'nutrient_code', nutrient_code,
      'name_de', nutrient_name_de,
      'actual_value', actual_value,
      'reference_value', reference_value_min,
      'unit', nutrient_unit,
      'reference_pct', reference_pct,
      'reference_kind', reference_kind
    ) ORDER BY reference_pct ASC, nutrient_name_de)
    FROM below
  ), '[]'::jsonb) AS items;
$$;


ALTER FUNCTION nutrition.micronutrient_below_threshold(p_user_id uuid, p_entry_date date, p_threshold_pct numeric) OWNER TO postgres;

--
-- Name: FUNCTION micronutrient_below_threshold(p_user_id uuid, p_entry_date date, p_threshold_pct numeric); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.micronutrient_below_threshold(p_user_id uuid, p_entry_date date, p_threshold_pct numeric) IS 'Sortierliste der vollstaendig bewerteten target-Referenzen unter einer Prozent-Schwelle. Keine Warnung und keine Wortbewertung.';


--
-- Name: micronutrient_snapshot(uuid, date); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.micronutrient_snapshot(p_user_id uuid, p_entry_date date) RETURNS TABLE(display_order integer, nutrient_code text, label_de text, label_en text, nutrient_name_de text, unit text, actual_value numeric, reference_value numeric, reference_pct numeric, reference_kind text, reference_status text, value_source text, source_note text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH goals_target AS (
  SELECT
    COALESCE(z.alpha_linolenic_acid_g, b.alpha_linolenic_acid_g) AS alpha_linolenic_acid_g
  FROM (SELECT 1) seed
  LEFT JOIN LATERAL goals.zielwerte_am(p_user_id, p_entry_date) z ON true
  LEFT JOIN LATERAL goals.berechne_zielwerte(p_user_id, p_entry_date) b ON true
),
assessment AS (
  SELECT
    a.*,
    ROW_NUMBER() OVER (
      PARTITION BY a.nutrient_code
      ORDER BY CASE a.reference_kind
        WHEN 'PRI' THEN 1
        WHEN 'AI' THEN 2
        WHEN 'FORMULA' THEN 3
        WHEN 'RI' THEN 4
        ELSE 9
      END
    ) AS rn
  FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date) a
  WHERE a.reference_direction = 'target'
)
SELECT
  i.display_order,
  i.nutrient_code,
  i.label_de,
  i.label_en,
  nd.name_de AS nutrient_name_de,
  nd.unit,
  a.actual_value,
  CASE
    WHEN i.value_source = 'goals_alpha_linolenic_acid' THEN g.alpha_linolenic_acid_g
    ELSE a.reference_value_min
  END AS reference_value,
  CASE
    WHEN i.value_source = 'goals_alpha_linolenic_acid' THEN
      CASE
        WHEN a.actual_value IS NULL OR a.missing_count > 0 OR g.alpha_linolenic_acid_g IS NULL OR g.alpha_linolenic_acid_g = 0 THEN NULL
        ELSE ROUND(a.actual_value / g.alpha_linolenic_acid_g * 100, 1)
      END
    ELSE a.reference_pct
  END AS reference_pct,
  CASE
    WHEN i.value_source = 'goals_alpha_linolenic_acid' THEN 'GOAL'
    ELSE a.reference_kind
  END AS reference_kind,
  CASE
    WHEN i.value_source = 'goals_alpha_linolenic_acid' THEN
      CASE
        WHEN a.missing_count > 0 THEN 'incomplete'
        WHEN a.actual_value IS NULL THEN 'no_value'
        WHEN g.alpha_linolenic_acid_g IS NULL THEN 'missing_goal'
        ELSE 'complete'
      END
    ELSE a.reference_status
  END AS reference_status,
  i.value_source,
  i.source_note
FROM nutrition.micronutrient_overview_items i
JOIN nutrition.nutrient_defs nd ON nd.code = i.nutrient_code
LEFT JOIN assessment a ON a.nutrient_code = i.nutrient_code AND a.rn = 1
CROSS JOIN goals_target g
ORDER BY i.display_order;
$$;


ALTER FUNCTION nutrition.micronutrient_snapshot(p_user_id uuid, p_entry_date date) OWNER TO postgres;

--
-- Name: FUNCTION micronutrient_snapshot(p_user_id uuid, p_entry_date date); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.micronutrient_snapshot(p_user_id uuid, p_entry_date date) IS 'Acht kuratierte Naehrstoffe fuer das Micronutrient-Snapshot-Netzdiagramm. Omega-3 wird als ALA gegen Goals-Zielwert gerechnet; Gesamt-Omega-3, EPA und DHA werden nicht ungestuetzt addiert.';


--
-- Name: nutrient_summary_window(uuid, date, integer); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.nutrient_summary_window(p_user_id uuid, p_end_date date, p_days integer DEFAULT 30) RETURNS TABLE(user_id uuid, window_start date, window_end date, window_days integer, nutrient_code text, nutrient_name_de text, nutrient_unit text, group_de text, display_tier integer, sort_index integer, logged_day_count integer, days_with_value integer, complete_day_count integer, item_count integer, value_count integer, missing_count integer, total_value numeric, avg_per_calendar_day numeric, avg_per_logged_day numeric, avg_per_value_day numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
WITH params AS (
  SELECT
    p_user_id AS user_id,
    (p_end_date - (GREATEST(p_days, 1) - 1))::DATE AS window_start,
    p_end_date AS window_end,
    GREATEST(p_days, 1)::INTEGER AS window_days
),
days AS (
  SELECT gs::DATE AS entry_date
  FROM params p
  CROSS JOIN generate_series(p.window_start, p.window_end, INTERVAL '1 day') AS gs
),
day_base AS (
  SELECT
    d.entry_date,
    COUNT(DISTINCT m.id)::INTEGER AS meal_count,
    COUNT(mi.id)::INTEGER AS item_count,
    (COUNT(DISTINCT m.id) > 0) AS day_logged
  FROM params p
  CROSS JOIN days d
  LEFT JOIN nutrition.meals m
    ON m.user_id = p.user_id
   AND m.entry_date = d.entry_date
  LEFT JOIN nutrition.meal_items mi ON mi.meal_id = m.id
  GROUP BY d.entry_date
),
item_base AS (
  SELECT
    m.entry_date,
    mi.id AS item_id,
    mi.enercc,
    mi.prot625,
    mi.fat,
    mi.cho,
    mi.fibt,
    mi.sugar,
    mi.fasat,
    mi.nacl,
    mi.water_g,
    mi.nutrients
  FROM params p
  JOIN nutrition.meals m
    ON m.user_id = p.user_id
   AND m.entry_date BETWEEN p.window_start AND p.window_end
  JOIN nutrition.meal_items mi ON mi.meal_id = m.id
),
item_values AS (
  SELECT
    ib.entry_date,
    ib.item_id,
    v.nutrient_code,
    v.value
  FROM item_base ib
  CROSS JOIN LATERAL (VALUES
    ('ENERCC', ib.enercc),
    ('PROT625', ib.prot625),
    ('FAT', ib.fat),
    ('CHO', ib.cho),
    ('FIBT', ib.fibt),
    ('SUGAR', ib.sugar),
    ('FASAT', ib.fasat),
    ('NACL', ib.nacl),
    ('WATER', ib.water_g)
  ) AS v(nutrient_code, value)
  WHERE v.value IS NOT NULL

  UNION ALL

  SELECT
    ib.entry_date,
    ib.item_id,
    kv.key AS nutrient_code,
    kv.value::NUMERIC AS value
  FROM item_base ib
  CROSS JOIN LATERAL jsonb_each_text(ib.nutrients) AS kv(key, value)
  WHERE kv.key NOT IN ('ENERCC','PROT625','FAT','CHO','FIBT','SUGAR','FASAT','NACL','WATER')
    AND kv.value ~ '^-?[0-9]+([.][0-9]+)?$'
),
agg AS (
  SELECT
    entry_date,
    nutrient_code,
    COUNT(*)::INTEGER AS value_count,
    SUM(value) AS total_value
  FROM item_values
  GROUP BY entry_date, nutrient_code
),
daily_values AS (
  SELECT
    db.entry_date,
    nd.code AS nutrient_code,
    nd.name_de AS nutrient_name_de,
    nd.unit AS nutrient_unit,
    nd.group_de,
    nd.display_tier,
    nd.sort_index,
    db.item_count,
    COALESCE(a.value_count, 0)::INTEGER AS value_count,
    (db.item_count - COALESCE(a.value_count, 0))::INTEGER AS missing_count,
    a.total_value,
    (db.item_count > 0 AND db.item_count = COALESCE(a.value_count, 0)) AS value_complete,
    db.day_logged
  FROM day_base db
  CROSS JOIN nutrition.nutrient_defs nd
  LEFT JOIN agg a
    ON a.entry_date = db.entry_date
   AND a.nutrient_code = nd.code
)
SELECT
  p.user_id,
  p.window_start,
  p.window_end,
  p.window_days,
  nd.code AS nutrient_code,
  nd.name_de AS nutrient_name_de,
  nd.unit AS nutrient_unit,
  nd.group_de,
  nd.display_tier,
  nd.sort_index,
  COUNT(*) FILTER (WHERE dv.day_logged)::INTEGER AS logged_day_count,
  COUNT(*) FILTER (WHERE dv.total_value IS NOT NULL)::INTEGER AS days_with_value,
  COUNT(*) FILTER (WHERE dv.value_complete)::INTEGER AS complete_day_count,
  COALESCE(SUM(dv.item_count), 0)::INTEGER AS item_count,
  COALESCE(SUM(dv.value_count), 0)::INTEGER AS value_count,
  COALESCE(SUM(dv.missing_count), 0)::INTEGER AS missing_count,
  SUM(dv.total_value) AS total_value,
  CASE
    WHEN SUM(dv.total_value) IS NULL THEN NULL
    ELSE ROUND(SUM(dv.total_value) / p.window_days, 3)
  END AS avg_per_calendar_day,
  CASE
    WHEN COUNT(*) FILTER (WHERE dv.day_logged) = 0
      OR SUM(dv.total_value) IS NULL THEN NULL
    ELSE ROUND(
      SUM(dv.total_value)
      / (COUNT(*) FILTER (WHERE dv.day_logged))::NUMERIC,
      3
    )
  END AS avg_per_logged_day,
  CASE
    WHEN COUNT(*) FILTER (WHERE dv.total_value IS NOT NULL) = 0
      OR SUM(dv.total_value) IS NULL THEN NULL
    ELSE ROUND(
      SUM(dv.total_value)
      / (COUNT(*) FILTER (WHERE dv.total_value IS NOT NULL))::NUMERIC,
      3
    )
  END AS avg_per_value_day
FROM params p
CROSS JOIN nutrition.nutrient_defs nd
JOIN daily_values dv ON dv.nutrient_code = nd.code
GROUP BY
  p.user_id,
  p.window_start,
  p.window_end,
  p.window_days,
  nd.code,
  nd.name_de,
  nd.unit,
  nd.group_de,
  nd.display_tier,
  nd.sort_index
ORDER BY nd.display_tier, nd.sort_index, nd.code;
$_$;


ALTER FUNCTION nutrition.nutrient_summary_window(p_user_id uuid, p_end_date date, p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION nutrient_summary_window(p_user_id uuid, p_end_date date, p_days integer); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.nutrient_summary_window(p_user_id uuid, p_end_date date, p_days integer) IS 'C-157: Lange Naehrstoffbilanz fuer Zeitfenster 1/7/14/30/45/60/90 Tage. Gibt Summe, Kalendertagsschnitt, Schnitt je protokolliertem Tag und Vollstaendigkeit aus; keine Bewertung.';


--
-- Name: nutrient_tree_value_anomalies(uuid, date); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.nutrient_tree_value_anomalies(p_user_id uuid, p_entry_date date) RETURNS TABLE(child_code text, parent_code text, child_value numeric, parent_value numeric, child_factor numeric, child_contribution numeric, unit text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH factors(child_code, parent_code, factor) AS (
  VALUES
    ('NT','PROT625',6.25::NUMERIC),
    ('CARTB','VITA',(1.0/6.0)::NUMERIC),
    ('CAROTPAXB','VITA',(1.0/12.0)::NUMERIC),
    ('FOLAC','FOL',1.7::NUMERIC),
    ('TRP','NIAEQ',(1000.0/60.0)::NUMERIC)
),
edges AS (
  SELECT nd.code AS child_code, nd.parent_code, COALESCE(f.factor, 1::NUMERIC) AS factor
  FROM nutrition.nutrient_defs nd
  LEFT JOIN factors f
    ON f.child_code = nd.code
   AND f.parent_code = nd.parent_code
  WHERE nd.parent_code IS NOT NULL
),
v AS (
  SELECT nutrient_code, total_value, nutrient_unit
  FROM nutrition.daily_nutrient_summary_long
  WHERE user_id = p_user_id
    AND entry_date = p_entry_date
)
SELECT
  e.child_code,
  e.parent_code,
  cv.total_value AS child_value,
  pv.total_value AS parent_value,
  e.factor AS child_factor,
  cv.total_value * e.factor AS child_contribution,
  cv.nutrient_unit AS unit
FROM edges e
JOIN v cv ON cv.nutrient_code = e.child_code
JOIN v pv ON pv.nutrient_code = e.parent_code
WHERE cv.total_value IS NOT NULL
  AND pv.total_value IS NOT NULL
  AND cv.nutrient_unit = pv.nutrient_unit
  AND (cv.total_value * e.factor) > (pv.total_value + 0.0001)
ORDER BY e.parent_code, e.child_code;
$$;


ALTER FUNCTION nutrition.nutrient_tree_value_anomalies(p_user_id uuid, p_entry_date date) OWNER TO postgres;

--
-- Name: FUNCTION nutrient_tree_value_anomalies(p_user_id uuid, p_entry_date date); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.nutrient_tree_value_anomalies(p_user_id uuid, p_entry_date date) IS 'C-161: Prueft echte Baumkanten gegen Tageswerte. Formelanteile wie 1/6 Beta-Carotin -> Vitamin A werden als Beitrag verglichen, nicht als rohe Kindmenge.';


--
-- Name: preference_search_preview(text, text, text[], text[], text[], text[], text[], text[], text, integer, integer, uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.preference_search_preview(p_query text, p_normalized_query text, p_tokens text[], p_excluded_category_slugs text[], p_liked_category_slugs text[], p_disliked_category_slugs text[], p_liked_tags text[], p_disliked_tags text[], p_sort text, p_limit integer, p_offset integer, p_liked_food_ids uuid[] DEFAULT ARRAY[]::uuid[], p_disliked_food_ids uuid[] DEFAULT ARRAY[]::uuid[], p_excluded_food_ids uuid[] DEFAULT ARRAY[]::uuid[]) RETURNS json
    LANGUAGE sql STABLE
    AS $$
WITH RECURSIVE excluded_categories AS (
  SELECT id, slug FROM nutrition.food_categories
  WHERE slug = ANY(COALESCE(p_excluded_category_slugs, ARRAY[]::text[]))
  UNION ALL
  SELECT child.id, child.slug
  FROM nutrition.food_categories child
  JOIN excluded_categories parent ON child.parent_id = parent.id
),
liked_categories AS (
  SELECT id, slug FROM nutrition.food_categories
  WHERE slug = ANY(COALESCE(p_liked_category_slugs, ARRAY[]::text[]))
  UNION ALL
  SELECT child.id, child.slug FROM nutrition.food_categories child JOIN liked_categories parent ON child.parent_id = parent.id
),
disliked_categories AS (
  SELECT id, slug FROM nutrition.food_categories
  WHERE slug = ANY(COALESCE(p_disliked_category_slugs, ARRAY[]::text[]))
  UNION ALL
  SELECT child.id, child.slug FROM nutrition.food_categories child JOIN disliked_categories parent ON child.parent_id = parent.id
),
base AS (
  SELECT
    f.id,
    f.bls_code,
    COALESCE(NULLIF(f.name_display_de, ''), f.name_de, f.name_en, f.bls_code) AS source_label,
    f.sort_weight,
    fc.slug AS category_slug,
    fc.name_de AS category_name_de,
    m.enercc,
    m.prot625,
    m.fat,
    m.cho,
    COALESCE(tags.tags, ARRAY[]::text[]) AS tags,
    1 AS text_rank,
    CASE WHEN f.id = ANY(COALESCE(p_liked_food_ids, ARRAY[]::uuid[])) THEN 80 ELSE 0 END
      + CASE WHEN f.id = ANY(COALESCE(p_disliked_food_ids, ARRAY[]::uuid[])) THEN -80 ELSE 0 END
      + CASE WHEN lc.id IS NOT NULL THEN 50 ELSE 0 END
      + CASE WHEN dc.id IS NOT NULL THEN -50 ELSE 0 END
      + CASE WHEN COALESCE(tags.tags, ARRAY[]::text[]) && COALESCE(p_liked_tags, ARRAY[]::text[]) THEN 30 ELSE 0 END
      + CASE WHEN COALESCE(tags.tags, ARRAY[]::text[]) && COALESCE(p_disliked_tags, ARRAY[]::text[]) THEN -30 ELSE 0 END AS preference_score,
    ARRAY_REMOVE(ARRAY[
      CASE WHEN f.id = ANY(COALESCE(p_liked_food_ids, ARRAY[]::uuid[])) THEN 'liked_food' END,
      CASE WHEN f.id = ANY(COALESCE(p_disliked_food_ids, ARRAY[]::uuid[])) THEN 'disliked_food' END,
      CASE WHEN lc.id IS NOT NULL THEN 'liked_category' END,
      CASE WHEN dc.id IS NOT NULL THEN 'disliked_category' END,
      CASE WHEN COALESCE(tags.tags, ARRAY[]::text[]) && COALESCE(p_liked_tags, ARRAY[]::text[]) THEN 'liked_tag' END,
      CASE WHEN COALESCE(tags.tags, ARRAY[]::text[]) && COALESCE(p_disliked_tags, ARRAY[]::text[]) THEN 'disliked_tag' END
    ], NULL) AS preference_notes,
    ARRAY_REMOVE(ARRAY[
      CASE WHEN f.id = ANY(COALESCE(p_liked_food_ids, ARRAY[]::uuid[])) THEN 'boosted because this food is marked as favorite' END,
      CASE WHEN f.id = ANY(COALESCE(p_disliked_food_ids, ARRAY[]::uuid[])) THEN 'suppressed because this food is marked as disliked' END,
      CASE WHEN lc.id IS NOT NULL THEN 'boosted because selected liked category includes this food category' END,
      CASE WHEN dc.id IS NOT NULL THEN 'suppressed because selected disliked category includes this food category' END,
      CASE WHEN COALESCE(tags.tags, ARRAY[]::text[]) && COALESCE(p_liked_tags, ARRAY[]::text[]) THEN 'boosted because food has a selected liked tag' END,
      CASE WHEN COALESCE(tags.tags, ARRAY[]::text[]) && COALESCE(p_disliked_tags, ARRAY[]::text[]) THEN 'suppressed because food has a selected disliked tag' END
    ], NULL) AS preference_reasons
  FROM nutrition.foods f
  LEFT JOIN nutrition.food_categories fc ON fc.id = f.category_id
  LEFT JOIN excluded_categories ec ON ec.id = f.category_id
  LEFT JOIN liked_categories lc ON lc.id = f.category_id
  LEFT JOIN disliked_categories dc ON dc.id = f.category_id
  LEFT JOIN LATERAL (
    SELECT
      MAX(value) FILTER (WHERE nutrient_code='ENERCC') AS enercc,
      MAX(value) FILTER (WHERE nutrient_code='PROT625') AS prot625,
      MAX(value) FILTER (WHERE nutrient_code='FAT') AS fat,
      MAX(value) FILTER (WHERE nutrient_code='CHO') AS cho
    FROM nutrition.food_nutrients fn WHERE fn.food_id = f.id
  ) m ON TRUE
  LEFT JOIN LATERAL (
    SELECT array_agg(ft.tag_code ORDER BY ft.tag_code) AS tags
    FROM nutrition.food_tags ft WHERE ft.food_id = f.id
  ) tags ON TRUE
  WHERE
    (p_tokens IS NULL OR cardinality(p_tokens) = 0 OR NOT EXISTS (
      SELECT 1 FROM unnest(p_tokens) AS t(tok)
      WHERE NOT (
        nutrition.search_fold(concat_ws(' ', f.bls_code, f.name_de, f.name_en, f.name_th)) LIKE '%' || tok || '%'
        OR EXISTS (
          SELECT 1 FROM nutrition.food_aliases fa
          WHERE fa.food_id = f.id
            AND nutrition.search_fold(fa.alias) LIKE '%' || tok || '%'
        )
      )
    ))
    AND ec.id IS NULL
    AND NOT (f.id = ANY(COALESCE(p_excluded_food_ids, ARRAY[]::uuid[])))
),
excluded_count AS (
  SELECT COUNT(*) AS count
  FROM nutrition.foods f
  LEFT JOIN excluded_categories ec ON ec.id = f.category_id
  WHERE
    (p_tokens IS NULL OR cardinality(p_tokens) = 0 OR NOT EXISTS (
      SELECT 1 FROM unnest(p_tokens) AS t(tok)
      WHERE NOT (
        nutrition.search_fold(concat_ws(' ', f.bls_code, f.name_de, f.name_en, f.name_th)) LIKE '%' || tok || '%'
        OR EXISTS (
          SELECT 1 FROM nutrition.food_aliases fa
          WHERE fa.food_id = f.id
            AND nutrition.search_fold(fa.alias) LIKE '%' || tok || '%'
        )
      )
    ))
    AND (ec.id IS NOT NULL OR f.id = ANY(COALESCE(p_excluded_food_ids, ARRAY[]::uuid[])))
),
ranked AS (
  SELECT * FROM base
  ORDER BY
    CASE WHEN COALESCE(p_sort, 'relevance') = 'protein_desc' THEN COALESCE(prot625, 0) END DESC,
    CASE WHEN COALESCE(p_sort, 'relevance') = 'kcal_asc' THEN COALESCE(enercc, 999999) END ASC,
    CASE WHEN COALESCE(p_sort, 'relevance') = 'relevance' THEN text_rank END DESC,
    CASE WHEN COALESCE(p_sort, 'relevance') IN ('relevance', 'protein_desc', 'kcal_asc') THEN preference_score END DESC,
    CASE WHEN COALESCE(p_sort, 'relevance') = 'relevance' THEN sort_weight END DESC NULLS LAST,
    source_label ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0)
)
SELECT json_build_object(
  'query', COALESCE(p_query, ''),
  'normalized_query', COALESCE(p_normalized_query, ''),
  'total', (SELECT COUNT(*) FROM base),
  'excluded_count', (SELECT count FROM excluded_count),
  'boosted_count', (SELECT COUNT(*) FROM base WHERE preference_score > 0),
  'suppressed_count', (SELECT COUNT(*) FROM base WHERE preference_score < 0),
  'foods', COALESCE((SELECT json_agg(json_build_object(
    'id', id,
    'bls_code', bls_code,
    'source_label', source_label,
    'category_slug', category_slug,
    'category_name_de', category_name_de,
    'enercc', enercc::text,
    'prot625', prot625::text,
    'fat', fat::text,
    'cho', cho::text,
    'tags', tags,
    'preference_score', preference_score,
    'preference_notes', preference_notes,
    'preference_reasons', preference_reasons
  )) FROM ranked), '[]'::json)
)
$$;


