--
-- Name: recipe_ingredients_owner_guard(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.recipe_ingredients_owner_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_owner UUID;
  v_custom_owner UUID;
BEGIN
  SELECT r.user_id INTO v_owner
  FROM nutrition.recipes r
  WHERE r.id = NEW.recipe_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'recipe_ingredients.recipe_id % existiert nicht', NEW.recipe_id
      USING ERRCODE = '23503';
  END IF;
  IF NEW.user_id <> v_owner THEN
    RAISE EXCEPTION 'recipe_ingredients.user_id (%) weicht von recipes.user_id (%) ab',
      NEW.user_id, v_owner USING ERRCODE = '23514';
  END IF;

  IF NEW.custom_food_id IS NOT NULL THEN
    SELECT fc.user_id INTO v_custom_owner
    FROM nutrition.foods_custom fc
    WHERE fc.id = NEW.custom_food_id;
    IF v_custom_owner <> NEW.user_id THEN
      RAISE EXCEPTION 'recipe_ingredients.custom_food_id gehoert nicht der Nutzerin'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION nutrition.recipe_ingredients_owner_guard() OWNER TO postgres;

--
-- Name: recipe_nutrition(uuid, numeric); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.recipe_nutrition(p_recipe_id uuid, p_servings numeric DEFAULT NULL::numeric) RETURNS TABLE(recipe_id uuid, servings_used numeric, ingredient_count integer, amount_g numeric, enercc numeric, prot625 numeric, fat numeric, cho numeric, fibt numeric, sugar numeric, fasat numeric, nacl numeric, water_g numeric, nutrients jsonb)
    LANGUAGE sql STABLE
    AS $$
WITH recipe AS (
  SELECT r.id, r.servings, COALESCE(p_servings, r.servings) AS servings_used
  FROM nutrition.recipes r
  WHERE r.id = p_recipe_id
),
scaled AS (
  SELECT
    ri.id,
    ri.recipe_id,
    (ri.amount_g * recipe.servings_used / recipe.servings) AS amount_g,
    snap.enercc,
    snap.prot625,
    snap.fat,
    snap.cho,
    snap.fibt,
    snap.sugar,
    snap.fasat,
    snap.nacl,
    snap.water_g,
    snap.nutrients
  FROM recipe
  JOIN nutrition.recipe_ingredients ri ON ri.recipe_id = recipe.id
  CROSS JOIN LATERAL nutrition.food_nutrient_snapshot(
    ri.food_source,
    ri.food_id,
    ri.custom_food_id,
    ri.amount_g * recipe.servings_used / recipe.servings
  ) snap
)
SELECT
  recipe.id AS recipe_id,
  recipe.servings_used,
  count(scaled.id)::integer AS ingredient_count,
  sum(scaled.amount_g) AS amount_g,
  sum(scaled.enercc) AS enercc,
  sum(scaled.prot625) AS prot625,
  sum(scaled.fat) AS fat,
  sum(scaled.cho) AS cho,
  sum(scaled.fibt) AS fibt,
  sum(scaled.sugar) AS sugar,
  sum(scaled.fasat) AS fasat,
  sum(scaled.nacl) AS nacl,
  sum(scaled.water_g) AS water_g,
  COALESCE(
    (
      SELECT jsonb_object_agg(code, round(total, 5))
      FROM (
        SELECT n.key AS code, sum((n.value #>> '{}')::numeric) AS total
        FROM scaled s
        CROSS JOIN LATERAL jsonb_each(s.nutrients) AS n(key, value)
        GROUP BY n.key
      ) totals
    ),
    '{}'::jsonb
  ) AS nutrients
FROM recipe
LEFT JOIN scaled ON scaled.recipe_id = recipe.id
GROUP BY recipe.id, recipe.servings_used;
$$;


ALTER FUNCTION nutrition.recipe_nutrition(p_recipe_id uuid, p_servings numeric) OWNER TO postgres;

--
-- Name: refresh_food_preference_search_targets(uuid); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.refresh_food_preference_search_targets(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;

  DELETE FROM nutrition.food_preference_search_targets
  WHERE user_id = p_user_id;

  INSERT INTO nutrition.food_preference_search_targets (
    user_id, food_id, constraint_level, match_type, score, specificity, source, updated_at
  )
  WITH RECURSIVE user_preference AS (
    SELECT
      fp.user_id,
      COALESCE(fp.diet_type, 'omnivore') AS diet_type,
      COALESCE(fp.allergies, '{}'::text[]) AS allergies,
      COALESCE(fp.intolerances, '{}'::text[]) AS intolerances,
      COALESCE(fp.general_exclusions, '{}'::text[]) AS general_exclusions
    FROM nutrition.food_preferences fp
    WHERE fp.user_id = p_user_id
  ),
  preference_items AS MATERIALIZED (
    SELECT
      fpi.id,
      fpi.user_id,
      fpi.preference,
      fpi.strength,
      fpi.target_type,
      fpi.food_id,
      fpi.category_id,
      fpi.tag_code,
      fpi.cuisine_code,
      fpi.exclusion_preset_code,
      CASE
        WHEN fpi.preference = 'hard_exclude'
          OR fpi.strength = 'hard_exclude' THEN 'hard'
        WHEN fpi.strength = 'strong_avoid' THEN 'strong'
        WHEN fpi.preference = 'disliked'
          OR fpi.strength = 'soft_dislike' THEN 'soft'
        WHEN fpi.preference = 'liked'
          OR fpi.strength IN ('like', 'boost') THEN 'boost'
        ELSE 'neutral'
      END AS constraint_level
    FROM nutrition.food_preference_items fpi
    WHERE fpi.user_id = p_user_id
  ),
  preference_category_tree AS (
    SELECT pi.id AS item_id, pi.category_id
    FROM preference_items pi
    WHERE pi.target_type = 'category'
      AND pi.category_id IS NOT NULL
    UNION ALL
    SELECT pct.item_id, fc.id
    FROM preference_category_tree pct
    JOIN nutrition.food_categories fc ON fc.parent_id = pct.category_id
  ),
  preference_category_ancestors AS (
    SELECT pi.id AS item_id, pi.category_id
    FROM preference_items pi
    WHERE pi.target_type = 'category'
      AND pi.category_id IS NOT NULL
    UNION ALL
    SELECT pca.item_id, fc.parent_id
    FROM preference_category_ancestors pca
    JOIN nutrition.food_categories fc ON fc.id = pca.category_id
    WHERE fc.parent_id IS NOT NULL
  ),
  allergy_tag_map AS (
    SELECT * FROM (VALUES
      ('gluten_wheat', 'contains_gluten'),
      ('gluten', 'contains_gluten'),
      ('tree_nuts', 'contains_nuts'),
      ('peanuts', 'contains_nuts'),
      ('nuts', 'contains_nuts'),
      ('lactose', 'contains_lactose'),
      ('milk_protein', 'contains_lactose')
    ) AS m(source_code, tag_code)
  ),
  preference_targets AS MATERIALIZED (
    SELECT
      pi.food_id,
      pi.constraint_level,
      'food'::text AS match_type,
      CASE
        WHEN pi.constraint_level = 'boost' THEN 100
        WHEN pi.constraint_level = 'soft' THEN -100
        WHEN pi.constraint_level = 'strong' THEN -75
        ELSE 0
      END AS score,
      30 AS specificity,
      'preference_item'::text AS source
    FROM preference_items pi
    WHERE pi.target_type = 'food'
      AND pi.food_id IS NOT NULL
      AND pi.constraint_level <> 'neutral'

    UNION ALL

    SELECT
      f.id,
      pi.constraint_level,
      'category'::text,
      CASE
        WHEN pi.constraint_level = 'boost' THEN 50
        WHEN pi.constraint_level = 'soft' THEN -50
        WHEN pi.constraint_level = 'strong' THEN -40
        ELSE 0
      END,
      20,
      'preference_item'::text
    FROM preference_items pi
    JOIN (
      SELECT item_id, category_id FROM preference_category_tree
      UNION
      SELECT item_id, category_id FROM preference_category_ancestors
    ) pct ON pct.item_id = pi.id
    JOIN nutrition.foods f ON f.category_id = pct.category_id
    WHERE pi.constraint_level <> 'neutral'

    UNION ALL

    SELECT
      ft.food_id,
      pi.constraint_level,
      'tag'::text,
      CASE
        WHEN pi.constraint_level = 'boost' THEN 30
        WHEN pi.constraint_level = 'soft' THEN -30
        WHEN pi.constraint_level = 'strong' THEN -25
        ELSE 0
      END,
      10,
      'preference_item'::text
    FROM preference_items pi
    JOIN nutrition.food_tags ft ON ft.tag_code = pi.tag_code
    WHERE pi.target_type = 'tag'
      AND pi.tag_code IS NOT NULL
      AND pi.constraint_level <> 'neutral'

    UNION ALL

    SELECT
      epm.food_id,
      pi.constraint_level,
      'exclusion_preset'::text,
      CASE
        WHEN pi.constraint_level = 'boost' THEN 30
        WHEN pi.constraint_level = 'soft' THEN -30
        WHEN pi.constraint_level = 'strong' THEN -25
        ELSE 0
      END,
      10,
      'preference_item'::text
    FROM preference_items pi
    JOIN nutrition.exclusion_preset_matches epm
      ON epm.preset_code = pi.exclusion_preset_code
    WHERE pi.target_type = 'exclusion_preset'
      AND pi.exclusion_preset_code IS NOT NULL
      AND pi.constraint_level <> 'neutral'

    UNION ALL

    SELECT
      ft.food_id,
      'hard'::text,
      'allergy'::text,
      0,
      100,
      'profile_allergy'::text
    FROM user_preference up
    JOIN allergy_tag_map m ON m.source_code = ANY(up.allergies)
    JOIN nutrition.food_tags ft ON ft.tag_code = m.tag_code

    UNION ALL

    SELECT
      ft.food_id,
      'strong'::text,
      'intolerance'::text,
      -25,
      90,
      'profile_intolerance'::text
    FROM user_preference up
    JOIN allergy_tag_map m ON m.source_code = ANY(up.intolerances)
    JOIN nutrition.food_tags ft ON ft.tag_code = m.tag_code

    UNION ALL

    SELECT
      ft.food_id,
      'hard'::text,
      'general_tag'::text,
      0,
      80,
      'profile_general_exclusion'::text
    FROM user_preference up
    JOIN nutrition.tag_definitions td ON td.code = ANY(up.general_exclusions)
    JOIN nutrition.food_tags ft ON ft.tag_code = td.code

    UNION ALL

    SELECT
      epm.food_id,
      'hard'::text,
      'general_preset'::text,
      0,
      80,
      'profile_general_exclusion'::text
    FROM user_preference up
    JOIN nutrition.exclusion_presets ep ON ep.code = ANY(up.general_exclusions)
    JOIN nutrition.exclusion_preset_matches epm ON epm.preset_code = ep.code

    UNION ALL

    SELECT
      f.id,
      'hard'::text,
      'diet_type'::text,
      0,
      70,
      'profile_diet_type'::text
    FROM user_preference up
    JOIN nutrition.foods f ON TRUE
    WHERE up.diet_type = 'vegan'
      AND NOT EXISTS (
        SELECT 1 FROM nutrition.food_tags ft
        WHERE ft.food_id = f.id AND ft.tag_code = 'vegan'
      )

    UNION ALL

    SELECT
      f.id,
      'hard'::text,
      'diet_type'::text,
      0,
      70,
      'profile_diet_type'::text
    FROM user_preference up
    JOIN nutrition.foods f ON TRUE
    WHERE up.diet_type = 'vegetarian'
      AND NOT EXISTS (
        SELECT 1 FROM nutrition.food_tags ft
        WHERE ft.food_id = f.id AND ft.tag_code = 'vegetarian'
      )

    UNION ALL

    SELECT
      f.id,
      'hard'::text,
      'diet_type'::text,
      0,
      70,
      'profile_diet_type'::text
    FROM user_preference up
    JOIN nutrition.foods f ON TRUE
    LEFT JOIN nutrition.food_categories fc ON fc.id = f.category_id
    WHERE up.diet_type = 'pescatarian'
      AND COALESCE(fc.food_group_code, substring(f.bls_code, 1, 1)) IN ('U', 'V', 'W')
  )
  SELECT DISTINCT
    p_user_id,
    food_id,
    constraint_level,
    match_type,
    score,
    specificity,
    source,
    now()
  FROM preference_targets;
END;
$$;


ALTER FUNCTION nutrition.refresh_food_preference_search_targets(p_user_id uuid) OWNER TO postgres;

--
-- Name: refresh_food_preference_search_targets_trigger(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.refresh_food_preference_search_targets_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM nutrition.refresh_food_preference_search_targets(COALESCE(NEW.user_id, OLD.user_id));
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION nutrition.refresh_food_preference_search_targets_trigger() OWNER TO postgres;

--
-- Name: schema_debug(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.schema_debug() RETURNS json
    LANGUAGE sql STABLE
    AS $$
WITH table_state AS (
  SELECT
    EXISTS (
      SELECT 1
      FROM information_schema.schemata
      WHERE schema_name = 'nutrition'
    ) AS schema_exists,
    to_regclass('nutrition.nutrient_defs') IS NOT NULL AS table_exists
),
row_state AS (
  SELECT CASE
    WHEN (SELECT table_exists FROM table_state)
      THEN (SELECT COUNT(*)::int FROM nutrition.nutrient_defs)
    ELSE 0
  END AS row_count
),
columns_json AS (
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'name', column_name,
        'data_type', data_type,
        'is_nullable', is_nullable = 'YES'
      )
      ORDER BY ordinal_position
    ),
    '[]'::json
  ) AS value
  FROM information_schema.columns
  WHERE table_schema = 'nutrition'
    AND table_name = 'nutrient_defs'
),
indexes_json AS (
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'name', indexname,
        'definition', indexdef
      )
      ORDER BY indexname
    ),
    '[]'::json
  ) AS value
  FROM pg_indexes
  WHERE schemaname = 'nutrition'
    AND tablename = 'nutrient_defs'
),
constraints_json AS (
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'name', conname,
        'definition', pg_get_constraintdef(c.oid)
      )
      ORDER BY conname
    ),
    '[]'::json
  ) AS value
  FROM pg_constraint c
  JOIN pg_class t ON t.oid = c.conrelid
  JOIN pg_namespace n ON n.oid = t.relnamespace
  WHERE n.nspname = 'nutrition'
    AND t.relname = 'nutrient_defs'
),
group_counts_json AS (
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'group_de', group_de,
        'group_en', group_en,
        'row_count', row_count
      )
      ORDER BY row_count DESC, group_de
    ),
    '[]'::json
  ) AS value
  FROM (
    SELECT
      group_de,
      group_en,
      COUNT(*)::int AS row_count
    FROM nutrition.nutrient_defs
    GROUP BY group_de, group_en
  ) grouped
),
nutrient_preview_json AS (
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'code', code,
        'name_de', name_de,
        'name_en', name_en,
        'name_th', name_th,
        'unit', unit,
        'group_de', group_de,
        'group_en', group_en,
        'group_th', group_th,
        'sort_index', sort_index,
        'display_tier', display_tier,
        'is_always_computed', is_always_computed,
        'is_partly_computed', is_partly_computed,
        'formula', formula,
        'rda_male', rda_male,
        'rda_female', rda_female,
        'rda_unit', rda_unit
      )
      ORDER BY sort_index, code
    ),
    '[]'::json
  ) AS value
  FROM (
    SELECT
      code,
      name_de,
      name_en,
      name_th,
      unit,
      group_de,
      group_en,
      group_th,
      sort_index,
      display_tier,
      is_always_computed,
      is_partly_computed,
      formula,
      rda_male,
      rda_female,
      rda_unit
    FROM nutrition.nutrient_defs
    ORDER BY sort_index, code
    LIMIT 138
  ) preview
),
rda_summary_json AS (
  SELECT json_build_object(
    'rda_male_populated', COUNT(*) FILTER (WHERE rda_male IS NOT NULL)::int,
    'rda_female_populated', COUNT(*) FILTER (WHERE rda_female IS NOT NULL)::int,
    'rda_unit_populated', COUNT(*) FILTER (WHERE rda_unit IS NOT NULL AND rda_unit <> '')::int
  ) AS value
  FROM nutrition.nutrient_defs
),
food_foundation_json AS (
  SELECT json_build_object(
    'foods_table_exists', to_regclass('nutrition.foods') IS NOT NULL,
    'food_nutrients_table_exists', to_regclass('nutrition.food_nutrients') IS NOT NULL,
    'foods_row_count', CASE
      WHEN to_regclass('nutrition.foods') IS NULL THEN 0
      ELSE (SELECT GREATEST(c.reltuples::int, 0) FROM pg_class c WHERE c.oid = to_regclass('nutrition.foods'))
    END,
    'food_nutrients_row_count', CASE
      WHEN to_regclass('nutrition.food_nutrients') IS NULL THEN 0
      ELSE (SELECT GREATEST(c.reltuples::int, 0) FROM pg_class c WHERE c.oid = to_regclass('nutrition.food_nutrients'))
    END,
    'food_nutrients_nutrient_fk_exists', EXISTS (
      SELECT 1
      FROM pg_constraint c
      JOIN pg_class source_table ON source_table.oid = c.conrelid
      JOIN pg_namespace source_ns ON source_ns.oid = source_table.relnamespace
      JOIN pg_class target_table ON target_table.oid = c.confrelid
      JOIN pg_namespace target_ns ON target_ns.oid = target_table.relnamespace
      JOIN unnest(c.conkey) WITH ORDINALITY source_key(attnum, ordinality) ON true
      JOIN pg_attribute source_attribute
        ON source_attribute.attrelid = source_table.oid
       AND source_attribute.attnum = source_key.attnum
      JOIN unnest(c.confkey) WITH ORDINALITY target_key(attnum, ordinality)
        ON target_key.ordinality = source_key.ordinality
      JOIN pg_attribute target_attribute
        ON target_attribute.attrelid = target_table.oid
       AND target_attribute.attnum = target_key.attnum
      WHERE c.contype = 'f'
        AND source_ns.nspname = 'nutrition'
        AND source_table.relname = 'food_nutrients'
        AND source_attribute.attname = 'nutrient_code'
        AND target_ns.nspname = 'nutrition'
        AND target_table.relname = 'nutrient_defs'
        AND target_attribute.attname = 'code'
    )
  ) AS value
)
SELECT json_build_object(
  'schema_exists', (SELECT schema_exists FROM table_state),
  'table_exists', (SELECT table_exists FROM table_state),
  'row_count', (SELECT row_count FROM row_state),
  'columns', (SELECT value FROM columns_json),
  'indexes', (SELECT value FROM indexes_json),
  'constraints', (SELECT value FROM constraints_json),
  'group_counts', (SELECT value FROM group_counts_json),
  'nutrient_preview', (SELECT value FROM nutrient_preview_json),
  'rda_summary', (SELECT value FROM rda_summary_json),
  'food_foundation', (SELECT value FROM food_foundation_json)
)
$$;


ALTER FUNCTION nutrition.schema_debug() OWNER TO postgres;

--
-- Name: search_events_report(); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.search_events_report() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
WITH no_results AS (
  SELECT normalized_query, min(query) AS example_query, count(*)::int AS searches
  FROM nutrition.search_events
  WHERE result_count = 0
  GROUP BY normalized_query
  ORDER BY count(*) DESC, normalized_query
  LIMIT 50
),
no_selection AS (
  SELECT normalized_query, min(query) AS example_query, count(*)::int AS searches
  FROM nutrition.search_events
  WHERE result_count > 0 AND selected_food_id IS NULL
  GROUP BY normalized_query
  ORDER BY count(*) DESC, normalized_query
  LIMIT 50
),
not_rank_one AS (
  SELECT
    normalized_query,
    min(query) AS example_query,
    count(*)::int AS selections,
    round(avg(selected_rank)::numeric, 2) AS avg_selected_rank
  FROM nutrition.search_events
  WHERE selected_rank IS NOT NULL AND selected_rank > 1
  GROUP BY normalized_query
  ORDER BY count(*) DESC, avg(selected_rank) DESC, normalized_query
  LIMIT 50
),
session_pairs AS (
  SELECT
    session_id,
    query AS first_query,
    lead(query) OVER (PARTITION BY session_id ORDER BY searched_at, id) AS second_query,
    searched_at AS first_at,
    lead(searched_at) OVER (PARTITION BY session_id ORDER BY searched_at, id) AS second_at
  FROM nutrition.search_events
),
quick_pairs AS (
  SELECT
    session_id,
    first_query,
    second_query,
    first_at,
    second_at,
    extract(epoch from (second_at - first_at))::int AS seconds_between
  FROM session_pairs
  WHERE second_query IS NOT NULL
    AND second_at <= first_at + interval '60 seconds'
  ORDER BY first_at DESC
  LIMIT 100
)
SELECT jsonb_build_object(
  'no_results', COALESCE((SELECT jsonb_agg(to_jsonb(no_results)) FROM no_results), '[]'::jsonb),
  'with_results_no_selection', COALESCE((SELECT jsonb_agg(to_jsonb(no_selection)) FROM no_selection), '[]'::jsonb),
  'selected_not_rank_one', COALESCE((SELECT jsonb_agg(to_jsonb(not_rank_one)) FROM not_rank_one), '[]'::jsonb),
  'session_query_pairs_60s', COALESCE((SELECT jsonb_agg(to_jsonb(quick_pairs)) FROM quick_pairs), '[]'::jsonb)
);
$$;


ALTER FUNCTION nutrition.search_events_report() OWNER TO postgres;

--
-- Name: FUNCTION search_events_report(); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.search_events_report() IS 'C-18: Auswertung Suchprotokoll fuer service_role: Nulltreffer, Treffer ohne Auswahl, Auswahl nicht Platz 1, schnelle Sitzungsfolgen.';


--
-- Name: search_fold(text); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.search_fold(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT btrim(regexp_replace(
           regexp_replace(
             replace(replace(replace(replace(
               lower(coalesce(t, '')),
               'ä', 'ae'), 'ö', 'oe'), 'ü', 'ue'), 'ß', 'ss'),
             '[^a-z0-9]+', ' ', 'g'),
           '\s+', ' ', 'g'))
$$;


ALTER FUNCTION nutrition.search_fold(t text) OWNER TO postgres;

--
-- Name: FUNCTION search_fold(t text); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.search_fold(t text) IS 'Einzige Faltungsregel der Suche. Muss Zeichen fuer Zeichen normalizeFoodSearchText in apps/web/src/lib/nutrition/food-search.ts entsprechen. Die Gegenprobe steht in supabase/_pipeline/_validierung/v072_normalisierung.sql — laufen die beiden auseinander, bricht die Suche STILL.';


--
-- Name: such_alias_treffer(jsonb); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.such_alias_treffer(p_groups jsonb) RETURNS TABLE(nr integer, food_id uuid)
    LANGUAGE plpgsql STABLE PARALLEL SAFE
    AS $$
DECLARE
  v_gruppe jsonb;
  v_nr integer := 0;
  v_bed text;
BEGIN
  IF p_groups IS NULL OR jsonb_typeof(p_groups) <> 'array' THEN RETURN; END IF;
  FOR v_gruppe IN SELECT * FROM jsonb_array_elements(p_groups) LOOP
    v_nr := v_nr + 1;
    SELECT string_agg(
             'nutrition.search_fold(alias) LIKE ' || quote_literal('%' || a || '%'),
             ' OR ')
      INTO v_bed
      FROM jsonb_array_elements_text(v_gruppe) AS t(a)
      WHERE a <> '';
    CONTINUE WHEN v_bed IS NULL;
    RETURN QUERY EXECUTE
      'SELECT DISTINCT ' || v_nr || '::integer, fa.food_id
       FROM nutrition.food_aliases fa WHERE ' || v_bed;
  END LOOP;
END;
$$;


ALTER FUNCTION nutrition.such_alias_treffer(p_groups jsonb) OWNER TO postgres;

--
-- Name: FUNCTION such_alias_treffer(p_groups jsonb); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.such_alias_treffer(p_groups jsonb) IS 'C-17: Food-IDs je Suchgruppe ueber die Aliase, einmal ermittelt statt je Zeile. Dynamisches SQL, damit der Trigramm-Index greift.';


--
-- Name: such_rang_wortgrenze(text, jsonb); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.such_rang_wortgrenze(p_name text, p_groups jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  -- Je Gruppe die BESTE Alternative (GREATEST/max), ueber alle Gruppen
  -- die SCHLECHTESTE (LEAST/min): jede Gruppe muss gut sitzen, sonst
  -- traegt der Treffer nicht. Bei "haehnchenbrust" sind das
  -- [haehnchen|huhn] und [brust] — beide muessen Woerter treffen.
  SELECT CASE
    WHEN p_groups IS NULL OR jsonb_typeof(p_groups) <> 'array'
      OR jsonb_array_length(p_groups) = 0 THEN 0
    ELSE COALESCE((
      SELECT min(g.beste)
      FROM (
        SELECT grp.nr,
               COALESCE(max(CASE
                 WHEN nutrition.search_fold(COALESCE(p_name,'')) = a.alt THEN 3
                 WHEN nutrition.search_fold(COALESCE(p_name,'')) ~ ('\m' || a.alt) THEN 2
                 ELSE 0 END), 0) AS beste
        -- Gruppiert wird ueber die POSITION, nicht ueber den Inhalt:
        -- zwei gleiche Gruppen duerfen nicht zu einer verschmelzen.
        FROM jsonb_array_elements(p_groups) WITH ORDINALITY AS grp(gruppe, nr),
             LATERAL jsonb_array_elements_text(grp.gruppe) AS a(alt)
        GROUP BY grp.nr
      ) g
    ), 0)
  END;
$$;


ALTER FUNCTION nutrition.such_rang_wortgrenze(p_name text, p_groups jsonb) OWNER TO postgres;

--
-- Name: FUNCTION such_rang_wortgrenze(p_name text, p_groups jsonb); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.such_rang_wortgrenze(p_name text, p_groups jsonb) IS 'C-20: 3 = Name ist das Wort, 2 = Treffer an einer Wortgrenze, 0 = nur Wortmitte. Max je Gruppe, Min ueber die Gruppen.';


--
-- Name: such_rang_zubereitung(text); Type: FUNCTION; Schema: nutrition; Owner: postgres
--

CREATE FUNCTION nutrition.such_rang_zubereitung(p_bls_code text) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE WHEN substr(COALESCE(p_bls_code, ''), 5, 3) IN ('100', '000')
              THEN 1 ELSE 0 END;
$$;


ALTER FUNCTION nutrition.such_rang_zubereitung(p_bls_code text) OWNER TO postgres;

--
-- Name: FUNCTION such_rang_zubereitung(p_bls_code text); Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON FUNCTION nutrition.such_rang_zubereitung(p_bls_code text) IS 'C-25: 1 fuer unzubereitete Formen (Zubereitungscode 100 = roh oder 000 = einzige Form), sonst 0. Wer eine Zutat sucht, will die Rohform.';


