CREATE FUNCTION recovery.modality_bonus_value(p_modality_type text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN p_modality_type IN (
      'sauna',
      'cold_plunge',
      'contrast_therapy',
      'massage',
      'foam_rolling',
      'stretching',
      'yoga',
      'meditation',
      'breathwork',
      'nap',
      'active_recovery',
      'other'
    ) THEN 0::numeric
    ELSE 0::numeric
  END;
$$;


