--
-- Name: scores; Type: TABLE; Schema: recovery; Owner: postgres
--

CREATE TABLE recovery.scores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    entry_date date NOT NULL,
    mode text DEFAULT 'manual'::text NOT NULL,
    score numeric(5,1) NOT NULL,
    algorithm_version text DEFAULT 'manual_v2_c215'::text NOT NULL,
    sleep_quality_score numeric(5,1) NOT NULL,
    sleep_duration_score numeric(5,1) NOT NULL,
    subjective_feeling_score numeric(5,1) NOT NULL,
    soreness_score numeric(5,1) NOT NULL,
    training_load_score numeric(5,1) NOT NULL,
    nutrition_score numeric(5,1) NOT NULL,
    mood_score numeric(5,1) NOT NULL,
    hrv_score numeric(5,1),
    sleep_quality_points numeric(5,2) NOT NULL,
    sleep_duration_points numeric(5,2) NOT NULL,
    subjective_feeling_points numeric(5,2) NOT NULL,
    soreness_points numeric(5,2) NOT NULL,
    training_load_points numeric(5,2) NOT NULL,
    nutrition_points numeric(5,2) NOT NULL,
    mood_points numeric(5,2) NOT NULL,
    modality_bonus numeric(4,2) DEFAULT 0 NOT NULL,
    sleep_hours_used numeric(3,1),
    soreness_avg_used numeric(4,2) DEFAULT 0 NOT NULL,
    soreness_reported_count integer DEFAULT 0 NOT NULL,
    nutrition_source text DEFAULT 'fallback_c123_e9'::text NOT NULL,
    hrv_source text DEFAULT 'not_used_manual_mode'::text NOT NULL,
    modality_bonus_source text DEFAULT 'pending_c124_e5'::text NOT NULL,
    fallbacks jsonb DEFAULT '{}'::jsonb NOT NULL,
    calculated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    measurement_source text DEFAULT 'derived'::text NOT NULL,
    source_detail text,
    CONSTRAINT scores_fallbacks_check CHECK ((jsonb_typeof(fallbacks) = 'object'::text)),
    CONSTRAINT scores_hrv_score_check CHECK (((hrv_score IS NULL) OR ((hrv_score >= (0)::numeric) AND (hrv_score <= (100)::numeric)))),
    CONSTRAINT scores_measurement_source_check CHECK ((measurement_source = ANY (ARRAY['manual'::text, 'device'::text, 'import'::text, 'admin'::text, 'seed'::text, 'derived'::text]))),
    CONSTRAINT scores_modality_bonus_check CHECK (((modality_bonus >= (0)::numeric) AND (modality_bonus <= (5)::numeric))),
    CONSTRAINT scores_mode_check CHECK ((mode = 'manual'::text)),
    CONSTRAINT scores_mood_score_check CHECK (((mood_score >= (0)::numeric) AND (mood_score <= (100)::numeric))),
    CONSTRAINT scores_nutrition_score_check CHECK (((nutrition_score >= (0)::numeric) AND (nutrition_score <= (100)::numeric))),
    CONSTRAINT scores_score_check CHECK (((score >= (0)::numeric) AND (score <= (100)::numeric))),
    CONSTRAINT scores_sleep_duration_score_check CHECK (((sleep_duration_score >= (0)::numeric) AND (sleep_duration_score <= (100)::numeric))),
    CONSTRAINT scores_sleep_quality_score_check CHECK (((sleep_quality_score >= (0)::numeric) AND (sleep_quality_score <= (100)::numeric))),
    CONSTRAINT scores_soreness_reported_count_check CHECK ((soreness_reported_count >= 0)),
    CONSTRAINT scores_soreness_score_check CHECK (((soreness_score >= (0)::numeric) AND (soreness_score <= (100)::numeric))),
    CONSTRAINT scores_subjective_feeling_score_check CHECK (((subjective_feeling_score >= (0)::numeric) AND (subjective_feeling_score <= (100)::numeric))),
    CONSTRAINT scores_training_load_score_check CHECK (((training_load_score >= (0)::numeric) AND (training_load_score <= (100)::numeric)))
);


