$$;


ALTER FUNCTION storage.operation() OWNER TO supabase_storage_admin;

--
-- Name: protect_delete(); Type: FUNCTION; Schema: storage; Owner: supabase_storage_admin
--

CREATE FUNCTION storage.protect_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if storage.allow_delete_query is set to 'true'
    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN
        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'
            USING HINT = 'This prevents accidental data loss from orphaned objects.',
                  ERRCODE = '42501';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION storage.protect_delete() OWNER TO supabase_storage_admin;

--
-- Name: search(text, text, integer, integer, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: supabase_storage_admin
--

CREATE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text) RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;
    v_skipped INT := 0;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach (unchanged)
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT path_tokens[$1] AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $2 || '%%'
                  AND bucket_id = $3
                  AND array_length(objects.path_tokens, 1) <> $1
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata FROM folders)
            UNION ALL
            (SELECT path_tokens[$1] AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata
             FROM storage.objects
             WHERE objects.name ILIKE $2 || '%%'
               AND bucket_id = $3
               AND array_length(objects.path_tokens, 1) = $1
             ORDER BY %I %s)
            LIMIT $4 OFFSET $5
            $sql$, v_sort_order, v_order_by, v_sort_order
        ) USING levels, v_prefix, bucketname, v_limit, offsets;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'AND lower(o.name) COLLATE "C" < $3 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'AND lower(o.name) COLLATE "C" >= $3 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC: find the last item in range first (static SQL)
        IF v_upper_bound IS NOT NULL THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower AND lower(o.name) COLLATE "C" < v_upper_bound
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSIF v_prefix_lower <> '' THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSE
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        END IF;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix_lower <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := split_part(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter), v_delimiter, levels);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := lower(v_current.name);
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := split_part(v_current.name, v_delimiter, levels);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := lower(v_current.name) || v_delimiter;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;


ALTER FUNCTION storage.search(prefix text, bucketname text, limits integer, levels integer, offsets integer, search text, sortcolumn text, sortorder text) OWNER TO supabase_storage_admin;

--
-- Name: search_by_timestamp(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: supabase_storage_admin
--

CREATE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_cursor_op text;
    v_query text;
    v_prefix text;
BEGIN
    v_prefix := coalesce(p_prefix, '');

    IF p_sort_order = 'asc' THEN
        v_cursor_op := '>';
    ELSE
        v_cursor_op := '<';
    END IF;

    v_query := format($sql$
        WITH raw_objects AS (
            SELECT
                o.name AS obj_name,
                o.id AS obj_id,
                o.updated_at AS obj_updated_at,
                o.created_at AS obj_created_at,
                o.last_accessed_at AS obj_last_accessed_at,
                o.metadata AS obj_metadata,
                storage.get_common_prefix(o.name, $1, '/') AS common_prefix
            FROM storage.objects o
            WHERE o.bucket_id = $2
              AND o.name COLLATE "C" LIKE $1 || '%%'
        ),
        -- Aggregate common prefixes (folders)
        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior
        aggregated_prefixes AS (
            SELECT
                rtrim(common_prefix, '/') AS name,
                NULL::uuid AS id,
                MIN(obj_created_at) AS updated_at,
                MIN(obj_created_at) AS created_at,
                NULL::timestamptz AS last_accessed_at,
                NULL::jsonb AS metadata,
                TRUE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NOT NULL
            GROUP BY common_prefix
        ),
        leaf_objects AS (
            SELECT
                obj_name AS name,
                obj_id AS id,
                obj_updated_at AS updated_at,
                obj_created_at AS created_at,
                obj_last_accessed_at AS last_accessed_at,
                obj_metadata AS metadata,
                FALSE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NULL
        ),
        combined AS (
            SELECT * FROM aggregated_prefixes
            UNION ALL
            SELECT * FROM leaf_objects
        ),
        filtered AS (
            SELECT *
            FROM combined
            WHERE (
                $5 = ''
                OR ROW(
                    date_trunc('milliseconds', %I),
                    name COLLATE "C"
                ) %s ROW(
                    COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz),
                    $5
                )
            )
        )
        SELECT
            split_part(name, '/', $3) AS key,
            name,
            id,
            updated_at,
            created_at,
            last_accessed_at,
            metadata
        FROM filtered
        ORDER BY
            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,
            name COLLATE "C" %s
        LIMIT $4
    $sql$,
        p_sort_column,
        v_cursor_op,
        p_sort_column,
        p_sort_order,
        p_sort_order
    );

    RETURN QUERY EXECUTE v_query
    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after;
END;
$_$;


ALTER FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text) OWNER TO supabase_storage_admin;

--
-- Name: search_v2(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: supabase_storage_admin
--

CREATE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_sort_col text;
    v_sort_ord text;
    v_limit int;
BEGIN
    -- Cap limit to maximum of 1500 records
    v_limit := LEAST(coalesce(limits, 100), 1500);

    -- Validate and normalize sort_order
    v_sort_ord := lower(coalesce(sort_order, 'asc'));
    IF v_sort_ord NOT IN ('asc', 'desc') THEN
        v_sort_ord := 'asc';
    END IF;

    -- Validate and normalize sort_column
    v_sort_col := lower(coalesce(sort_column, 'name'));
    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN
        v_sort_col := 'name';
    END IF;

    -- Route to appropriate implementation
    IF v_sort_col = 'name' THEN
        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))
        RETURN QUERY
        SELECT
            split_part(l.name, '/', levels) AS key,
            l.name AS name,
            l.id,
            l.updated_at,
            l.created_at,
            l.last_accessed_at,
            l.metadata
        FROM storage.list_objects_with_delimiter(
            bucket_name,
            coalesce(prefix, ''),
            '/',
            v_limit,
            start_after,
            '',
            v_sort_ord
        ) l;
    ELSE
        -- Use aggregation approach for timestamp sorting
        -- Not efficient for large datasets but supports correct pagination
        RETURN QUERY SELECT * FROM storage.search_by_timestamp(
            prefix, bucket_name, v_limit, levels, start_after,
            v_sort_ord, v_sort_col, sort_column_after
        );
    END IF;
END;
$$;


ALTER FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer, levels integer, start_after text, sort_order text, sort_column text, sort_column_after text) OWNER TO supabase_storage_admin;

--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: storage; Owner: supabase_storage_admin
--

CREATE FUNCTION storage.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$$;


ALTER FUNCTION storage.update_updated_at_column() OWNER TO supabase_storage_admin;

--
-- Name: http_request(); Type: FUNCTION; Schema: supabase_functions; Owner: supabase_functions_admin
--

CREATE FUNCTION supabase_functions.http_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'supabase_functions'
    AS $$
  DECLARE
    request_id bigint;
    payload jsonb;
    url text := TG_ARGV[0]::text;
    method text := TG_ARGV[1]::text;
    headers jsonb DEFAULT '{}'::jsonb;
    params jsonb DEFAULT '{}'::jsonb;
    timeout_ms integer DEFAULT 1000;
  BEGIN
    IF url IS NULL OR url = 'null' THEN
      RAISE EXCEPTION 'url argument is missing';
    END IF;

    IF method IS NULL OR method = 'null' THEN
      RAISE EXCEPTION 'method argument is missing';
    END IF;

    IF TG_ARGV[2] IS NULL OR TG_ARGV[2] = 'null' THEN
      headers = '{"Content-Type": "application/json"}'::jsonb;
    ELSE
      headers = TG_ARGV[2]::jsonb;
    END IF;

    IF TG_ARGV[3] IS NULL OR TG_ARGV[3] = 'null' THEN
      params = '{}'::jsonb;
    ELSE
      params = TG_ARGV[3]::jsonb;
    END IF;

    IF TG_ARGV[4] IS NULL OR TG_ARGV[4] = 'null' THEN
      timeout_ms = 1000;
    ELSE
      timeout_ms = TG_ARGV[4]::integer;
    END IF;

    CASE
      WHEN method = 'GET' THEN
        SELECT http_get INTO request_id FROM net.http_get(
          url,
          params,
          headers,
          timeout_ms
        );
      WHEN method = 'POST' THEN
        payload = jsonb_build_object(
          'old_record', OLD,
          'record', NEW,
          'type', TG_OP,
          'table', TG_TABLE_NAME,
          'schema', TG_TABLE_SCHEMA
        );

        SELECT http_post INTO request_id FROM net.http_post(
          url,
          payload,
          params,
          headers,
          timeout_ms
        );
      ELSE
        RAISE EXCEPTION 'method argument % is invalid', method;
    END CASE;

    INSERT INTO supabase_functions.hooks
      (hook_table_id, hook_name, request_id)
    VALUES
      (TG_RELID, TG_NAME, request_id);

    RETURN NEW;
  END
$$;


ALTER FUNCTION supabase_functions.http_request() OWNER TO supabase_functions_admin;

--
-- Name: platform_input_status(uuid, date); Type: FUNCTION; Schema: supplements; Owner: postgres
--

CREATE FUNCTION supplements.platform_input_status(p_user_id uuid, p_entry_date date DEFAULT CURRENT_DATE) RETURNS TABLE(input_path text, input_status text, missing_reason text, detail jsonb)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_stack_items integer;
  v_stack_matches integer;
  v_medications integer;
  v_conditions integer;
  v_labs integer;
  v_daily integer;
  v_age integer;
  v_profile_weight numeric;
  v_profile_sex text;
  v_pregnancy_planned boolean;
  v_training_week integer;
BEGIN
  SELECT count(*) INTO v_stack_items
  FROM supplements.user_stacks us
  JOIN supplements.stack_items si ON si.stack_id = us.id
  WHERE us.user_id = p_user_id
    AND us.is_active
    AND si.is_active;

  SELECT count(DISTINCT stack_item_id) INTO v_stack_matches
  FROM supplements.stack_item_substance_matches
  WHERE user_id = p_user_id
    AND is_active;

  SELECT count(*) INTO v_medications
  FROM medical.user_medications
  WHERE user_id = p_user_id
    AND is_active
    AND start_date <= p_entry_date
    AND (end_date IS NULL OR end_date >= p_entry_date);

  SELECT count(*) INTO v_conditions
  FROM medical.user_conditions
  WHERE user_id = p_user_id
    AND status IN ('active', 'planned', 'unknown')
    AND (start_date IS NULL OR start_date <= p_entry_date)
    AND (end_date IS NULL OR end_date >= p_entry_date);

  SELECT count(*) INTO v_labs
  FROM medical.lab_reports r
  JOIN medical.lab_result_values v ON v.report_id = r.id
  WHERE r.user_id = p_user_id
    AND r.report_date <= p_entry_date;

  SELECT count(*) INTO v_daily
  FROM nutrition.daily_summary
  WHERE user_id = p_user_id
    AND entry_date = p_entry_date;

  SELECT
    date_part('year', age(p_entry_date, birth_date))::integer,
    body_weight_kg,
    biological_sex,
    CASE
      WHEN pregnancy_started_on IS NOT NULL
       AND pregnancy_started_on <= p_entry_date
       AND (pregnancy_ended_on IS NULL OR pregnancy_ended_on >= p_entry_date)
      THEN true
      ELSE false
    END
  INTO v_age, v_profile_weight, v_profile_sex, v_pregnancy_planned
  FROM public.profiles
  WHERE id = p_user_id;

  SELECT count(*) INTO v_training_week
  FROM training.workout_sessions
  WHERE user_id = p_user_id
    AND status = 'completed'
    AND session_date BETWEEN p_entry_date - 6 AND p_entry_date;

  RETURN QUERY VALUES
    (
      'medical.medications',
      CASE WHEN v_medications > 0 THEN 'available' ELSE 'no_data' END,
      CASE WHEN v_medications > 0 THEN NULL ELSE 'no active medication rows for day' END,
      jsonb_build_object('active_medications', v_medications)
    ),
    (
      'medical.medications[].drug_class',
      CASE WHEN v_medications > 0 THEN 'available' ELSE 'no_data' END,
      CASE WHEN v_medications > 0 THEN NULL ELSE 'no active medication rows for day' END,
      jsonb_build_object('active_medications', v_medications)
    ),
    (
      'medical.medications[].cyp_profile',
      CASE WHEN v_medications > 0 THEN 'available' ELSE 'no_data' END,
      CASE WHEN v_medications > 0 THEN NULL ELSE 'no active medication rows for day' END,
      jsonb_build_object('active_medications', v_medications)
    ),
    (
      'medical.conditions',
      CASE WHEN v_conditions > 0 THEN 'available' ELSE 'no_data' END,
      CASE WHEN v_conditions > 0 THEN NULL ELSE 'no active condition rows for day' END,
      jsonb_build_object('active_conditions', v_conditions)
    ),
    (
      'medical.labs',
      CASE WHEN v_labs > 0 THEN 'available' ELSE 'no_data' END,
      CASE WHEN v_labs > 0 THEN NULL ELSE 'no lab values up to day' END,
      jsonb_build_object('lab_values_up_to_day', v_labs)
    ),
    (
      'supplements.stack',
      CASE WHEN v_stack_items > 0 THEN 'available' ELSE 'no_data' END,
      CASE WHEN v_stack_items > 0 THEN NULL ELSE 'no active stack items' END,
      jsonb_build_object('active_stack_items', v_stack_items)
    ),
    (
      'supplements.stack_item.substance_id',
      CASE
        WHEN v_stack_items = 0 THEN 'no_data'
        WHEN v_stack_matches = v_stack_items THEN 'available'
        WHEN v_stack_matches > 0 THEN 'partial'
        ELSE 'missing_input'
      END,
      CASE
        WHEN v_stack_items = 0 THEN 'no active stack items'
        WHEN v_stack_matches = v_stack_items THEN NULL
        WHEN v_stack_matches > 0 THEN 'some stack items have no Kimi substance bridge'
        ELSE 'no stack item has a Kimi substance bridge'
      END,
      jsonb_build_object('active_stack_items', v_stack_items, 'matched_stack_items', v_stack_matches)
    ),
    (
      'supplements.daily_totals',
      CASE
        WHEN v_stack_items = 0 THEN 'no_data'
        WHEN v_stack_matches = v_stack_items THEN 'available'
        WHEN v_stack_matches > 0 THEN 'partial'
        ELSE 'missing_input'
      END,
      CASE
        WHEN v_stack_items = 0 THEN 'no active stack items'
        WHEN v_stack_matches = v_stack_items THEN NULL
        WHEN v_stack_matches > 0 THEN 'daily totals can only be computed for bridged stack items'
        ELSE 'daily totals need substance bridge'
      END,
      jsonb_build_object('active_stack_items', v_stack_items, 'matched_stack_items', v_stack_matches)
    ),
    (
      'supplements.daily_total_mg',
      CASE
        WHEN v_stack_items = 0 THEN 'no_data'
        WHEN v_stack_matches = v_stack_items THEN 'available'
        WHEN v_stack_matches > 0 THEN 'partial'
        ELSE 'missing_input'
      END,
      CASE
        WHEN v_stack_items = 0 THEN 'no active stack items'
        WHEN v_stack_matches = v_stack_items THEN NULL
        WHEN v_stack_matches > 0 THEN 'daily total mg can only be computed for bridged stack items'
        ELSE 'daily total mg needs substance bridge'
      END,
      jsonb_build_object('active_stack_items', v_stack_items, 'matched_stack_items', v_stack_matches)
    ),
    (
      'nutrition.daily.protein_g',
      CASE
        WHEN v_daily = 0 THEN 'no_data'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_summary
          WHERE user_id = p_user_id AND entry_date = p_entry_date
            AND prot625_missing = 0
        ) THEN 'available'
        ELSE 'incomplete'
      END,
      CASE
        WHEN v_daily = 0 THEN 'no daily_summary row'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_summary
          WHERE user_id = p_user_id AND entry_date = p_entry_date
            AND prot625_missing = 0
        ) THEN NULL
        ELSE 'protein has missing counter'
      END,
      COALESCE((
        SELECT jsonb_build_object('protein_g', prot625, 'missing', prot625_missing)
        FROM nutrition.daily_summary
        WHERE user_id = p_user_id AND entry_date = p_entry_date
      ), '{}'::jsonb)
    ),
    (
      'nutrition.protein_intake_g_per_kg',
      CASE
        WHEN v_daily = 0 THEN 'no_data'
        WHEN v_profile_weight IS NULL THEN 'missing_input'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_summary
          WHERE user_id = p_user_id AND entry_date = p_entry_date
            AND prot625_missing = 0
        ) THEN 'available'
        ELSE 'incomplete'
      END,
      CASE
        WHEN v_daily = 0 THEN 'no daily_summary row'
        WHEN v_profile_weight IS NULL THEN 'profile body_weight_kg missing'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_summary
          WHERE user_id = p_user_id AND entry_date = p_entry_date
            AND prot625_missing = 0
        ) THEN NULL
        ELSE 'protein has missing counter'
      END,
      COALESCE((
        SELECT jsonb_build_object(
          'protein_g', prot625,
          'body_weight_kg', v_profile_weight,
          'protein_g_per_kg',
          CASE WHEN v_profile_weight > 0 THEN round(prot625 / v_profile_weight, 3) ELSE NULL END,
          'missing', prot625_missing
        )
        FROM nutrition.daily_summary
        WHERE user_id = p_user_id AND entry_date = p_entry_date
      ), jsonb_build_object('body_weight_kg', v_profile_weight))
    ),
    (
      'nutrition.d_vitamin_dietary_low',
      CASE
        WHEN v_daily = 0 THEN 'no_data'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date)
          WHERE nutrient_code = 'VITD'
            AND reference_status = 'complete'
            AND reference_pct IS NOT NULL
        ) THEN 'available'
        ELSE 'partial'
      END,
      CASE
        WHEN v_daily = 0 THEN 'no daily_summary row'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date)
          WHERE nutrient_code = 'VITD'
            AND reference_status = 'complete'
            AND reference_pct IS NOT NULL
        ) THEN NULL
        ELSE 'vitamin D assessment not complete for day'
      END,
      COALESCE((
        SELECT jsonb_build_object('reference_pct', reference_pct, 'reference_status', reference_status)
        FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date)
        WHERE nutrient_code = 'VITD'
        LIMIT 1
      ), '{}'::jsonb)
    ),
    (
      'nutrition.magnesium_dietary_low',
      CASE
        WHEN v_daily = 0 THEN 'no_data'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date)
          WHERE nutrient_code = 'MG'
            AND reference_status = 'complete'
            AND reference_pct IS NOT NULL
        ) THEN 'available'
        ELSE 'partial'
      END,
      CASE
        WHEN v_daily = 0 THEN 'no daily_summary row'
        WHEN EXISTS (
          SELECT 1 FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date)
          WHERE nutrient_code = 'MG'
            AND reference_status = 'complete'
            AND reference_pct IS NOT NULL
        ) THEN NULL
        ELSE 'magnesium assessment not complete for day'
      END,
      COALESCE((
        SELECT jsonb_build_object('reference_pct', reference_pct, 'reference_status', reference_status)
        FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date)
        WHERE nutrient_code = 'MG'
        LIMIT 1
      ), '{}'::jsonb)
    ),
    (
      'nutrition.caffeine_mg_day',
      'partial',
      'caffeine is not a dedicated daily_summary nutrient; only indirect food records exist',
      '{}'::jsonb
    ),
    (
      'profile.age',
      CASE WHEN v_age IS NULL THEN 'missing_input' ELSE 'available' END,
      CASE WHEN v_age IS NULL THEN 'profile birth_date missing' ELSE NULL END,
      jsonb_build_object('age', v_age)
    ),
    (
      'profile.sex',
      CASE WHEN v_profile_sex IS NULL THEN 'missing_input' ELSE 'available' END,
      CASE WHEN v_profile_sex IS NULL THEN 'profile biological_sex missing' ELSE NULL END,
      jsonb_build_object('sex', v_profile_sex)
    ),
    (
      'profile.pregnancy_planned',
      'available',
      NULL,
      jsonb_build_object('pregnancy_planned', v_pregnancy_planned)
    ),
    (
      'training.resistance_sessions_per_week',
      CASE WHEN v_training_week > 0 THEN 'available' ELSE 'no_data' END,
      CASE WHEN v_training_week > 0 THEN NULL ELSE 'no completed training sessions in 7 day window' END,
      jsonb_build_object('completed_sessions_7d', v_training_week)
    ),
    (
      'training.load_spike',
      'no_data',
      'ACWR was removed from recovery scoring in C-215; no load spike model is built',
      jsonb_build_object('completed_sessions_7d', v_training_week)
    ),
    (
      'sleep.sleep_latency_min',
      'missing_input',
      'sleep schema is not built',
      '{}'::jsonb
    ),
    (
      'medical.symptoms',
      'missing_input',
      'symptoms table is not built',
      '{}'::jsonb
    ),
    (
      'medical.lab_draw_scheduled_within_days',
      'missing_input',
      'scheduled lab draw model is not built',
      '{}'::jsonb
    ),
    (
      'nutrition.daily.fish_servings_week',
      'missing_input',
      'fish servings are not derived from meal_items',
      '{}'::jsonb
    ),
    (
      'nutrition.daily.dairy_servings_day',
      'missing_input',
      'dairy servings are not derived from meal_items',
      '{}'::jsonb
    ),
    (
      'profile.athlete_tested_pool',
      'missing_input',
      'profile has no athlete_tested_pool field',
      '{}'::jsonb
    ),
    (
      'lifestyle.indoor_dominant',
      'missing_input',
      'lifestyle/profile has no indoor_dominant field',
      '{}'::jsonb
    ),
    (
      'location.low_sun',
      'missing_input',
      'location/climate input is not built',
      '{}'::jsonb
    ),
    (
      'supplements.computed.stimulant_load_mg_caffeine_equiv',
      'missing_input',
      'stimulant equivalence computation is not built',
      '{}'::jsonb
    ),
    (
      'sleep.quality_score',
      'missing_input',
      'sleep schema is not built',
      '{}'::jsonb
    ),
    (
      'sleep.tracked_nights',
      'missing_input',
      'sleep schema is not built',
      '{}'::jsonb
    );
END;
$$;


ALTER FUNCTION supplements.platform_input_status(p_user_id uuid, p_entry_date date) OWNER TO postgres;

--
-- Name: FUNCTION platform_input_status(p_user_id uuid, p_entry_date date); Type: COMMENT; Schema: supplements; Owner: postgres
--

COMMENT ON FUNCTION supplements.platform_input_status(p_user_id uuid, p_entry_date date) IS 'C-132: Diagnostik fuer Kimi-Regel-Eingaenge. Fehlen wird als missing_input/no_data/partial gemeldet, nicht als false.';


--
-- Name: refresh_stack_item_count(); Type: FUNCTION; Schema: supplements; Owner: postgres
--

CREATE FUNCTION supplements.refresh_stack_item_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_stack_id UUID;
BEGIN
  v_stack_id := COALESCE(NEW.stack_id, OLD.stack_id);
  UPDATE supplements.user_stacks us
  SET item_count = (
        SELECT count(*)::integer
        FROM supplements.stack_items si
        WHERE si.stack_id = v_stack_id
          AND si.is_active
      ),
      updated_at = now()
  WHERE us.id = v_stack_id;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION supplements.refresh_stack_item_count() OWNER TO postgres;

--
-- Name: rule_assessment(uuid, date); Type: FUNCTION; Schema: supplements; Owner: postgres
--

CREATE FUNCTION supplements.rule_assessment(p_user_id uuid DEFAULT auth.uid(), p_entry_date date DEFAULT CURRENT_DATE) RETURNS TABLE(rule_id text, rule_type text, message_key text, message_de text, severity text, recommended_action_type text, evaluation_state text, missing_inputs text[], matched_context jsonb)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_auth_uid UUID := auth.uid();
  v_med_traits TEXT[];
  v_med_names TEXT[];
  v_med_risk_flags TEXT[];
  v_conditions TEXT[];
  v_stack_substances TEXT[];
  v_stack_items INTEGER;
  v_lab_names TEXT[];
  v_rule supplements.rule_catalog%ROWTYPE;
  v_missing TEXT[];
  v_group_missing TEXT[];
  v_ok BOOLEAN;
  v_condition JSONB;
  v_module TEXT;
  v_field TEXT;
  v_op TEXT;
  v_value JSONB;
  v_needed TEXT[];
  v_count INTEGER;
  v_protein_per_kg NUMERIC;
  v_training_week INTEGER;
  v_vitd_pct NUMERIC;
  v_mg_pct NUMERIC;
  v_input_status JSONB;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'rule_assessment braucht user_id oder auth.uid()';
  END IF;
  IF v_auth_uid IS NOT NULL AND v_auth_uid <> p_user_id THEN
    RAISE EXCEPTION 'rule_assessment darf nur eigene Regeln auswerten';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT trait), '{}') INTO v_med_traits
  FROM (
    SELECT unnest(um.drug_class || um.cyp_profile) AS trait
    FROM medical.user_medications um
    WHERE um.user_id = p_user_id
      AND um.is_active
      AND um.start_date <= p_entry_date
      AND (um.end_date IS NULL OR um.end_date >= p_entry_date)
  ) t
  WHERE trait IS NOT NULL AND btrim(trait) <> '';

  SELECT COALESCE(array_agg(DISTINCT lower(um.name)), '{}') INTO v_med_names
  FROM medical.user_medications um
  WHERE um.user_id = p_user_id
    AND um.is_active
    AND um.start_date <= p_entry_date
    AND (um.end_date IS NULL OR um.end_date >= p_entry_date);

  SELECT COALESCE(array_agg(DISTINCT key), '{}') INTO v_med_risk_flags
  FROM medical.user_medications um
  JOIN medical.medication_active_substances mas ON mas.id = um.active_substance_id
  CROSS JOIN LATERAL jsonb_object_keys(COALESCE(mas.risk_flags, '{}'::jsonb)) key
  WHERE um.user_id = p_user_id
    AND um.is_active
    AND um.start_date <= p_entry_date
    AND (um.end_date IS NULL OR um.end_date >= p_entry_date)
    AND COALESCE((mas.risk_flags->>key)::boolean, false);

  SELECT COALESCE(array_agg(DISTINCT condition_code), '{}') INTO v_conditions
  FROM medical.user_conditions
  WHERE user_id = p_user_id
    AND status IN ('active', 'planned', 'unknown')
    AND (start_date IS NULL OR start_date <= p_entry_date)
    AND (end_date IS NULL OR end_date >= p_entry_date);

  SELECT count(*) INTO v_stack_items
  FROM supplements.user_stacks us
  JOIN supplements.stack_items si ON si.stack_id = us.id
  WHERE us.user_id = p_user_id
    AND us.is_active
    AND si.is_active;

  SELECT COALESCE(array_agg(DISTINCT kimi_substance_id), '{}') INTO v_stack_substances
  FROM supplements.stack_item_substance_matches
  WHERE user_id = p_user_id
    AND is_active
    AND kimi_substance_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT lower(v.marker_name_snapshot)), '{}') INTO v_lab_names
  FROM medical.lab_reports r
  JOIN medical.lab_result_values v ON v.report_id = r.id
  WHERE r.user_id = p_user_id
    AND r.report_date <= p_entry_date;

  SELECT round(ds.prot625 / NULLIF(p.body_weight_kg, 0), 3)
    INTO v_protein_per_kg
  FROM nutrition.daily_summary ds
  JOIN public.profiles p ON p.id = ds.user_id
  WHERE ds.user_id = p_user_id
    AND ds.entry_date = p_entry_date
    AND ds.prot625_missing = 0;

  SELECT count(*) INTO v_training_week
  FROM training.workout_sessions
  WHERE user_id = p_user_id
    AND status = 'completed'
    AND session_date BETWEEN p_entry_date - 6 AND p_entry_date;

  SELECT
    max(reference_pct) FILTER (WHERE nutrient_code = 'VITD'),
    max(reference_pct) FILTER (WHERE nutrient_code = 'MG')
  INTO v_vitd_pct, v_mg_pct
  FROM nutrition.daily_reference_assessment(p_user_id, p_entry_date)
  WHERE nutrient_code IN ('VITD', 'MG');

  SELECT COALESCE(jsonb_agg(to_jsonb(s)), '[]'::jsonb) INTO v_input_status
  FROM supplements.platform_input_status(p_user_id, p_entry_date) s;

  FOR v_rule IN
    SELECT *
    FROM supplements.rule_catalog
    ORDER BY priority_rank NULLS LAST, rule_id
  LOOP
    SELECT COALESCE(array_agg(DISTINCT s.input_path), '{}') INTO v_missing
    FROM jsonb_to_recordset(v_input_status) AS s(
      input_path text,
      input_status text,
      missing_reason text,
      detail jsonb
    )
    WHERE s.input_path = ANY(v_rule.input_paths)
      AND s.input_status IN ('missing_input', 'partial', 'incomplete');

    v_group_missing := '{}';
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_rule.conditions) c
      WHERE c->>'op' IN ('contains_any_group', 'count_group_gte')
    )
    AND COALESCE(array_length(v_rule.substance_ids, 1), 0) = 0
    AND COALESCE(array_length(v_rule.substance_group_ids, 1), 0) > 0 THEN
      v_group_missing := ARRAY['supplements.substance_group_membership'];
    END IF;

    IF COALESCE(array_length(v_missing, 1), 0) > 0
       OR COALESCE(array_length(v_group_missing, 1), 0) > 0 THEN
      rule_id := v_rule.rule_id;
      rule_type := v_rule.rule_type;
      message_key := v_rule.message_key;
      message_de := v_rule.message_de;
      severity := v_rule.severity;
      recommended_action_type := COALESCE(v_rule.recommended_action_type, 'physician_referral');
      evaluation_state := 'missing_input';
      missing_inputs := (SELECT ARRAY(SELECT DISTINCT unnest(v_missing || v_rule.missing_input_paths || v_group_missing)));
      matched_context := jsonb_build_object(
        'input_coverage_status', v_rule.input_coverage_status,
        'input_paths', v_rule.input_paths,
        'static_missing_inputs', v_rule.missing_input_paths
      );
      RETURN NEXT;
      CONTINUE;
    END IF;

    v_ok := true;
    FOR v_condition IN SELECT * FROM jsonb_array_elements(v_rule.conditions)
    LOOP
      v_module := v_condition->>'module';
      v_field := v_condition->>'field';
      v_op := v_condition->>'op';
      v_value := v_condition->'value';
      v_needed := '{}';

      IF v_module = 'medical' AND v_field IN ('medications[].drug_class', 'medications[].cyp_profile') THEN
        IF v_op = 'contains' THEN
          v_ok := v_ok AND (v_value #>> '{}' = ANY(v_med_traits));
        ELSIF v_op = 'contains_any' THEN
          SELECT COALESCE(array_agg(elem), '{}') INTO v_needed FROM jsonb_array_elements_text(v_value) elem;
          v_ok := v_ok AND (v_med_traits && v_needed);
        ELSE
          v_ok := false;
        END IF;
      ELSIF v_module = 'medical' AND v_field = 'medications' THEN
        IF v_op = 'contains_cyp_substrate' THEN
          v_ok := v_ok AND ((v_value->>'enzyme') || '_substrate' = ANY(v_med_traits));
        ELSIF v_op = 'contains_cyp_inducer' THEN
          v_ok := v_ok AND ((v_value->>'enzyme') || '_inducer' = ANY(v_med_traits));
        ELSIF v_op = 'contains_cyp_inhibitor' THEN
          v_ok := v_ok AND ((v_value->>'enzyme') || '_inhibitor' = ANY(v_med_traits));
        ELSIF v_op = 'contains_medication' THEN
          v_ok := v_ok AND lower(v_value #>> '{}') = ANY(v_med_names);
        ELSIF v_op = 'contains_any_class' THEN
          SELECT COALESCE(array_agg(elem), '{}') INTO v_needed
          FROM jsonb_array_elements(v_value) outer_arr,
               jsonb_array_elements_text(outer_arr) elem;
          v_ok := v_ok AND (v_med_traits && v_needed);
        ELSIF v_op = 'count_risk_flag_gte' THEN
          SELECT count(*) INTO v_count FROM unnest(v_med_risk_flags) f WHERE f = v_value->>'flag';
          v_ok := v_ok AND v_count >= COALESCE((v_value->>'count')::integer, 1);
        ELSE
          v_ok := false;
        END IF;
      ELSIF v_module = 'supplements' AND v_field = 'stack' THEN
        IF v_op IN ('contains_any_substance', 'contains_any_group') THEN
          v_ok := v_ok AND (v_stack_substances && v_rule.substance_ids);
        ELSIF v_op = 'count_group_gte' THEN
          SELECT count(*) INTO v_count FROM unnest(v_stack_substances) s WHERE s = ANY(v_rule.substance_ids);
          v_ok := v_ok AND v_count >= COALESCE((v_value->>'count')::integer, 1);
        ELSE
          v_ok := false;
        END IF;
      ELSIF v_module = 'supplements' AND v_field = 'daily_total_mg' THEN
        v_ok := false;
      ELSIF v_module = 'medical' AND v_field = 'conditions' AND v_op = 'contains_any' THEN
        SELECT COALESCE(array_agg(elem), '{}') INTO v_needed FROM jsonb_array_elements_text(v_value) elem;
        v_ok := v_ok AND (v_conditions && v_needed);
      ELSIF v_module = 'medical' AND v_field = 'labs' AND v_op = 'missing_analyte_within_months' THEN
        v_ok := v_ok AND NOT EXISTS (
          SELECT 1 FROM unnest(v_lab_names) n WHERE n LIKE '%' || lower(v_value->>'analyte') || '%'
        );
      ELSIF v_module = 'medical' AND v_field = 'labs[].analyte' THEN
        IF v_op = 'contains_any' THEN
          SELECT COALESCE(array_agg(lower(elem)), '{}') INTO v_needed FROM jsonb_array_elements_text(v_value) elem;
          v_ok := v_ok AND EXISTS (
            SELECT 1 FROM unnest(v_lab_names) n JOIN unnest(v_needed) w ON n LIKE '%' || w || '%'
          );
        ELSE
          v_ok := false;
        END IF;
      ELSIF v_field = '(see gap_condition)' THEN
        IF v_rule.rule_id = 'gap_protein_training' THEN
          v_ok := v_ok AND COALESCE(v_protein_per_kg < 1.2 AND v_training_week >= 2, false);
        ELSIF v_rule.rule_id = 'gap_magnesium_intake' THEN
          v_ok := v_ok AND COALESCE(v_mg_pct < 80, false);
        ELSIF v_rule.rule_id = 'gap_folate_pregnancy_plan' THEN
          v_ok := v_ok AND EXISTS (
            SELECT 1
            FROM jsonb_to_recordset(v_input_status) AS s(
              input_path text,
              input_status text,
              missing_reason text,
              detail jsonb
            )
            WHERE input_path = 'profile.pregnancy_planned'
              AND detail->>'pregnancy_planned' = 'true'
          );
        ELSE
          v_ok := false;
        END IF;
      ELSE
        v_ok := false;
      END IF;
    END LOOP;

    rule_id := v_rule.rule_id;
    rule_type := v_rule.rule_type;
    message_key := v_rule.message_key;
    message_de := v_rule.message_de;
    severity := v_rule.severity;
    recommended_action_type := CASE
      WHEN v_rule.rule_type = 'nutrient_gap' THEN COALESCE(v_rule.recommended_action_type, 'information')
      ELSE COALESCE(v_rule.recommended_action_type, 'physician_referral')
    END;
    evaluation_state := CASE WHEN v_ok THEN 'fulfilled' ELSE 'not_fulfilled' END;
    missing_inputs := '{}';
    matched_context := jsonb_build_object(
      'medication_traits', v_med_traits,
      'stack_substances', v_stack_substances,
      'conditions', v_conditions,
      'protein_g_per_kg', v_protein_per_kg,
      'resistance_sessions_7d', v_training_week,
      'rule_substance_ids', v_rule.substance_ids
    );
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION supplements.rule_assessment(p_user_id uuid, p_entry_date date) OWNER TO postgres;

--
-- Name: FUNCTION rule_assessment(p_user_id uuid, p_entry_date date); Type: COMMENT; Schema: supplements; Owner: postgres
--

COMMENT ON FUNCTION supplements.rule_assessment(p_user_id uuid, p_entry_date date) IS 'C-133: Nutzerbezogene dreistufige Regelauswertung: fulfilled, not_fulfilled, missing_input. SECURITY INVOKER und auth.uid-Schutz.';


--
-- Name: supplement_nutrient_intake_for_day(uuid, date); Type: FUNCTION; Schema: supplements; Owner: postgres
--

CREATE FUNCTION supplements.supplement_nutrient_intake_for_day(p_user_id uuid, p_entry_date date DEFAULT CURRENT_DATE) RETURNS TABLE(user_id uuid, intake_date date, nutrient_code text, nutrient_unit text, total_amount numeric, taken_log_count integer, skipped_log_count integer, mapped_taken_log_count integer, unmapped_taken_log_count integer)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH logs AS (
    SELECT
      il.user_id,
      il.intake_date,
      il.status,
      COALESCE(il.actual_dose, il.dose_snapshot) AS dose_amount,
      COALESCE(il.actual_dose_unit, il.dose_unit_snapshot) AS dose_unit,
      si.supplement_id,
      c.serving_size,
      c.serving_unit
    FROM supplements.intake_logs il
    JOIN supplements.stack_items si ON si.id = il.stack_item_id
    JOIN supplements.supplement_catalog c ON c.id = si.supplement_id
    WHERE il.user_id = p_user_id
      AND il.intake_date = p_entry_date
  ),
  taken AS (
    SELECT *
    FROM logs
    WHERE status = 'taken'
  ),
  mapped AS (
    SELECT
      t.user_id,
      t.intake_date,
      m.nutrient_code,
      m.nutrient_unit,
      (t.dose_amount / NULLIF(t.serving_size, 0)) * m.amount_nutrient_unit AS amount
    FROM taken t
    JOIN supplements.supplement_nutrient_mappings m ON m.supplement_id = t.supplement_id
    WHERE t.dose_unit = t.serving_unit
      AND t.serving_size IS NOT NULL
      AND t.dose_amount IS NOT NULL
  ),
  counts AS (
    SELECT
      count(*) FILTER (WHERE status = 'taken')::integer AS taken_count,
      count(*) FILTER (WHERE status = 'skipped')::integer AS skipped_count,
      count(*) FILTER (WHERE status = 'taken' AND EXISTS (
        SELECT 1 FROM supplements.supplement_nutrient_mappings m
        WHERE m.supplement_id = logs.supplement_id
      ))::integer AS mapped_taken_count,
      count(*) FILTER (WHERE status = 'taken' AND NOT EXISTS (
        SELECT 1 FROM supplements.supplement_nutrient_mappings m
        WHERE m.supplement_id = logs.supplement_id
      ))::integer AS unmapped_taken_count
    FROM logs
  )
  SELECT
    p_user_id,
    p_entry_date,
    m.nutrient_code,
    m.nutrient_unit,
    sum(m.amount) AS total_amount,
    c.taken_count,
    c.skipped_count,
    c.mapped_taken_count,
    c.unmapped_taken_count
  FROM mapped m
  CROSS JOIN counts c
  GROUP BY m.nutrient_code, m.nutrient_unit, c.taken_count, c.skipped_count,
           c.mapped_taken_count, c.unmapped_taken_count
  ORDER BY m.nutrient_code;
$$;


ALTER FUNCTION supplements.supplement_nutrient_intake_for_day(p_user_id uuid, p_entry_date date) OWNER TO postgres;

