    undone_by uuid,
    CONSTRAINT action_log_module_check CHECK ((module = ANY (ARRAY['nutrition'::text, 'training'::text, 'recovery'::text, 'goals'::text, 'supplements'::text, 'medical'::text, 'buddy'::text])))
);


ALTER TABLE coach.action_log OWNER TO postgres;

