--
-- Name: alerts; Type: TABLE; Schema: coach; Owner: postgres
--

CREATE TABLE coach.alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coach_id uuid NOT NULL,
    client_id uuid NOT NULL,
    module text NOT NULL,
    title text NOT NULL,
    detail text,
    metric jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    read_at timestamp with time zone,
    done_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT alerts_done_ck CHECK (((status <> 'done'::text) OR (done_at IS NOT NULL))),
    CONSTRAINT alerts_metric_check CHECK ((jsonb_typeof(metric) = 'object'::text)),
    CONSTRAINT alerts_module_check CHECK ((module = ANY (ARRAY['nutrition'::text, 'training'::text, 'recovery'::text, 'goals'::text, 'supplements'::text, 'medical'::text, 'buddy'::text, 'general'::text]))),
    CONSTRAINT alerts_not_self_ck CHECK ((coach_id <> client_id)),
    CONSTRAINT alerts_status_check CHECK ((status = ANY (ARRAY['open'::text, 'read'::text, 'done'::text])))
);


ALTER TABLE coach.alerts OWNER TO postgres;

--
-- Name: TABLE alerts; Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON TABLE coach.alerts IS 'Arbeitsliste des Coaches: Sachverhalt plus Zahlen (metric), bewusst ohne Schweregrad und ohne Ampel — Dringlichkeitsstufen sind T7 (offen).';


