--
-- Name: checkins; Type: TABLE; Schema: coach; Owner: postgres
--

CREATE TABLE coach.checkins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coach_id uuid NOT NULL,
    client_id uuid NOT NULL,
    template_id uuid,
    due_date date NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    auto_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    client_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    client_note text,
    coach_feedback text,
    coach_notes text,
    submitted_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    changed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT checkins_auto_data_check CHECK ((jsonb_typeof(auto_data) = 'object'::text)),
    CONSTRAINT checkins_client_data_check CHECK ((jsonb_typeof(client_data) = 'object'::text)),
    CONSTRAINT checkins_not_self_ck CHECK ((coach_id <> client_id)),
    CONSTRAINT checkins_reviewed_ck CHECK (((status <> 'reviewed'::text) OR (reviewed_at IS NOT NULL))),
    CONSTRAINT checkins_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'submitted'::text, 'reviewed'::text, 'missed'::text]))),
    CONSTRAINT checkins_submitted_ck CHECK (((status <> ALL (ARRAY['submitted'::text, 'reviewed'::text])) OR (submitted_at IS NOT NULL)))
);


ALTER TABLE coach.checkins OWNER TO postgres;

--
-- Name: TABLE checkins; Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON TABLE coach.checkins IS 'Check-in-Instanz: pending -> submitted -> reviewed (oder missed). Keine persistierte Analyse — die Vorauswertung rechnet die Anwendung beim Lesen.';


--
-- Name: COLUMN checkins.coach_feedback; Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON COLUMN coach.checkins.coach_feedback IS 'Antwort an den Klienten. coach_notes bleibt intern — zwei Felder, ein Unterschied.';


--
-- Name: client_autonomy; Type: TABLE; Schema: coach; Owner: postgres
--

CREATE TABLE coach.client_autonomy (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coach_id uuid NOT NULL,
    client_id uuid NOT NULL,
    nutrition_level smallint DEFAULT 2 NOT NULL,
    training_level smallint DEFAULT 2 NOT NULL,
    recovery_level smallint DEFAULT 2 NOT NULL,
    goals_level smallint DEFAULT 2 NOT NULL,
    supplements_level smallint DEFAULT 2 NOT NULL,
    medical_level smallint DEFAULT 2 NOT NULL,
    buddy_level smallint DEFAULT 2 NOT NULL,
    safety_level smallint DEFAULT 1 NOT NULL,
    coach_note text,
    changed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_autonomy_levels_ck CHECK ((((nutrition_level >= 1) AND (nutrition_level <= 5)) AND ((training_level >= 1) AND (training_level <= 5)) AND ((recovery_level >= 1) AND (recovery_level <= 5)) AND ((goals_level >= 1) AND (goals_level <= 5)) AND ((supplements_level >= 1) AND (supplements_level <= 5)) AND ((medical_level >= 1) AND (medical_level <= 5)) AND ((buddy_level >= 1) AND (buddy_level <= 5)) AND ((safety_level >= 1) AND (safety_level <= 3)))),
    CONSTRAINT client_autonomy_not_self_ck CHECK ((coach_id <> client_id))
);


ALTER TABLE coach.client_autonomy OWNER TO postgres;

--
-- Name: TABLE client_autonomy; Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON TABLE coach.client_autonomy IS 'Vom Coach gesetzter Autonomy-Level des Athleten je Modul. Speichert Reifegrad, keine Coach-Rechte.';


--
-- Name: client_permissions; Type: TABLE; Schema: coach; Owner: postgres
--

CREATE TABLE coach.client_permissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coach_id uuid NOT NULL,
    client_id uuid NOT NULL,
    nutrition_visibility text DEFAULT 'none'::text NOT NULL,
    training_visibility text DEFAULT 'none'::text NOT NULL,
    recovery_visibility text DEFAULT 'none'::text NOT NULL,
    goals_visibility text DEFAULT 'none'::text NOT NULL,
    supplements_visibility text DEFAULT 'none'::text NOT NULL,
    medical_visibility text DEFAULT 'none'::text NOT NULL,
    buddy_visibility text DEFAULT 'none'::text NOT NULL,
    nutrition_auto_apply boolean DEFAULT false NOT NULL,
    training_auto_apply boolean DEFAULT false NOT NULL,
    recovery_auto_apply boolean DEFAULT false NOT NULL,
    goals_auto_apply boolean DEFAULT false NOT NULL,
    supplements_auto_apply boolean DEFAULT false NOT NULL,
    medical_auto_apply boolean DEFAULT false NOT NULL,
    buddy_auto_apply boolean DEFAULT false NOT NULL,
    client_note text,
    expires_at timestamp with time zone,
    changed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_permissions_not_self_ck CHECK ((coach_id <> client_id)),
    CONSTRAINT client_permissions_visibility_ck CHECK (((nutrition_visibility = ANY (ARRAY['none'::text, 'summary'::text, 'full'::text])) AND (training_visibility = ANY (ARRAY['none'::text, 'summary'::text, 'full'::text])) AND (recovery_visibility = ANY (ARRAY['none'::text, 'summary'::text, 'full'::text])) AND (goals_visibility = ANY (ARRAY['none'::text, 'summary'::text, 'full'::text])) AND (supplements_visibility = ANY (ARRAY['none'::text, 'summary'::text, 'full'::text])) AND (medical_visibility = ANY (ARRAY['none'::text, 'summary'::text, 'full'::text])) AND (buddy_visibility = ANY (ARRAY['none'::text, 'summary'::text, 'full'::text]))))
);


ALTER TABLE coach.client_permissions OWNER TO postgres;

--
-- Name: TABLE client_permissions; Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON TABLE coach.client_permissions IS 'Vom Klienten gesetzte Coach-Rechte je Modul: Sichtbarkeit und Aenderung ohne Bestaetigung.';


--
-- Name: messages; Type: TABLE; Schema: coach; Owner: postgres
--

CREATE TABLE coach.messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
