    CONSTRAINT messages_body_check CHECK ((length(btrim(body)) > 0)),
    CONSTRAINT messages_not_self_ck CHECK ((coach_id <> client_id)),
    CONSTRAINT messages_sender_ck CHECK (((sender_id = coach_id) OR (sender_id = client_id)))
);


ALTER TABLE coach.messages OWNER TO postgres;

--
-- Name: TABLE messages; Type: COMMENT; Schema: coach; Owner: postgres
--

COMMENT ON TABLE coach.messages IS 'Nachrichten Coach <-> Klient. sender_id ist per CHECK ans Paar gebunden — kein Diskriminator-Raetsel wie im Vorgaenger (N-20).';


--
-- Name: pending_actions; Type: TABLE; Schema: coach; Owner: postgres
--

CREATE TABLE coach.pending_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coach_id uuid NOT NULL,
    client_id uuid NOT NULL,
