    CONSTRAINT pending_actions_module_check CHECK ((module = ANY (ARRAY['nutrition'::text, 'training'::text, 'recovery'::text, 'goals'::text, 'supplements'::text, 'medical'::text, 'buddy'::text]))),
    CONSTRAINT pending_actions_not_self_ck CHECK ((coach_id <> client_id)),
    CONSTRAINT pending_actions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'rejected'::text, 'expired'::text, 'cancelled'::text])))
);


ALTER TABLE coach.pending_actions OWNER TO postgres;

