    chest_cm numeric(5,1),
    upper_arm_left_cm numeric(5,1),
    upper_arm_right_cm numeric(5,1),
    forearm_left_cm numeric(5,1),
    forearm_right_cm numeric(5,1),
    waist_cm numeric(5,1),
    hip_cm numeric(5,1),
    thigh_left_cm numeric(5,1),
    thigh_right_cm numeric(5,1),
    calf_left_cm numeric(5,1),
    calf_right_cm numeric(5,1),
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    measurement_source text DEFAULT 'manual'::text NOT NULL,
    source_detail text,
    CONSTRAINT body_circumferences_at_least_one_ck CHECK (((neck_cm IS NOT NULL) OR (shoulders_cm IS NOT NULL) OR (chest_cm IS NOT NULL) OR (upper_arm_left_cm IS NOT NULL) OR (upper_arm_right_cm IS NOT NULL) OR (forearm_left_cm IS NOT NULL) OR (forearm_right_cm IS NOT NULL) OR (waist_cm IS NOT NULL) OR (hip_cm IS NOT NULL) OR (thigh_left_cm IS NOT NULL) OR (thigh_right_cm IS NOT NULL) OR (calf_left_cm IS NOT NULL) OR (calf_right_cm IS NOT NULL))),
    CONSTRAINT body_circumferences_positive_ck CHECK ((((neck_cm IS NULL) OR ((neck_cm >= (10)::numeric) AND (neck_cm <= (80)::numeric))) AND ((shoulders_cm IS NULL) OR ((shoulders_cm >= (40)::numeric) AND (shoulders_cm <= (220)::numeric))) AND ((chest_cm IS NULL) OR ((chest_cm >= (40)::numeric) AND (chest_cm <= (220)::numeric))) AND ((upper_arm_left_cm IS NULL) OR ((upper_arm_left_cm >= (10)::numeric) AND (upper_arm_left_cm <= (90)::numeric))) AND ((upper_arm_right_cm IS NULL) OR ((upper_arm_right_cm >= (10)::numeric) AND (upper_arm_right_cm <= (90)::numeric))) AND ((forearm_left_cm IS NULL) OR ((forearm_left_cm >= (10)::numeric) AND (forearm_left_cm <= (70)::numeric))) AND ((forearm_right_cm IS NULL) OR ((forearm_right_cm >= (10)::numeric) AND (forearm_right_cm <= (70)::numeric))) AND ((waist_cm IS NULL) OR ((waist_cm >= (40)::numeric) AND (waist_cm <= (220)::numeric))) AND ((hip_cm IS NULL) OR ((hip_cm >= (40)::numeric) AND (hip_cm <= (220)::numeric))) AND ((thigh_left_cm IS NULL) OR ((thigh_left_cm >= (20)::numeric) AND (thigh_left_cm <= (140)::numeric))) AND ((thigh_right_cm IS NULL) OR ((thigh_right_cm >= (20)::numeric) AND (thigh_right_cm <= (140)::numeric))) AND ((calf_left_cm IS NULL) OR ((calf_left_cm >= (10)::numeric) AND (calf_left_cm <= (90)::numeric))) AND ((calf_right_cm IS NULL) OR ((calf_right_cm >= (10)::numeric) AND (calf_right_cm <= (90)::numeric))))),
    CONSTRAINT body_circumferences_source_ck CHECK ((measurement_source = ANY (ARRAY['manual'::text, 'device'::text, 'import'::text, 'admin'::text])))
);


