--
-- Name: body_measurements; Type: TABLE; Schema: goals; Owner: postgres
--

CREATE TABLE goals.body_measurements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    measurement_date date NOT NULL,
    measurement_time time without time zone NOT NULL,
    weight_kg numeric(6,2) NOT NULL,
    body_fat_pct numeric(5,2),
    bf_method text,
    height_cm_snapshot numeric(5,1),
    lean_mass_kg numeric(6,2) GENERATED ALWAYS AS (
CASE
    WHEN (body_fat_pct IS NULL) THEN NULL::numeric
    ELSE round((weight_kg * ((1)::numeric - (body_fat_pct / (100)::numeric))), 2)
END) STORED,
    fat_mass_kg numeric(6,2) GENERATED ALWAYS AS (
CASE
    WHEN (body_fat_pct IS NULL) THEN NULL::numeric
    ELSE round(((weight_kg * body_fat_pct) / (100)::numeric), 2)
END) STORED,
    bmi numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (height_cm_snapshot IS NULL) THEN NULL::numeric
    ELSE round((weight_kg / ((height_cm_snapshot / 100.0) * (height_cm_snapshot / 100.0))), 2)
END) STORED,
    ffmi numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN ((body_fat_pct IS NULL) OR (height_cm_snapshot IS NULL)) THEN NULL::numeric
    ELSE round((((weight_kg * ((1)::numeric - (body_fat_pct / (100)::numeric))) / ((height_cm_snapshot / 100.0) * (height_cm_snapshot / 100.0))) + (6.1 * (1.8 - (height_cm_snapshot / 100.0)))), 2)
END) STORED,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    measurement_source text DEFAULT 'manual'::text NOT NULL,
    source_detail text,
    CONSTRAINT body_measurements_body_fat_ck CHECK (((body_fat_pct IS NULL) OR ((body_fat_pct >= (2)::numeric) AND (body_fat_pct <= (70)::numeric)))),
    CONSTRAINT body_measurements_height_ck CHECK (((height_cm_snapshot IS NULL) OR ((height_cm_snapshot >= (80)::numeric) AND (height_cm_snapshot <= (250)::numeric)))),
    CONSTRAINT body_measurements_method_ck CHECK (((bf_method IS NULL) OR (bf_method = ANY (ARRAY['caliper_3'::text, 'caliper_7'::text, 'dexa'::text, 'bia'::text, 'visual'::text, 'hydrostatic'::text, 'navy'::text, 'durnin'::text, 'jackson_pollock'::text, 'manual'::text])))),
    CONSTRAINT body_measurements_source_ck CHECK ((measurement_source = ANY (ARRAY['manual'::text, 'device'::text, 'import'::text, 'admin'::text]))),
    CONSTRAINT body_measurements_weight_ck CHECK (((weight_kg >= (20)::numeric) AND (weight_kg <= (400)::numeric)))
);


