--
-- Name: daily_nutrient_summary_long; Type: VIEW; Schema: nutrition; Owner: postgres
--

CREATE VIEW nutrition.daily_nutrient_summary_long WITH (security_invoker='true') AS
 WITH day_base AS (
         SELECT m.user_id,
            m.entry_date,
            (count(DISTINCT m.id))::integer AS meal_count,
            (count(mi.id))::integer AS item_count
           FROM (nutrition.meals m
             LEFT JOIN nutrition.meal_items mi ON ((mi.meal_id = m.id)))
          GROUP BY m.user_id, m.entry_date
        ), item_base AS (
         SELECT m.user_id,
            m.entry_date,
            mi.id AS item_id,
            mi.enercc,
            mi.prot625,
            mi.fat,
            mi.cho,
            mi.fibt,
            mi.sugar,
            mi.fasat,
            mi.nacl,
            mi.water_g,
            mi.nutrients
           FROM (nutrition.meals m
             JOIN nutrition.meal_items mi ON ((mi.meal_id = m.id)))
        ), item_values AS (
         SELECT ib.user_id,
            ib.entry_date,
            ib.item_id,
            v.nutrient_code,
            v.value
           FROM (item_base ib
             CROSS JOIN LATERAL ( VALUES ('ENERCC'::text,ib.enercc), ('PROT625'::text,ib.prot625), ('FAT'::text,ib.fat), ('CHO'::text,ib.cho), ('FIBT'::text,ib.fibt), ('SUGAR'::text,ib.sugar), ('FASAT'::text,ib.fasat), ('NACL'::text,ib.nacl), ('WATER'::text,ib.water_g)) v(nutrient_code, value))
          WHERE (v.value IS NOT NULL)
        UNION ALL
         SELECT ib.user_id,
            ib.entry_date,
            ib.item_id,
            kv.key AS nutrient_code,
            (kv.value)::numeric AS value
           FROM (item_base ib
             CROSS JOIN LATERAL jsonb_each_text(ib.nutrients) kv(key, value))
          WHERE ((kv.key <> ALL (ARRAY['ENERCC'::text, 'PROT625'::text, 'FAT'::text, 'CHO'::text, 'FIBT'::text, 'SUGAR'::text, 'FASAT'::text, 'NACL'::text, 'WATER'::text])) AND (kv.value ~ '^-?[0-9]+([.][0-9]+)?$'::text))
        ), agg AS (
         SELECT item_values.user_id,
            item_values.entry_date,
            item_values.nutrient_code,
            (count(*))::integer AS value_count,
            sum(item_values.value) AS total_value
           FROM item_values
          GROUP BY item_values.user_id, item_values.entry_date, item_values.nutrient_code
        )
 SELECT db.user_id,
    db.entry_date,
    nd.code AS nutrient_code,
    nd.name_de AS nutrient_name_de,
    nd.unit AS nutrient_unit,
    nd.group_de,
    nd.display_tier,
    nd.sort_index,
    db.meal_count,
    db.item_count,
    COALESCE(a.value_count, 0) AS value_count,
    (db.item_count - COALESCE(a.value_count, 0)) AS missing_count,
    a.total_value,
    ((db.item_count > 0) AND (db.item_count = COALESCE(a.value_count, 0))) AS value_complete
   FROM ((day_base db
     CROSS JOIN nutrition.nutrient_defs nd)
     LEFT JOIN agg a ON (((a.user_id = db.user_id) AND (a.entry_date = db.entry_date) AND (a.nutrient_code = nd.code))));


ALTER VIEW nutrition.daily_nutrient_summary_long OWNER TO postgres;

--
-- Name: VIEW daily_nutrient_summary_long; Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON VIEW nutrition.daily_nutrient_summary_long IS 'C-157: Lange Tagesbilanz fuer alle 138 nutrient_defs. Eine Zeile je Nutzer, Tag und Naehrstoff; total_value plus value_count/missing_count statt breiter Spaltenpaare. Liest eingefrorene meal_items-Spalten fuer Schnellmakros und mi.nutrients fuer alle weiteren Codes. security_invoker=true, damit RLS von meals/meal_items greift. Keine Bewertung.';


--
-- Name: daily_summary; Type: VIEW; Schema: nutrition; Owner: postgres
--

CREATE VIEW nutrition.daily_summary WITH (security_invoker='true') AS
 SELECT m.user_id,
    m.entry_date,
    count(DISTINCT m.id) AS meal_count,
    count(mi.id) AS item_count,
    sum(mi.enercc) AS enercc,
    sum(mi.prot625) AS prot625,
    sum(mi.fat) AS fat,
    sum(mi.cho) AS cho,
    sum(mi.fibt) AS fibt,
    sum(mi.sugar) AS sugar,
    sum(mi.fasat) AS fasat,
    sum(mi.nacl) AS nacl,
    sum(mi.water_g) AS water_g,
    (count(mi.id) - count(mi.enercc)) AS enercc_missing,
    (count(mi.id) - count(mi.prot625)) AS prot625_missing,
    (count(mi.id) - count(mi.fat)) AS fat_missing,
    (count(mi.id) - count(mi.cho)) AS cho_missing,
    (count(mi.id) - count(mi.fibt)) AS fibt_missing,
    (count(mi.id) - count(mi.sugar)) AS sugar_missing,
    (count(mi.id) - count(mi.fasat)) AS fasat_missing,
    (count(mi.id) - count(mi.nacl)) AS nacl_missing,
    (count(mi.id) - count(mi.water_g)) AS water_g_missing,
    sum(((mi.nutrients ->> 'VITA'::text))::numeric) AS vita,
    sum(((mi.nutrients ->> 'VITD'::text))::numeric) AS vitd,
    sum(((mi.nutrients ->> 'VITE'::text))::numeric) AS vite,
    sum(((mi.nutrients ->> 'VITK'::text))::numeric) AS vitk,
    sum(((mi.nutrients ->> 'THIA'::text))::numeric) AS thia,
    sum(((mi.nutrients ->> 'RIBF'::text))::numeric) AS ribf,
    sum(((mi.nutrients ->> 'NIA'::text))::numeric) AS nia,
    sum(((mi.nutrients ->> 'VITB6'::text))::numeric) AS vitb6,
    sum(((mi.nutrients ->> 'FOL'::text))::numeric) AS fol,
    sum(((mi.nutrients ->> 'VITB12'::text))::numeric) AS vitb12,
    sum(((mi.nutrients ->> 'VITC'::text))::numeric) AS vitc,
    sum(((mi.nutrients ->> 'NA'::text))::numeric) AS na,
    sum(((mi.nutrients ->> 'K'::text))::numeric) AS k,
    sum(((mi.nutrients ->> 'CA'::text))::numeric) AS ca,
    sum(((mi.nutrients ->> 'MG'::text))::numeric) AS mg,
    sum(((mi.nutrients ->> 'P'::text))::numeric) AS p,
    sum(((mi.nutrients ->> 'FE'::text))::numeric) AS fe,
    sum(((mi.nutrients ->> 'ZN'::text))::numeric) AS zn,
    sum(((mi.nutrients ->> 'ID'::text))::numeric) AS iodid,
    sum(((mi.nutrients ->> 'CHORL'::text))::numeric) AS chorl,
    sum(((mi.nutrients ->> 'FAPUN3'::text))::numeric) AS fapun3,
    sum(((mi.nutrients ->> 'FAPUN6'::text))::numeric) AS fapun6,
    sum(((mi.nutrients ->> 'AAE9'::text))::numeric) AS aae9,
    sum(((mi.nutrients ->> 'LEU'::text))::numeric) AS leu,
    (count(mi.id) - count(((mi.nutrients ->> 'VITA'::text))::numeric)) AS vita_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'VITD'::text))::numeric)) AS vitd_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'VITE'::text))::numeric)) AS vite_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'VITK'::text))::numeric)) AS vitk_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'THIA'::text))::numeric)) AS thia_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'RIBF'::text))::numeric)) AS ribf_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'NIA'::text))::numeric)) AS nia_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'VITB6'::text))::numeric)) AS vitb6_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'FOL'::text))::numeric)) AS fol_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'VITB12'::text))::numeric)) AS vitb12_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'VITC'::text))::numeric)) AS vitc_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'NA'::text))::numeric)) AS na_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'K'::text))::numeric)) AS k_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'CA'::text))::numeric)) AS ca_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'MG'::text))::numeric)) AS mg_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'P'::text))::numeric)) AS p_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'FE'::text))::numeric)) AS fe_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'ZN'::text))::numeric)) AS zn_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'ID'::text))::numeric)) AS iodid_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'CHORL'::text))::numeric)) AS chorl_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'FAPUN3'::text))::numeric)) AS fapun3_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'FAPUN6'::text))::numeric)) AS fapun6_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'AAE9'::text))::numeric)) AS aae9_missing,
    (count(mi.id) - count(((mi.nutrients ->> 'LEU'::text))::numeric)) AS leu_missing,
    sum(((mi.nutrients ->> 'F18:2CN6'::text))::numeric) AS f18_2cn6,
    (count(mi.id) - count(((mi.nutrients ->> 'F18:2CN6'::text))::numeric)) AS f18_2cn6_missing,
    sum(((mi.nutrients ->> 'F18:3CN3'::text))::numeric) AS f18_3cn3,
    (count(mi.id) - count(((mi.nutrients ->> 'F18:3CN3'::text))::numeric)) AS f18_3cn3_missing
   FROM (nutrition.meals m
     LEFT JOIN nutrition.meal_items mi ON ((mi.meal_id = m.id)))
  GROUP BY m.user_id, m.entry_date;


ALTER VIEW nutrition.daily_summary OWNER TO postgres;

--
-- Name: VIEW daily_summary; Type: COMMENT; Schema: nutrition; Owner: postgres
--

COMMENT ON VIEW nutrition.daily_summary IS 'Tagessummen aus den eingefrorenen Werten in meal_items (C-04, 2026-08-06; Mikros ergaenzt C-37, 2026-08-15). security_invoker=true, damit die RLS-Policies von meals/meal_items greifen. Je Wert zusaetzlich <wert>_missing: Zahl der Positionen ohne Wert ??? ist sie > 0, ist die Summe eine Untergrenze. Neun Makros aus den Spalten, 24 Mikros aus dem JSONB-Schnappschuss mi.nutrients, plus C-53: Linolsaeure und Alpha-Linolensaeure. Diese Sicht SUMMIERT und BEWERTET NICHT: sie fuehrt keine Referenz- oder Tageswerte und sagt nicht, ob eine Menge ausreicht.';


