--
-- Name: exclusion_preset_matches; Type: VIEW; Schema: nutrition; Owner: postgres
--

CREATE VIEW nutrition.exclusion_preset_matches WITH (security_invoker='true') AS
 WITH RECURSIVE kategorie_baum AS (
         SELECT r.preset_code,
            c.id AS category_id
           FROM (nutrition.exclusion_preset_rules r
             JOIN nutrition.food_categories c ON ((c.slug = r.rule_value)))
          WHERE (r.rule_kind = 'category'::text)
        UNION ALL
         SELECT b.preset_code,
            c.id
           FROM (kategorie_baum b
             JOIN nutrition.food_categories c ON ((c.parent_id = b.category_id)))
        ), treffer AS (
         SELECT DISTINCT b.preset_code,
            f.id AS food_id,
            'category'::text AS via
           FROM (kategorie_baum b
             JOIN nutrition.foods f ON ((f.category_id = b.category_id)))
        UNION
         SELECT DISTINCT r.preset_code,
            f.id,
            'bls_prefix'::text
           FROM (nutrition.exclusion_preset_rules r
             JOIN nutrition.foods f ON (("substring"(f.bls_code, 1, length(r.rule_value)) = r.rule_value)))
          WHERE (r.rule_kind = 'bls_prefix'::text)
        UNION
         SELECT DISTINCT r.preset_code,
            f.id,
            'name'::text
           FROM (nutrition.exclusion_preset_rules r
             JOIN nutrition.foods f ON ((f.name_de ~* r.rule_value)))
          WHERE (r.rule_kind = 'name'::text)
        UNION
         SELECT DISTINCT r.preset_code,
            f.id,
            'raw_animal'::text
           FROM (nutrition.exclusion_preset_rules r
             JOIN nutrition.foods f ON (((f.processing_level = 'raw'::text) AND (POSITION(("substring"(f.bls_code, 1, 1)) IN (r.rule_value)) > 0))))
          WHERE (r.rule_kind = 'raw_animal'::text)
        )
 SELECT preset_code,
    food_id,
    min(via) AS via
   FROM treffer t
  WHERE (NOT (EXISTS ( SELECT 1
           FROM (nutrition.exclusion_preset_rules r
             JOIN nutrition.foods f ON ((f.id = t.food_id)))
          WHERE ((r.rule_kind = 'name_not'::text) AND (r.preset_code = t.preset_code) AND (f.name_de ~* r.rule_value)))))
  GROUP BY preset_code, food_id;


