-- Name: meal_plan_entries; Type: TABLE; Schema: nutrition; Owner: postgres
--

CREATE TABLE nutrition.meal_plan_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    day_id uuid NOT NULL,
    user_id uuid NOT NULL,
    meal_type text NOT NULL,
    planned_time time without time zone,
    slot_order integer DEFAULT 0 NOT NULL,
    entry_type text NOT NULL,
    recipe_id uuid,
    food_id uuid,
    custom_food_id uuid,
    amount_g numeric(10,2),
    planned_servings numeric(8,3),
    portion_name text,
    portion_quantity numeric(10,3),
    portion_amount_g numeric(10,2),
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT meal_plan_entries_amount_g_check CHECK (((amount_g IS NULL) OR (amount_g > (0)::numeric))),
    CONSTRAINT meal_plan_entries_entry_type_check CHECK ((entry_type = ANY (ARRAY['recipe'::text, 'bls'::text, 'custom'::text]))),
    CONSTRAINT meal_plan_entries_meal_type_check CHECK ((meal_type = ANY (ARRAY['breakfast'::text, 'lunch'::text, 'dinner'::text, 'snack'::text, 'pre_workout'::text, 'post_workout'::text, 'other'::text]))),
    CONSTRAINT meal_plan_entries_planned_servings_check CHECK (((planned_servings IS NULL) OR (planned_servings > (0)::numeric))),
    CONSTRAINT meal_plan_entries_portion_check CHECK ((((portion_name IS NULL) AND (portion_quantity IS NULL) AND (portion_amount_g IS NULL)) OR ((entry_type = ANY (ARRAY['bls'::text, 'custom'::text])) AND (portion_name IS NOT NULL) AND (length(TRIM(BOTH FROM portion_name)) > 0) AND (portion_quantity IS NOT NULL) AND (portion_quantity > (0)::numeric) AND (portion_amount_g IS NOT NULL) AND (portion_amount_g > (0)::numeric) AND (amount_g IS NOT NULL) AND (abs((amount_g - (portion_quantity * portion_amount_g))) <= 0.01)))),
    CONSTRAINT meal_plan_entries_slot_order_check CHECK ((slot_order >= 0)),
    CONSTRAINT meal_plan_entries_target_check CHECK ((((entry_type = 'recipe'::text) AND (recipe_id IS NOT NULL) AND (food_id IS NULL) AND (custom_food_id IS NULL) AND (planned_servings IS NOT NULL) AND (amount_g IS NULL)) OR ((entry_type = 'bls'::text) AND (recipe_id IS NULL) AND (food_id IS NOT NULL) AND (custom_food_id IS NULL) AND (amount_g IS NOT NULL) AND (planned_servings IS NULL)) OR ((entry_type = 'custom'::text) AND (recipe_id IS NULL) AND (food_id IS NULL) AND (custom_food_id IS NOT NULL) AND (amount_g IS NOT NULL) AND (planned_servings IS NULL))))
);


