-- Name: nutrient_search_aliases; Type: VIEW; Schema: nutrition; Owner: postgres
--

CREATE VIEW nutrition.nutrient_search_aliases WITH (security_invoker='true') AS
 SELECT nutrient_code,
    array_agg(alias_folded ORDER BY alias_folded) AS aliases_folded,
    string_agg(alias_folded, ' '::text ORDER BY alias_folded) AS alias_text
   FROM nutrition.nutrient_aliases
  GROUP BY nutrient_code;


