    macro_rule jsonb,
    CONSTRAINT tag_definitions_tag_type_check CHECK ((tag_type = ANY (ARRAY['ingredient'::text, 'diet'::text, 'allergen'::text, 'fitness'::text, 'gym'::text, 'processing'::text])))
);


ALTER TABLE nutrition.tag_definitions OWNER TO postgres;

--
-- Name: profiles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    birth_date date,
    biological_sex text,
    height_cm numeric(5,2),
    body_weight_kg numeric(6,3),
    activity_level text,
    nutrition_goal text,
    pregnancy_started_on date,
    pregnancy_ended_on date,
    lactation_started_on date,
    lactation_ended_on date,
    locale text,
    experience_level text,
    CONSTRAINT profiles_activity_level_check CHECK (((activity_level IS NULL) OR (activity_level = ANY (ARRAY['sedentary'::text, 'light'::text, 'moderate'::text, 'active'::text, 'very_active'::text])))),
    CONSTRAINT profiles_biological_sex_check CHECK (((biological_sex IS NULL) OR (biological_sex = ANY (ARRAY['male'::text, 'female'::text])))),
    CONSTRAINT profiles_birth_date_check CHECK (((birth_date IS NULL) OR ((birth_date >= '1900-01-01'::date) AND (birth_date <= CURRENT_DATE)))),
    CONSTRAINT profiles_body_weight_kg_check CHECK (((body_weight_kg IS NULL) OR ((body_weight_kg >= (20)::numeric) AND (body_weight_kg <= (400)::numeric)))),
    CONSTRAINT profiles_experience_level_check CHECK (((experience_level IS NULL) OR (experience_level = ANY (ARRAY['beginner'::text, 'advanced'::text, 'pro'::text, 'elite'::text])))),
    CONSTRAINT profiles_height_cm_check CHECK (((height_cm IS NULL) OR ((height_cm >= (80)::numeric) AND (height_cm <= (260)::numeric)))),
    CONSTRAINT profiles_lactation_period_check CHECK (((lactation_started_on IS NULL) OR (lactation_ended_on IS NULL) OR (lactation_ended_on >= lactation_started_on))),
    CONSTRAINT profiles_locale_check CHECK (((locale IS NULL) OR (locale = ANY (ARRAY['de'::text, 'en'::text, 'th'::text])))),
    CONSTRAINT profiles_nutrition_goal_check CHECK (((nutrition_goal IS NULL) OR (nutrition_goal = ANY (ARRAY['lose_weight'::text, 'maintain'::text, 'gain_muscle'::text, 'recomposition'::text, 'performance'::text, 'health'::text])))),
    CONSTRAINT profiles_pregnancy_period_check CHECK (((pregnancy_started_on IS NULL) OR (pregnancy_ended_on IS NULL) OR (pregnancy_ended_on >= pregnancy_started_on)))
);


ALTER TABLE public.profiles OWNER TO postgres;

--
-- Name: COLUMN profiles.birth_date; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.birth_date IS 'C-47: Geburtsdatum statt Alter; Alter wird fuer Referenzwerte zum abgefragten Tag berechnet.';


--
-- Name: COLUMN profiles.biological_sex; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.biological_sex IS 'C-47: biologisches Geschlecht male/female fuer Naehrstoff-Referenzwerte. E-07 ist getrennt und betrifft nur Trainingsmedien.';


--
-- Name: COLUMN profiles.height_cm; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.height_cm IS 'C-47: Koerpergroesse fuer spaetere Makro-/TDEE-Berechnung; nullable, weil Profil unvollstaendig sein darf.';


--
-- Name: COLUMN profiles.body_weight_kg; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.body_weight_kg IS 'C-47: aktuelles Koerpergewicht fuer spaetere Makro-/TDEE-Berechnung; Verlauf gehoert in Goals/Measurements.';


--
-- Name: COLUMN profiles.activity_level; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.activity_level IS 'C-47: grobes Aktivitaetsniveau fuer spaetere Makro-/TDEE-Berechnung; konkrete Ziele bleiben bei Goals.';


--
-- Name: COLUMN profiles.nutrition_goal; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.nutrition_goal IS 'C-47: grobe Zielrichtung fuer spaetere Makroberechnung. nutrition_targets bleibt laut Sollliste bei Goals.';


--
-- Name: COLUMN profiles.pregnancy_started_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.pregnancy_started_on IS 'C-47: Schwangerschaft ist ein Zeitraum, kein dauerhaftes Profilmerkmal.';


--
-- Name: COLUMN profiles.pregnancy_ended_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.pregnancy_ended_on IS 'C-47: Ende des Schwangerschaftszeitraums; Zustand wird fuer einen Stichtag berechnet.';


--
-- Name: COLUMN profiles.lactation_started_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.lactation_started_on IS 'C-47: Stillzeit ist ein Zeitraum, kein dauerhaftes Profilmerkmal.';


--
-- Name: COLUMN profiles.lactation_ended_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.lactation_ended_on IS 'C-47: Ende des Stillzeitraums; Zustand wird fuer einen Stichtag berechnet.';


--
-- Name: COLUMN profiles.locale; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.locale IS 'C-63: Gewaehlte Sprache der Person (de/en/th). NULL = noch nicht gefragt; kein Default, damit keine Entscheidung vorgetaeuscht wird.';


--
-- Name: COLUMN profiles.experience_level; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.profiles.experience_level IS 'C-118/C-140: Selbstauskunft zum Trainings-/Erfahrungsgrad beginner/advanced/pro/elite. Nicht activity_level, nicht Coach-Autonomy.';


--
-- Name: user_display_preferences; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_display_preferences (
    user_id uuid NOT NULL,
    preference_key text NOT NULL,
    value jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_display_preferences_key_check CHECK ((preference_key ~ '^[a-z0-9_.:-]{3,120}$'::text)),
    CONSTRAINT user_display_preferences_value_object_check CHECK ((jsonb_typeof(value) = 'object'::text))
);


ALTER TABLE public.user_display_preferences OWNER TO postgres;

--
-- Name: TABLE user_display_preferences; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.user_display_preferences IS 'C-161 Teil D: Allgemeine gespeicherte Anzeigeeinstellungen je Nutzer. Key-Value mit JSONB, nicht nur fuer den Naehrstoffbaum.';


--
-- Name: COLUMN user_display_preferences.preference_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_display_preferences.preference_key IS 'Stabiler Schluessel, z. B. nutrition.nutrient_tree. Keine eigene Spalte je Ansicht.';


--
-- Name: COLUMN user_display_preferences.value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_display_preferences.value IS 'JSONB-Zustand der Ansicht, z. B. offene Knoten, Zeitfenster und Filter. Die Anwendung validiert die konkrete Form je Key.';


