--
-- Name: checkins; Type: TABLE; Schema: recovery; Owner: postgres
--

CREATE TABLE recovery.checkins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    entry_date date NOT NULL,
    checkin_time time without time zone,
    sleep_hours numeric(3,1),
    sleep_quality smallint,
    sleep_start_time time without time zone,
    sleep_end_time time without time zone,
    subjective_feeling smallint,
    mood text DEFAULT 'neutral'::text NOT NULL,
    energy_level smallint,
    motivation smallint,
    soreness jsonb DEFAULT '{}'::jsonb NOT NULL,
    pain_areas text[] DEFAULT '{}'::text[] NOT NULL,
    stress_level smallint,
    work_stress smallint,
    life_stress smallint,
    alcohol_units numeric(3,1),
    caffeine_mg integer,
    screen_time_before_bed integer,
    resting_hr integer,
    hrv_rmssd numeric(6,2),
    spo2_pct numeric(4,1),
    respiratory_rate numeric(4,1),
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    measurement_source text DEFAULT 'manual'::text NOT NULL,
    source_detail text,
    CONSTRAINT checkins_alcohol_units_check CHECK (((alcohol_units IS NULL) OR (alcohol_units >= (0)::numeric))),
    CONSTRAINT checkins_caffeine_mg_check CHECK (((caffeine_mg IS NULL) OR (caffeine_mg >= 0))),
    CONSTRAINT checkins_checkin_time_check CHECK (((checkin_time IS NULL) OR (EXTRACT(second FROM checkin_time) = (0)::numeric))),
    CONSTRAINT checkins_energy_level_check CHECK (((energy_level IS NULL) OR ((energy_level >= 1) AND (energy_level <= 10)))),
    CONSTRAINT checkins_hrv_rmssd_check CHECK (((hrv_rmssd IS NULL) OR (hrv_rmssd >= (0)::numeric))),
    CONSTRAINT checkins_life_stress_check CHECK (((life_stress IS NULL) OR ((life_stress >= 1) AND (life_stress <= 10)))),
    CONSTRAINT checkins_mood_check CHECK ((mood = ANY (ARRAY['motivated'::text, 'good'::text, 'neutral'::text, 'tired'::text, 'sick'::text]))),
    CONSTRAINT checkins_motivation_check CHECK (((motivation IS NULL) OR ((motivation >= 1) AND (motivation <= 10)))),
    CONSTRAINT checkins_respiratory_rate_check CHECK (((respiratory_rate IS NULL) OR (respiratory_rate > (0)::numeric))),
    CONSTRAINT checkins_resting_hr_check CHECK (((resting_hr IS NULL) OR ((resting_hr >= 25) AND (resting_hr <= 240)))),
    CONSTRAINT checkins_screen_time_before_bed_check CHECK (((screen_time_before_bed IS NULL) OR (screen_time_before_bed >= 0))),
    CONSTRAINT checkins_sleep_hours_check CHECK (((sleep_hours IS NULL) OR ((sleep_hours >= (0)::numeric) AND (sleep_hours <= (14)::numeric)))),
    CONSTRAINT checkins_sleep_quality_check CHECK (((sleep_quality IS NULL) OR ((sleep_quality >= 1) AND (sleep_quality <= 10)))),
    CONSTRAINT checkins_soreness_check CHECK ((jsonb_typeof(soreness) = 'object'::text)),
    CONSTRAINT checkins_spo2_pct_check CHECK (((spo2_pct IS NULL) OR ((spo2_pct >= (50)::numeric) AND (spo2_pct <= (100)::numeric)))),
    CONSTRAINT checkins_stress_level_check CHECK (((stress_level IS NULL) OR ((stress_level >= 1) AND (stress_level <= 10)))),
    CONSTRAINT checkins_subjective_feeling_check CHECK (((subjective_feeling IS NULL) OR ((subjective_feeling >= 1) AND (subjective_feeling <= 10)))),
    CONSTRAINT checkins_work_stress_check CHECK (((work_stress IS NULL) OR ((work_stress >= 1) AND (work_stress <= 10)))),
    CONSTRAINT recovery_checkins_measurement_source_ck CHECK ((measurement_source = ANY (ARRAY['manual'::text, 'device'::text, 'import'::text, 'admin'::text, 'seed'::text])))
);


ALTER TABLE recovery.checkins OWNER TO postgres;

--
-- Name: TABLE checkins; Type: COMMENT; Schema: recovery; Owner: postgres
--

COMMENT ON TABLE recovery.checkins IS 'Taeglicher Recovery-Check-in eines Nutzers (C-67). V1: ein Check-in je lokalem entry_date, per Upsert aenderbar.';


--
-- Name: COLUMN checkins.checkin_time; Type: COMMENT; Schema: recovery; Owner: postgres
--

COMMENT ON COLUMN recovery.checkins.checkin_time IS 'Lokale Uhrzeit des Check-ins zum entry_date. Kein DB-Default: die Anwendung setzt die lokale aktuelle Uhrzeit; der Server laeuft in UTC.';


--
-- Name: COLUMN checkins.measurement_source; Type: COMMENT; Schema: recovery; Owner: postgres
--

COMMENT ON COLUMN recovery.checkins.measurement_source IS 'Herkunft des Check-ins. V1 ist manuell; Wearable-Rohdaten brauchen spaeter eigene Tabellen.';


--
-- Name: COLUMN checkins.source_detail; Type: COMMENT; Schema: recovery; Owner: postgres
--

COMMENT ON COLUMN recovery.checkins.source_detail IS 'Optionales Detail zur Herkunft, z. B. Geraet, Importpfad oder App-Version.';


--
-- Name: modality_log; Type: TABLE; Schema: recovery; Owner: postgres
--

CREATE TABLE recovery.modality_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    entry_date date NOT NULL,
    logged_time time without time zone,
    modality_type text NOT NULL,
    duration_min integer,
    detail text,
    immediate_effect smallint,
    next_day_effect smallint,
    bonus_value numeric(4,2) DEFAULT 0 NOT NULL,
    bonus_source text DEFAULT 'pending_c124_e5'::text NOT NULL,
    next_day_score_delta numeric(5,1),
