    measurement_source text DEFAULT 'manual'::text NOT NULL,
    source_detail text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT modality_log_bonus_value_check CHECK (((bonus_value >= (0)::numeric) AND (bonus_value <= (5)::numeric))),
    CONSTRAINT modality_log_duration_min_check CHECK (((duration_min IS NULL) OR (duration_min >= 0))),
    CONSTRAINT modality_log_immediate_effect_check CHECK (((immediate_effect IS NULL) OR ((immediate_effect >= 1) AND (immediate_effect <= 10)))),
    CONSTRAINT modality_log_logged_time_check CHECK (((logged_time IS NULL) OR (EXTRACT(second FROM logged_time) = (0)::numeric))),
    CONSTRAINT modality_log_measurement_source_check CHECK ((measurement_source = ANY (ARRAY['manual'::text, 'device'::text, 'import'::text, 'admin'::text, 'seed'::text]))),
    CONSTRAINT modality_log_modality_type_check CHECK ((modality_type = ANY (ARRAY['sauna'::text, 'cold_plunge'::text, 'contrast_therapy'::text, 'massage'::text, 'foam_rolling'::text, 'stretching'::text, 'yoga'::text, 'meditation'::text, 'breathwork'::text, 'nap'::text, 'active_recovery'::text, 'other'::text]))),
    CONSTRAINT modality_log_next_day_effect_check CHECK (((next_day_effect IS NULL) OR ((next_day_effect >= 1) AND (next_day_effect <= 10))))
);


ALTER TABLE recovery.modality_log OWNER TO postgres;

--
-- Name: TABLE modality_log; Type: COMMENT; Schema: recovery; Owner: postgres
--

COMMENT ON TABLE recovery.modality_log IS 'Recovery-Modalitaetenprotokoll (C-125): Sauna, Massage, Eisbad, Dehnen usw. Bonuswerte warten zentral auf C-124/E5.';


--
-- Name: COLUMN modality_log.next_day_score_delta; Type: COMMENT; Schema: recovery; Owner: postgres
--

COMMENT ON COLUMN recovery.modality_log.next_day_score_delta IS 'Differenz recovery.scores Folgetag minus aktueller Tag. Nur berechenbar, wenn beide Score-Schnappschuesse existieren.';


