--
-- Name: daily_intake_summary; Type: VIEW; Schema: supplements; Owner: postgres
--

CREATE VIEW supplements.daily_intake_summary WITH (security_invoker='true') AS
 SELECT user_id,
    intake_date,
    count(*) AS total_logged,
    count(*) FILTER (WHERE (status = 'taken'::text)) AS total_taken,
    count(*) FILTER (WHERE (status = 'skipped'::text)) AS total_skipped,
    count(*) FILTER (WHERE (status = 'snoozed'::text)) AS total_snoozed,
    count(*) FILTER (WHERE (status = 'planned'::text)) AS total_planned,
        CASE
            WHEN (count(*) FILTER (WHERE (status = ANY (ARRAY['taken'::text, 'skipped'::text]))) > 0) THEN round((((count(*) FILTER (WHERE (status = 'taken'::text)))::numeric / (count(*) FILTER (WHERE (status = ANY (ARRAY['taken'::text, 'skipped'::text]))))::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS compliance_pct
   FROM supplements.intake_logs il
  GROUP BY user_id, intake_date;


