--
-- Name: substance_alias_matches; Type: VIEW; Schema: supplements; Owner: postgres
--

CREATE VIEW supplements.substance_alias_matches WITH (security_invoker='true') AS
 SELECT DISTINCT LEAST(a.catalog, b.catalog) AS catalog_a,
        CASE
            WHEN (a.catalog <= b.catalog) THEN a.entity_id
            ELSE b.entity_id
        END AS entity_id_a,
        CASE
            WHEN (a.catalog <= b.catalog) THEN a.entity_label
            ELSE b.entity_label
        END AS entity_label_a,
    GREATEST(a.catalog, b.catalog) AS catalog_b,
        CASE
            WHEN (a.catalog <= b.catalog) THEN b.entity_id
            ELSE a.entity_id
        END AS entity_id_b,
        CASE
            WHEN (a.catalog <= b.catalog) THEN b.entity_label
            ELSE a.entity_label
        END AS entity_label_b,
    a.alias_folded,
        CASE
            WHEN (a.catalog <= b.catalog) THEN a.alias
            ELSE b.alias
        END AS alias_a,
        CASE
            WHEN (a.catalog <= b.catalog) THEN b.alias
            ELSE a.alias
        END AS alias_b
   FROM (supplements.substance_aliases a
     JOIN supplements.substance_aliases b ON (((b.alias_folded = a.alias_folded) AND (b.catalog <> a.catalog) AND (ROW(a.catalog, a.entity_id) < ROW(b.catalog, b.entity_id)))));


ALTER VIEW supplements.substance_alias_matches OWNER TO postgres;

