--
-- Name: stack_item_substance_matches; Type: VIEW; Schema: supplements; Owner: postgres
--

CREATE VIEW supplements.stack_item_substance_matches WITH (security_invoker='true') AS
 SELECT DISTINCT us.user_id,
    si.id AS stack_item_id,
    si.is_active,
    sc.slug AS supplement_slug,
    sc.name AS supplement_name,
        CASE
            WHEN (m.catalog_a = 'kimi_substance'::text) THEN m.entity_id_a
            ELSE m.entity_id_b
        END AS kimi_substance_id,
        CASE
            WHEN (m.catalog_a = 'kimi_substance'::text) THEN m.entity_label_a
            ELSE m.entity_label_b
        END AS kimi_substance_name,
    m.alias_folded,
        CASE
            WHEN (m.catalog_a = 'lumeos_supplement_catalog'::text) THEN m.alias_a
            ELSE m.alias_b
        END AS local_alias,
        CASE
            WHEN (m.catalog_a = 'kimi_substance'::text) THEN m.alias_a
            ELSE m.alias_b
        END AS kimi_alias
   FROM (((supplements.user_stacks us
     JOIN supplements.stack_items si ON ((si.stack_id = us.id)))
     JOIN supplements.supplement_catalog sc ON ((sc.id = si.supplement_id)))
     JOIN supplements.substance_alias_matches m ON ((((m.catalog_a = 'lumeos_supplement_catalog'::text) AND (m.catalog_b = 'kimi_substance'::text) AND (m.entity_id_a = sc.slug)) OR ((m.catalog_a = 'kimi_substance'::text) AND (m.catalog_b = 'lumeos_supplement_catalog'::text) AND (m.entity_id_b = sc.slug)))));


