CREATE TABLE supplements.substance_catalog (
    id text NOT NULL,
    canonical_name text NOT NULL,
    domain text NOT NULL,
    compound_type text,
    category text,
    subcategory text,
    chemical_form text,
    aliases text[] DEFAULT '{}'::text[] NOT NULL,
    cas_number text,
    external_ids jsonb DEFAULT '{}'::jsonb NOT NULL,
    platform_classes text[] DEFAULT '{}'::text[] NOT NULL,
    platform jsonb DEFAULT '{}'::jsonb NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    official_label_dose jsonb,
    guideline_dose jsonb,
    tolerable_upper_intake_level jsonb,
    studied_dose_ranges jsonb DEFAULT '[]'::jsonb NOT NULL,
    anecdotal_dose_ranges jsonb DEFAULT '[]'::jsonb NOT NULL,
    dosing jsonb DEFAULT '{}'::jsonb NOT NULL,
    pharmacology jsonb DEFAULT '{}'::jsonb NOT NULL,
    half_life jsonb,
    half_life_status text NOT NULL,
    cyp jsonb DEFAULT '{}'::jsonb NOT NULL,
    lab_effects jsonb DEFAULT '[]'::jsonb NOT NULL,
    nutrients_provided jsonb DEFAULT '{}'::jsonb NOT NULL,
    nutrient_mapping_status text NOT NULL,
    source_primary text NOT NULL,
    raw jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    safety jsonb,
    canonical_category text,
    canonical_compound_type text,
    canonical_routes text[],
    interactions jsonb,
    regulatory jsonb,
    quality jsonb,
    warning_triggers jsonb,
    evidence_provenance jsonb,
    wada_status text,
    prescription_required boolean,
    dose_ceiling_value numeric,
    dose_ceiling_unit text,
    recommendable boolean,
    warning_only boolean,
    physician_referral boolean,
    athlete_flag boolean,
    missing_fields jsonb,
    missing_reason jsonb,
    last_verified date,
    needs_review jsonb,
    confidence numeric,
    source_count integer,
    primary_source_count integer,
    unii text,
    pubchem_cid bigint,
    chembl_id text,
    inchikey text,
    molecular_formula text,
    cas_candidates text[],
    molecular_weight numeric,
    peptide_sequence text,
    gruppe text,
    kategorie text,
    description text,
    monitoring jsonb,
    filter text,
    CONSTRAINT substance_catalog_anecdotal_dose_ranges_check CHECK ((jsonb_typeof(anecdotal_dose_ranges) = 'array'::text)),
    CONSTRAINT substance_catalog_canonical_name_check CHECK ((btrim(canonical_name) <> ''::text)),
    CONSTRAINT substance_catalog_confidence_range_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))),
    CONSTRAINT substance_catalog_cyp_check CHECK ((jsonb_typeof(cyp) = 'object'::text)),
    CONSTRAINT substance_catalog_domain_check CHECK ((domain = ANY (ARRAY['kimi_supplement'::text, 'kimi_peptide'::text, 'kimi_performance'::text, 'lumeos_local'::text, 'f05_candidate'::text]))),
    CONSTRAINT substance_catalog_dosing_check CHECK ((jsonb_typeof(dosing) = 'object'::text)),
    CONSTRAINT substance_catalog_evidence_check CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT substance_catalog_evidence_provenance_json_check CHECK (((evidence_provenance IS NULL) OR (jsonb_typeof(evidence_provenance) = 'object'::text))),
    CONSTRAINT substance_catalog_external_ids_check CHECK ((jsonb_typeof(external_ids) = 'object'::text)),
    CONSTRAINT substance_catalog_filter_not_blank_check CHECK (((filter IS NULL) OR (btrim(filter) <> ''::text))),
    CONSTRAINT substance_catalog_gruppe_check CHECK (((gruppe IS NULL) OR (gruppe = ANY (ARRAY['supplement'::text, 'peptide'::text, 'enhanced'::text])))),
    CONSTRAINT substance_catalog_guideline_dose_check CHECK (((guideline_dose IS NULL) OR (jsonb_typeof(guideline_dose) = ANY (ARRAY['string'::text, 'number'::text, 'object'::text, 'array'::text])))),
    CONSTRAINT substance_catalog_half_life_check CHECK (((half_life IS NULL) OR (jsonb_typeof(half_life) = ANY (ARRAY['string'::text, 'number'::text, 'object'::text, 'array'::text])))),
    CONSTRAINT substance_catalog_interactions_json_check CHECK (((interactions IS NULL) OR (jsonb_typeof(interactions) = 'object'::text))),
    CONSTRAINT substance_catalog_kategorie_not_blank_check CHECK (((kategorie IS NULL) OR (btrim(kategorie) <> ''::text))),
    CONSTRAINT substance_catalog_lab_effects_check CHECK ((jsonb_typeof(lab_effects) = 'array'::text)),
    CONSTRAINT substance_catalog_missing_fields_json_check CHECK (((missing_fields IS NULL) OR (jsonb_typeof(missing_fields) = 'array'::text))),
    CONSTRAINT substance_catalog_missing_reason_json_check CHECK (((missing_reason IS NULL) OR (jsonb_typeof(missing_reason) = 'object'::text))),
    CONSTRAINT substance_catalog_monitoring_json_check CHECK (((monitoring IS NULL) OR (jsonb_typeof(monitoring) = 'object'::text))),
    CONSTRAINT substance_catalog_needs_review_json_check CHECK (((needs_review IS NULL) OR (jsonb_typeof(needs_review) = 'array'::text))),
    CONSTRAINT substance_catalog_nutrients_provided_check CHECK ((jsonb_typeof(nutrients_provided) = 'object'::text)),
    CONSTRAINT substance_catalog_official_label_dose_check CHECK (((official_label_dose IS NULL) OR (jsonb_typeof(official_label_dose) = ANY (ARRAY['string'::text, 'number'::text, 'object'::text, 'array'::text])))),
    CONSTRAINT substance_catalog_pharmacology_check CHECK ((jsonb_typeof(pharmacology) = 'object'::text)),
    CONSTRAINT substance_catalog_platform_check CHECK ((jsonb_typeof(platform) = 'object'::text)),
    CONSTRAINT substance_catalog_primary_source_count_check CHECK (((primary_source_count IS NULL) OR (primary_source_count >= 0))),
    CONSTRAINT substance_catalog_quality_json_check CHECK (((quality IS NULL) OR (jsonb_typeof(quality) = 'object'::text))),
    CONSTRAINT substance_catalog_raw_check CHECK ((jsonb_typeof(raw) = 'object'::text)),
    CONSTRAINT substance_catalog_regulatory_json_check CHECK (((regulatory IS NULL) OR (jsonb_typeof(regulatory) = 'object'::text))),
    CONSTRAINT substance_catalog_safety_json_check CHECK (((safety IS NULL) OR (jsonb_typeof(safety) = 'object'::text))),
    CONSTRAINT substance_catalog_source_count_check CHECK (((source_count IS NULL) OR (source_count >= 0))),
    CONSTRAINT substance_catalog_studied_dose_ranges_check CHECK ((jsonb_typeof(studied_dose_ranges) = 'array'::text)),
    CONSTRAINT substance_catalog_tolerable_upper_intake_level_check CHECK (((tolerable_upper_intake_level IS NULL) OR (jsonb_typeof(tolerable_upper_intake_level) = ANY (ARRAY['string'::text, 'number'::text, 'object'::text, 'array'::text])))),
    CONSTRAINT substance_catalog_wada_status_check CHECK (((wada_status IS NULL) OR (wada_status = ANY (ARRAY['prohibited'::text, 'monitored'::text, 'not_prohibited'::text])))),
    CONSTRAINT substance_catalog_warning_triggers_json_check CHECK (((warning_triggers IS NULL) OR (jsonb_typeof(warning_triggers) = 'object'::text)))
);


ALTER TABLE supplements.substance_catalog OWNER TO postgres;

