    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT substance_catalog_sources_field_sources_check CHECK ((jsonb_typeof(field_sources) = 'object'::text)),
    CONSTRAINT substance_catalog_sources_raw_check CHECK ((jsonb_typeof(raw) = 'object'::text)),
    CONSTRAINT substance_catalog_sources_source_catalog_check CHECK ((source_catalog = ANY (ARRAY['kimi_supplement'::text, 'kimi_peptide'::text, 'kimi_performance'::text, 'lumeos_supplement_catalog'::text, 'f05_substance_candidate'::text, 'cross_domain_substance_mapping'::text])))
);


ALTER TABLE supplements.substance_catalog_sources OWNER TO postgres;

--
-- Name: substance_lab_effects; Type: TABLE; Schema: supplements; Owner: postgres
--

CREATE TABLE supplements.substance_lab_effects (
    id text NOT NULL,
    substance_id text NOT NULL,
    substance_name text NOT NULL,
    effect_index integer NOT NULL,
    marker_index integer NOT NULL,
    lab_marker_id text,
    loinc_code text,
    effect_type text NOT NULL,
    direction text,
    direction_enum text,
    mechanism text,
    clinical_consequence text,
    evidence text,
    monitoring_link text,
    source text,
    mapping_status text NOT NULL,
    raw jsonb DEFAULT '{}'::jsonb NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT substance_lab_effects_check CHECK ((((mapping_status = 'loinc_validated'::text) AND (lab_marker_id IS NOT NULL) AND (loinc_code IS NOT NULL)) OR ((mapping_status = 'marker_without_loinc'::text) AND (lab_marker_id IS NOT NULL) AND (loinc_code IS NULL)) OR ((mapping_status = 'effect_without_marker_id'::text) AND (lab_marker_id IS NULL) AND (loinc_code IS NULL)))),
    CONSTRAINT substance_lab_effects_direction_enum_check CHECK ((direction_enum = ANY (ARRAY['increase'::text, 'decrease'::text, 'monitor'::text, 'false_low'::text, 'false_high'::text, 'interference_unspecified'::text, 'unaffected'::text]))),
    CONSTRAINT substance_lab_effects_effect_index_check CHECK ((effect_index >= 0)),
    CONSTRAINT substance_lab_effects_effect_type_check CHECK ((effect_type = ANY (ARRAY['physiological_lab_effect'::text, 'monitoring_requirement'::text, 'assay_interference'::text]))),
    CONSTRAINT substance_lab_effects_mapping_status_check CHECK ((mapping_status = ANY (ARRAY['loinc_validated'::text, 'marker_without_loinc'::text, 'effect_without_marker_id'::text]))),
    CONSTRAINT substance_lab_effects_marker_index_check CHECK ((marker_index >= 0)),
    CONSTRAINT substance_lab_effects_raw_check CHECK ((jsonb_typeof(raw) = 'object'::text))
);


ALTER TABLE supplements.substance_lab_effects OWNER TO postgres;

--
-- Name: TABLE substance_lab_effects; Type: COMMENT; Schema: supplements; Owner: postgres
