    location text,
    notes text,
    duration_minutes integer,
    total_volume_kg numeric(12,2) DEFAULT 0 NOT NULL,
    total_sets integer DEFAULT 0 NOT NULL,
    total_reps integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    measurement_source text DEFAULT 'manual'::text NOT NULL,
    source_detail text,
    CONSTRAINT workout_sessions_check CHECK (((ended_time IS NULL) OR (ended_time >= started_time))),
    CONSTRAINT workout_sessions_duration_minutes_check CHECK (((duration_minutes IS NULL) OR (duration_minutes >= 0))),
    CONSTRAINT workout_sessions_measurement_source_ck CHECK ((measurement_source = ANY (ARRAY['manual'::text, 'device'::text, 'import'::text, 'admin'::text, 'seed'::text]))),
    CONSTRAINT workout_sessions_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'active'::text, 'completed'::text, 'cancelled'::text])))
);


ALTER TABLE training.workout_sessions OWNER TO postgres;

--
-- Name: COLUMN workout_sessions.measurement_source; Type: COMMENT; Schema: training; Owner: postgres
--

COMMENT ON COLUMN training.workout_sessions.measurement_source IS 'Herkunft der Trainingseinheit, z. B. manuelle Eingabe, Geraet oder Import.';


--
-- Name: COLUMN workout_sessions.source_detail; Type: COMMENT; Schema: training; Owner: postgres
--

COMMENT ON COLUMN training.workout_sessions.source_detail IS 'Optionales Detail zur Herkunft, z. B. Geraet, Importpfad oder App-Version.';


--
-- Name: workout_sets; Type: TABLE; Schema: training; Owner: postgres
--

CREATE TABLE training.workout_sets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workout_exercise_id uuid NOT NULL,
    set_number smallint NOT NULL,
    reps integer,
    weight_kg numeric(8,2),
    duration_seconds integer,
    distance_meters numeric(10,2),
    rpe numeric(3,1),
    rir smallint,
    set_type text DEFAULT 'working'::text NOT NULL,
    rest_seconds integer,
    notes text,
    logged_via text DEFAULT 'manual'::text NOT NULL,
    completed_at timestamp with time zone DEFAULT now() NOT NULL,
    volume_kg numeric(12,2),
    estimated_1rm numeric(8,2),
    is_pr boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    measurement_source text DEFAULT 'manual'::text NOT NULL,
    source_detail text,
    CONSTRAINT workout_sets_check CHECK (((reps IS NOT NULL) OR (duration_seconds IS NOT NULL) OR (distance_meters IS NOT NULL))),
    CONSTRAINT workout_sets_distance_meters_check CHECK (((distance_meters IS NULL) OR (distance_meters >= (0)::numeric))),
    CONSTRAINT workout_sets_duration_seconds_check CHECK (((duration_seconds IS NULL) OR (duration_seconds > 0))),
    CONSTRAINT workout_sets_logged_via_check CHECK ((logged_via = ANY (ARRAY['manual'::text, 'voice'::text, 'auto'::text]))),
    CONSTRAINT workout_sets_measurement_source_ck CHECK ((measurement_source = ANY (ARRAY['manual'::text, 'device'::text, 'import'::text, 'admin'::text, 'seed'::text]))),
    CONSTRAINT workout_sets_reps_check CHECK (((reps IS NULL) OR (reps > 0))),
    CONSTRAINT workout_sets_rest_seconds_check CHECK (((rest_seconds IS NULL) OR (rest_seconds >= 0))),
    CONSTRAINT workout_sets_rir_check CHECK (((rir IS NULL) OR ((rir >= 0) AND (rir <= 10)))),
    CONSTRAINT workout_sets_rpe_check CHECK (((rpe IS NULL) OR ((rpe >= (1)::numeric) AND (rpe <= (10)::numeric)))),
    CONSTRAINT workout_sets_set_number_check CHECK ((set_number > 0)),
    CONSTRAINT workout_sets_set_type_check CHECK ((set_type = ANY (ARRAY['working'::text, 'warmup'::text, 'dropset'::text, 'failure'::text]))),
    CONSTRAINT workout_sets_weight_kg_check CHECK (((weight_kg IS NULL) OR (weight_kg >= (0)::numeric)))
);


ALTER TABLE training.workout_sets OWNER TO postgres;

--
-- Name: COLUMN workout_sets.measurement_source; Type: COMMENT; Schema: training; Owner: postgres
--

COMMENT ON COLUMN training.workout_sets.measurement_source IS 'Herkunft des Satzwerts. logged_via bleibt der Bedienweg manual/voice/auto.';


--
-- Name: COLUMN workout_sets.source_detail; Type: COMMENT; Schema: training; Owner: postgres
--

COMMENT ON COLUMN training.workout_sets.source_detail IS 'Optionales Detail zur Herkunft, z. B. Geraet, Importpfad oder App-Version.';


